/**
 * Vue Router配置文件
 * 功能：配置应用路由，定义页面导航
 */
import { createRouter, createWebHashHistory } from 'vue-router'
import ServerList from '../views/ServerList.vue'
import ServerDetail from '../views/ServerDetail.vue'
import Kline from '../views/Kline.vue'
import RealTimeQuote from '../views/RealTimeQuote.vue'
import StockList from '../views/StockList.vue'
import CacheManager from '../views/CacheManager.vue'
import CompanyInfo from '../views/CompanyInfo.vue'
import StockNote from '../views/StockNote.vue'
import SchedulerManager from '../views/SchedulerManager.vue'
import StockTag from '../views/StockTag.vue'
import DbManager from '../views/DbManager.vue'
import StockTheme from '../views/StockTheme.vue'
import F10Parser from '../views/F10Parser.vue'

// 路由配置
const routes = [
  {
    path: '/',
    name: 'Home',
    redirect: '/servers'
  },
  {
    path: '/servers',
    name: 'ServerList',
    component: ServerList,
    meta: { title: '服务器列表' }
  },
  {
    path: '/servers/:id',
    name: 'ServerDetail',
    component: ServerDetail,
    meta: { title: '服务器详情' },
    props: true
  },
  {
    path: '/kline',
    name: 'Kline',
    component: Kline,
    meta: { title: 'K线图' }
  },
  {
    path: '/realtime',
    name: 'RealTimeQuote',
    component: RealTimeQuote,
    meta: { title: '实时行情' }
  },
  {
    path: '/stocks',
    name: 'StockList',
    component: StockList,
    meta: { title: '股票列表' }
  },
  {
    path: '/cache',
    name: 'CacheManager',
    component: CacheManager,
    meta: { title: '缓存管理' }
  },
  {
    path: '/company',
    name: 'CompanyInfo',
    component: CompanyInfo,
    meta: { title: 'F10公司资料' }
  },
  {
    path: '/stock-note',
    name: 'StockNote',
    component: StockNote,
    meta: { title: '持仓笔记' }
  },
  {
    path: '/scheduler',
    name: 'SchedulerManager',
    component: SchedulerManager,
    meta: { title: '定时任务' }
  },
  {
    path: '/stock-tag',
    name: 'StockTag',
    component: StockTag,
    meta: { title: '标签管理' }
  },
  {
    path: '/db-manager',
    name: 'DbManager',
    component: DbManager,
    meta: { title: '数据库管理' }
  },
  {
    path: '/stock-theme-search',
    name: 'StockTheme',
    component: StockTheme,
    meta: { title: '题材检索' }
  },
  {
    path: '/f10-parser',
    name: 'F10Parser',
    component: F10Parser,
    meta: { title: 'F10解析器' }
  }
]

// 创建路由实例
const router = createRouter({
  history: createWebHashHistory(process.env.BASE_URL),
  routes
})

// 路由守卫，设置页面标题
router.beforeEach((to, from, next) => {
  if (to.meta && to.meta.title) {
    document.title = to.meta.title + ' - MooTDX服务器管理'
  }
  next()
})

export default router
