/**
 * 数据库管理API接口
 * 提供表管理、SQL执行、历史记录等功能
 */

import axios from 'axios'

const BASE_URL = process.env.VUE_APP_API_URL || 'http://localhost:8080'

const apiClient = axios.create({
  baseURL: BASE_URL,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json'
  }
})

// 请求拦截器
apiClient.interceptors.request.use(
  config => {
    console.log(`[API请求] ${config.method.toUpperCase()} ${config.url}`)
    return config
  },
  error => {
    console.error('[API请求错误]', error)
    return Promise.reject(error)
  }
)

// 响应拦截器
apiClient.interceptors.response.use(
  response => {
    console.log(`[API响应] ${response.config.url}`, response.data)
    const data = response.data
    if (data.code !== 200) {
      return Promise.reject(new Error(data.message || '操作失败'))
    }
    return data
  },
  error => {
    console.error('[API响应错误]', error)
    const message = error.response?.data?.message || error.message || '网络请求失败'
    return Promise.reject(new Error(message))
  }
)

/**
 * 获取所有数据库表
 */
export function getTables() {
  return apiClient.get('/api/db-manager/tables')
}

/**
 * 刷新表列表并检测新增表
 */
export function refreshTables() {
  return apiClient.post('/api/db-manager/tables/refresh')
}

/**
 * 获取新增表列表
 */
export function getNewTables() {
  return apiClient.get('/api/db-manager/tables/new')
}

/**
 * 获取表结构
 * @param {string} tableName - 表名
 */
export function getTableStructure(tableName) {
  return apiClient.get(`/api/db-manager/tables/${tableName}/structure`)
}

/**
 * 获取表数据
 * @param {string} tableName - 表名
 * @param {Object} params - {page, pageSize, sortColumn, sortOrder}
 */
export function getTableData(tableName, params = {}) {
  return apiClient.get(`/api/db-manager/tables/${tableName}/data`, { params })
}

/**
 * 执行SQL
 * @param {Object} data - {sql, params}
 */
export function executeSql(data) {
  return apiClient.post('/api/db-manager/execute', data)
}

/**
 * 批量执行SQL
 * @param {Object} data - {statements: [], mode: 'single'|'batch'|'transaction'}
 */
export function executeBatchSql(data) {
  return apiClient.post('/api/db-manager/execute-batch', data)
}

/**
 * 获取SQL执行历史
 * @param {number} limit - 限制条数
 */
export function getSqlHistory(limit = 50) {
  return apiClient.get('/api/db-manager/sql-history', { params: { limit } })
}

/**
 * 清空SQL执行历史
 */
export function clearSqlHistory() {
  return apiClient.delete('/api/db-manager/sql-history')
}

/**
 * 获取SQL模板
 */
export function getSqlTemplates() {
  return apiClient.get('/api/db-manager/sql-templates')
}

/**
 * 应用SQL模板
 * @param {Object} data - {template_id, table_name}
 */
export function applySqlTemplate(data) {
  return apiClient.post('/api/db-manager/sql-templates/apply', data)
}

export default {
  getTables,
  refreshTables,
  getNewTables,
  getTableStructure,
  getTableData,
  executeSql,
  executeBatchSql,
  getSqlHistory,
  clearSqlHistory,
  getSqlTemplates,
  applySqlTemplate
}
