<template>
  <!-- 股本结构面板组件 - 展示公司股本相关信息 -->
  <div class="shares-panel">
    <!-- 股本概览 -->
    <el-row :gutter="20" class="shares-overview">
      <el-col :span="8">
        <el-card class="shares-card total" shadow="hover">
          <div class="shares-icon">
            <el-icon><Coin /></el-icon>
          </div>
          <div class="shares-info">
            <div class="shares-label">总股本</div>
            <div class="shares-value">{{ data.totalSharesFormatted || '-' }}</div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="8">
        <el-card class="shares-card circulating" shadow="hover">
          <div class="shares-icon">
            <el-icon><Money /></el-icon>
          </div>
          <div class="shares-info">
            <div class="shares-label">流通股本</div>
            <div class="shares-value">{{ data.circulatingSharesFormatted || '-' }}</div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="8">
        <el-card class="shares-card restricted" shadow="hover">
          <div class="shares-icon">
            <el-icon><Lock /></el-icon>
          </div>
          <div class="shares-info">
            <div class="shares-label">限售股本</div>
            <div class="shares-value">{{ calculateRestrictedShares() }}</div>
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 股本结构图表 -->
    <el-row :gutter="20" class="chart-section">
      <el-col :span="12">
        <el-card class="chart-card" shadow="hover">
          <template #header>
            <div class="card-header">
              <el-icon><PieChart /></el-icon>
              <span>股本结构分布</span>
            </div>
          </template>
          <div ref="pieChart" class="chart-container"></div>
        </el-card>
      </el-col>
      <el-col :span="12">
        <el-card class="chart-card" shadow="hover">
          <template #header>
            <div class="card-header">
              <el-icon><User /></el-icon>
              <span>股东情况</span>
            </div>
          </template>
          <el-descriptions :column="1" border>
            <el-descriptions-item label="股东总数">
              {{ data.totalShareholders ? data.totalShareholders + ' 户' : '-' }}
            </el-descriptions-item>
            <el-descriptions-item label="机构股东数">
              {{ data.institutionalShareholders ? data.institutionalShareholders + ' 户' : '-' }}
            </el-descriptions-item>
            <el-descriptions-item label="人均持股">
              {{ calculateAvgShares() }}
            </el-descriptions-item>
          </el-descriptions>

          <!-- 股东变化趋势提示 -->
          <div class="shareholder-trend">
            <el-alert
              v-if="data.totalShareholders"
              :title="`股东总数: ${data.totalShareholders} 户`"
              type="info"
              :closable="false"
              show-icon
            />
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 股本变动历史 -->
    <el-card class="history-card" shadow="hover">
      <template #header>
        <div class="card-header">
          <el-icon><Timer /></el-icon>
          <span>股本变动说明</span>
        </div>
      </template>
      <div class="history-content">
        <el-empty v-if="!hasHistoryData" description="暂无股本变动数据" />
        <div v-else class="history-list">
          <el-timeline>
            <el-timeline-item
              v-if="data.listingDate"
              type="primary"
              :timestamp="data.listingDate"
            >
              <h4>上市发行</h4>
              <p>公司正式上市，发行 {{ data.totalSharesFormatted || '-' }} 股</p>
            </el-timeline-item>
          </el-timeline>
        </div>
      </div>
    </el-card>
  </div>
</template>

<script>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { Coin, Money, Lock, PieChart, User, Timer } from '@element-plus/icons-vue'
import * as echarts from 'echarts'

export default {
  name: 'SharesPanel',

  components: {
    Coin,
    Money,
    Lock,
    PieChart,
    User,
    Timer
  },

  props: {
    data: {
      type: Object,
      required: true
    }
  },

  setup(props) {
    const pieChart = ref(null)
    let chartInstance = null

    /**
     * 计算限售股本
     */
    const calculateRestrictedShares = () => {
      const total = props.data.totalShares
      const circulating = props.data.circulatingShares
      if (!total || !circulating) return '-'
      const restricted = total - circulating
      if (restricted >= 100000000) {
        return (restricted / 100000000).toFixed(2) + '亿股'
      } else if (restricted >= 10000) {
        return (restricted / 10000).toFixed(2) + '万股'
      }
      return restricted.toString()
    }

    /**
     * 计算人均持股
     */
    const calculateAvgShares = () => {
      const total = props.data.totalShares
      const shareholders = props.data.totalShareholders
      if (!total || !shareholders || shareholders === 0) return '-'
      const avg = total / shareholders
      if (avg >= 10000) {
        return (avg / 10000).toFixed(2) + '万股/人'
      }
      return Math.round(avg) + '股/人'
    }

    /**
     * 是否有历史数据
     */
    const hasHistoryData = computed(() => {
      return props.data.listingDate
    })

    /**
     * 初始化饼图
     */
    const initPieChart = () => {
      if (!pieChart.value) return

      chartInstance = echarts.init(pieChart.value)

      const total = props.data.totalShares || 0
      const circulating = props.data.circulatingShares || 0
      const restricted = total - circulating

      const option = {
        tooltip: {
          trigger: 'item',
          formatter: '{b}: {c} ({d}%)'
        },
        legend: {
          orient: 'vertical',
          left: 'left',
          top: 'center'
        },
        series: [
          {
            name: '股本结构',
            type: 'pie',
            radius: ['40%', '70%'],
            center: ['60%', '50%'],
            avoidLabelOverlap: false,
            itemStyle: {
              borderRadius: 10,
              borderColor: '#fff',
              borderWidth: 2
            },
            label: {
              show: true,
              formatter: '{b}\n{d}%'
            },
            emphasis: {
              label: {
                show: true,
                fontSize: 16,
                fontWeight: 'bold'
              }
            },
            data: [
              {
                value: circulating,
                name: '流通股本',
                itemStyle: { color: '#67c23a' }
              },
              {
                value: restricted > 0 ? restricted : 0,
                name: '限售股本',
                itemStyle: { color: '#e6a23c' }
              }
            ]
          }
        ]
      }

      chartInstance.setOption(option)
    }

    /**
     * 处理窗口大小变化
     */
    const handleResize = () => {
      if (chartInstance) {
        chartInstance.resize()
      }
    }

    onMounted(() => {
      initPieChart()
      window.addEventListener('resize', handleResize)
    })

    onUnmounted(() => {
      window.removeEventListener('resize', handleResize)
      if (chartInstance) {
        chartInstance.dispose()
      }
    })

    return {
      pieChart,
      calculateRestrictedShares,
      calculateAvgShares,
      hasHistoryData
    }
  }
}
</script>

