<template>
  <!-- 实时行情页面 -->
  <div class="realtime-quote-page">
    <!-- 页面标题 -->
    <div class="page-header">
      <h1 class="page-title">
        <el-icon><TrendCharts /></el-icon>
        实时行情
      </h1>
      <div class="page-actions">
        <el-button type="primary" @click="refreshAll" :loading="loading">
          <el-icon><Refresh /></el-icon>
          刷新全部
        </el-button>
        <el-button @click="showAddDialog">
          <el-icon><Plus /></el-icon>
          添加自选
        </el-button>
      </div>
    </div>

    <!-- 市场概览卡片 -->
    <el-row :gutter="20" class="market-overview">
      <el-col :span="6" v-for="item in marketIndices" :key="item.code">
        <el-card class="index-card" :class="item.change >= 0 ? 'up' : 'down'">
          <div class="index-name">{{ item.name }}</div>
          <div class="index-price">{{ formatPrice(item.price) }}</div>
          <div class="index-change">
            <span :class="item.change >= 0 ? 'up-text' : 'down-text'">
              {{ item.change >= 0 ? '+' : '' }}{{ item.change.toFixed(2) }}
              ({{ item.change >= 0 ? '+' : '' }}{{ item.changePercent.toFixed(2) }}%)
            </span>
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 自选股列表 -->
    <el-card class="quote-table-card">
      <template #header>
        <div class="card-header">
          <span>自选股</span>
          <el-radio-group v-model="refreshInterval" size="small" @change="handleIntervalChange">
            <el-radio-button :label="0">手动刷新</el-radio-button>
            <el-radio-button :label="5">5秒</el-radio-button>
            <el-radio-button :label="10">10秒</el-radio-button>
            <el-radio-button :label="30">30秒</el-radio-button>
          </el-radio-group>
        </div>
      </template>

      <el-table
        :data="watchList"
        v-loading="loading"
        stripe
        border
        style="width: 100%"
        @row-click="handleRowClick"
        highlight-current-row
      >
        <el-table-column type="index" width="50" />
        <el-table-column prop="code" label="代码" width="100" />
        <el-table-column prop="name" label="名称" width="120" />
        <el-table-column label="最新价" width="100">
          <template #default="{ row }">
            <span :class="getPriceClass(row)">{{ formatPrice(row.lastPrice) }}</span>
          </template>
        </el-table-column>
        <el-table-column label="涨跌额" width="100">
          <template #default="{ row }">
            <span :class="getPriceClass(row)">{{ formatChange(row) }}</span>
          </template>
        </el-table-column>
        <el-table-column label="涨跌幅" width="100">
          <template #default="{ row }">
            <span :class="getPriceClass(row)">{{ formatChangePercent(row) }}</span>
          </template>
        </el-table-column>
        <el-table-column label="开盘价" width="100">
          <template #default="{ row }">
            {{ formatPrice(row.open) }}
          </template>
        </el-table-column>
        <el-table-column label="最高价" width="100">
          <template #default="{ row }">
            {{ formatPrice(row.high) }}
          </template>
        </el-table-column>
        <el-table-column label="最低价" width="100">
          <template #default="{ row }">
            {{ formatPrice(row.low) }}
          </template>
        </el-table-column>
        <el-table-column label="昨收" width="100">
          <template #default="{ row }">
            {{ formatPrice(row.prevClose) }}
          </template>
        </el-table-column>
        <el-table-column label="成交量" width="120">
          <template #default="{ row }">
            {{ formatVolume(row.volume) }}
          </template>
        </el-table-column>
        <el-table-column label="成交额" min-width="120">
          <template #default="{ row }">
            {{ formatAmount(row.amount) }}
          </template>
        </el-table-column>
        <el-table-column label="操作" width="150" fixed="right">
          <template #default="{ row }">
            <el-button type="primary" size="small" @click.stop="viewKline(row)">
              K线
            </el-button>
            <el-button type="danger" size="small" @click.stop="removeFromWatch(row)">
              删除
            </el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <!-- 五档行情详情 -->
    <el-dialog
      v-model="detailDialogVisible"
      title="行情详情"
      width="600px"
    >
      <div v-if="selectedStock" class="quote-detail">
        <div class="detail-header">
          <h3>{{ selectedStock.name }} ({{ selectedStock.code }})</h3>
          <div class="detail-price" :class="getPriceClass(selectedStock)">
            {{ formatPrice(selectedStock.lastPrice) }}
          </div>
        </div>
        
        <!-- 买卖五档 -->
        <div class="bid-ask-table">
          <el-row :gutter="20">
            <el-col :span="12">
              <h4>卖盘</h4>
              <div v-for="i in 5" :key="'ask' + i" class="bid-ask-row">
                <span class="label">卖{{ 6 - i }}</span>
                <span class="price" :class="getBidAskClass(selectedStock.askPrices[5 - i], selectedStock)">
                  {{ formatPrice(selectedStock.askPrices[5 - i]) }}
                </span>
                <span class="volume">{{ formatVolume(selectedStock.askVolumes[5 - i]) }}</span>
              </div>
            </el-col>
            <el-col :span="12">
              <h4>买盘</h4>
              <div v-for="i in 5" :key="'bid' + i" class="bid-ask-row">
                <span class="label">买{{ i }}</span>
                <span class="price" :class="getBidAskClass(selectedStock.bidPrices[i - 1], selectedStock)">
                  {{ formatPrice(selectedStock.bidPrices[i - 1]) }}
                </span>
                <span class="volume">{{ formatVolume(selectedStock.bidVolumes[i - 1]) }}</span>
              </div>
            </el-col>
          </el-row>
        </div>
      </div>
    </el-dialog>

    <!-- 添加自选对话框 -->
    <el-dialog
      v-model="addDialogVisible"
      title="添加自选股"
      width="500px"
    >
      <el-form :model="addForm" label-width="80px">
        <el-form-item label="市场">
          <el-select v-model="addForm.market" placeholder="选择市场">
            <el-option label="上海" value="SH" />
            <el-option label="深圳" value="SZ" />
          </el-select>
        </el-form-item>
        <el-form-item label="股票代码">
          <el-input v-model="addForm.code" placeholder="输入股票代码" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="addDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="confirmAdd" :loading="adding">
          添加
        </el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script>
import { ref, reactive, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { TrendCharts, Refresh, Plus } from '@element-plus/icons-vue'
import { getQuotes, getQuote } from '@/api/stock'

export default {
  name: 'RealTimeQuoteView',

  components: {
    TrendCharts,
    Refresh,
    Plus
  },

  setup() {
    const router = useRouter()
    
    // 加载状态
    const loading = ref(false)
    const adding = ref(false)
    
    // 自动刷新间隔
    const refreshInterval = ref(5)
    let refreshTimer = null
    
    // 市场指数
    const marketIndices = ref([
      { name: '上证指数', code: '000001.SH', price: 0, change: 0, changePercent: 0 },
      { name: '深证成指', code: '399001.SZ', price: 0, change: 0, changePercent: 0 },
      { name: '创业板指', code: '399006.SZ', price: 0, change: 0, changePercent: 0 },
      { name: '科创50', code: '000688.SH', price: 0, change: 0, changePercent: 0 }
    ])
    
    // 自选股列表
    const watchList = ref([])
    
    // 详情对话框
    const detailDialogVisible = ref(false)
    const selectedStock = ref(null)
    
    // 添加对话框
    const addDialogVisible = ref(false)
    const addForm = reactive({
      market: 'SZ',
      code: ''
    })

    /**
     * 获取实时行情
     */
    const fetchQuotes = async () => {
      if (watchList.value.length === 0) return
      
      loading.value = true
      try {
        const codes = watchList.value.map(item => `${item.market === 'SH' ? 1 : 0}_${item.code}`)
        const response = await getQuotes(codes)
        
        if (response.data.code === 200) {
          // 更新行情数据
          const quotes = response.data.data || []
          watchList.value = watchList.value.map(item => {
            const quote = quotes.find(q => q.code === item.code)
            return quote ? { ...item, ...quote } : item
          })
        }
      } catch (error) {
        console.error('获取行情失败:', error)
      } finally {
        loading.value = false
      }
    }

    /**
     * 刷新全部
     */
    const refreshAll = () => {
      fetchQuotes()
      fetchMarketIndices()
    }

    /**
     * 获取市场指数
     */
    const fetchMarketIndices = async () => {
      try {
        for (let index of marketIndices.value) {
          const [code, market] = index.code.split('.')
          const response = await getQuote(market, code)
          if (response.data.code === 200) {
            const quote = response.data.data
            index.price = parseFloat(quote.lastPrice)
            index.change = parseFloat(quote.lastPrice) - parseFloat(quote.prevClose)
            index.changePercent = (index.change / parseFloat(quote.prevClose)) * 100
          }
        }
      } catch (error) {
        console.error('获取指数失败:', error)
      }
    }

    /**
     * 处理刷新间隔变化
     */
    const handleIntervalChange = () => {
      clearInterval(refreshTimer)
      if (refreshInterval.value > 0) {
        refreshTimer = setInterval(() => {
          fetchQuotes()
        }, refreshInterval.value * 1000)
      }
    }

    /**
     * 显示添加对话框
     */
    const showAddDialog = () => {
      addForm.market = 'SZ'
      addForm.code = ''
      addDialogVisible.value = true
    }

    /**
     * 确认添加
     */
    const confirmAdd = async () => {
      if (!addForm.code) {
        ElMessage.warning('请输入股票代码')
        return
      }
      
      adding.value = true
      try {
        const response = await getQuote(addForm.market, addForm.code)
        if (response.data.code === 200) {
          const quote = response.data.data
          watchList.value.push({
            ...quote,
            market: addForm.market
          })
          saveWatchList()
          ElMessage.success('添加成功')
          addDialogVisible.value = false
        } else {
          ElMessage.error('股票不存在')
        }
      } catch (error) {
        ElMessage.error('添加失败: ' + error.message)
      } finally {
        adding.value = false
      }
    }

    /**
     * 从自选删除
     */
    const removeFromWatch = (row) => {
      ElMessageBox.confirm(
        `确定从自选股中删除 ${row.name} 吗？`,
        '提示',
        { type: 'warning' }
      ).then(() => {
        watchList.value = watchList.value.filter(item => item.code !== row.code)
        saveWatchList()
        ElMessage.success('删除成功')
      })
    }

    /**
     * 查看K线
     */
    const viewKline = (row) => {
      router.push({
        path: '/kline',
        query: {
          market: row.market,
          code: row.code
        }
      })
    }

    /**
     * 处理行点击
     */
    const handleRowClick = (row) => {
      selectedStock.value = row
      detailDialogVisible.value = true
    }

    /**
     * 保存自选股列表
     */
    const saveWatchList = () => {
      localStorage.setItem('watchList', JSON.stringify(watchList.value.map(item => ({
        code: item.code,
        market: item.market,
        name: item.name
      }))))
    }

    /**
     * 加载自选股列表
     */
    const loadWatchList = () => {
      const saved = localStorage.getItem('watchList')
      if (saved) {
        watchList.value = JSON.parse(saved)
        fetchQuotes()
      }
    }

    /**
     * 格式化价格
     */
    const formatPrice = (price) => {
      if (price === null || price === undefined) return '-'
      return parseFloat(price).toFixed(2)
    }

    /**
     * 格式化涨跌额
     */
    const formatChange = (row) => {
      const change = parseFloat(row.lastPrice) - parseFloat(row.prevClose)
      return (change >= 0 ? '+' : '') + change.toFixed(2)
    }

    /**
     * 格式化涨跌幅
     */
    const formatChangePercent = (row) => {
      const change = parseFloat(row.lastPrice) - parseFloat(row.prevClose)
      const percent = (change / parseFloat(row.prevClose)) * 100
      return (percent >= 0 ? '+' : '') + percent.toFixed(2) + '%'
    }

    /**
     * 格式化成交量
     */
    const formatVolume = (volume) => {
      if (volume === null || volume === undefined) return '-'
      const v = parseInt(volume)
      if (v >= 100000000) {
        return (v / 100000000).toFixed(2) + '亿'
      } else if (v >= 10000) {
        return (v / 10000).toFixed(2) + '万'
      }
      return v.toString()
    }

    /**
     * 格式化成交额
     */
    const formatAmount = (amount) => {
      if (amount === null || amount === undefined) return '-'
      const a = parseFloat(amount)
      if (a >= 100000000) {
        return (a / 100000000).toFixed(2) + '亿'
      } else if (a >= 10000) {
        return (a / 10000).toFixed(2) + '万'
      }
      return a.toFixed(2)
    }

    /**
     * 获取价格样式类
     */
    const getPriceClass = (row) => {
      const change = parseFloat(row.lastPrice) - parseFloat(row.prevClose)
      return change >= 0 ? 'up-text' : 'down-text'
    }

    /**
     * 获取买卖盘价格样式
     */
    const getBidAskClass = (price, row) => {
      const change = parseFloat(price) - parseFloat(row.prevClose)
      return change >= 0 ? 'up-text' : 'down-text'
    }

    onMounted(() => {
      loadWatchList()
      fetchMarketIndices()
      handleIntervalChange()
    })

    onUnmounted(() => {
      clearInterval(refreshTimer)
    })

    return {
      loading,
      adding,
      refreshInterval,
      marketIndices,
      watchList,
      detailDialogVisible,
      selectedStock,
      addDialogVisible,
      addForm,
      refreshAll,
      handleIntervalChange,
      showAddDialog,
      confirmAdd,
      removeFromWatch,
      viewKline,
      handleRowClick,
      formatPrice,
      formatChange,
      formatChangePercent,
      formatVolume,
      formatAmount,
      getPriceClass,
      getBidAskClass
    }
  }
}
</script>

