<template>
  <div class="stock-note-container">
    <h1>持仓笔记</h1>
    
    <!-- 汇总统计卡片 -->
    <el-row :gutter="20" class="summary-cards">
      <el-col :span="6">
        <el-card class="summary-card">
          <div class="summary-label">总成本</div>
          <div class="summary-value">{{ formatMoney(summary.totalCost) }}</div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card class="summary-card">
          <div class="summary-label">总市值</div>
          <div class="summary-value">{{ formatMoney(summary.totalMarketValue) }}</div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card class="summary-card">
          <div class="summary-label">总盈亏</div>
          <div class="summary-value" :class="getProfitClass(summary.totalProfit)">
            {{ formatMoney(summary.totalProfit) }}
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card class="summary-card">
          <div class="summary-label">盈亏率</div>
          <div class="summary-value" :class="getProfitClass(summary.totalProfitRate)">
            {{ formatPercent(summary.totalProfitRate) }}
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 操作栏 -->
    <div class="operation-bar">
      <el-button type="primary" @click="showAddPositionDialog">
        <el-icon><Plus /></el-icon> 添加持仓
      </el-button>
      <el-button @click="showPlatformDialog">
        <el-icon><Setting /></el-icon> 平台管理
      </el-button>
      <el-select v-model="filter.platformId" placeholder="选择平台" clearable @change="handleFilterChange">
        <el-option
          v-for="platform in platforms"
          :key="platform.id"
          :label="platform.name"
          :value="platform.id"
        />
      </el-select>
      <el-select v-model="filter.status" placeholder="选择状态" clearable @change="handleFilterChange">
        <el-option label="持仓中" value="holding" />
        <el-option label="部分卖出" value="partial" />
        <el-option label="已清仓" value="sold" />
      </el-select>
      <el-input
        v-model="filter.code"
        placeholder="股票代码"
        clearable
        style="width: 150px"
        @change="handleFilterChange"
      />
      <el-button @click="refreshData">
        <el-icon><Refresh /></el-icon> 刷新
      </el-button>
    </div>

    <!-- 持仓列表 -->
    <el-table :data="positions" v-loading="loading" border stripe>
      <el-table-column type="index" width="50" />
      <el-table-column prop="code" label="股票代码" width="100" />
      <el-table-column prop="name" label="股票名称" width="120" />
      <el-table-column prop="market" label="市场" width="80">
        <template #default="{ row }">
          <el-tag :type="row.market === 'SH' ? 'danger' : 'success'">{{ row.market }}</el-tag>
        </template>
      </el-table-column>
      <el-table-column prop="platformName" label="所属平台" width="120" />
      <el-table-column label="买入信息" min-width="200">
        <template #default="{ row }">
          <div>价格: {{ row.buyPrice }}</div>
          <div>数量: {{ row.buyQuantity }}</div>
          <div>日期: {{ row.buyDate }}</div>
        </template>
      </el-table-column>
      <el-table-column label="当前持仓" width="120">
        <template #default="{ row }">
          <div>{{ row.currentQuantity }} / {{ row.buyQuantity }}</div>
          <el-tag v-if="row.status === 'holding'" type="success">持仓中</el-tag>
          <el-tag v-else-if="row.status === 'partial'" type="warning">部分卖出</el-tag>
          <el-tag v-else type="info">已清仓</el-tag>
        </template>
      </el-table-column>
      <el-table-column label="成本与市值" min-width="180">
        <template #default="{ row }">
          <div>总成本: {{ formatMoney(row.totalCost) }}</div>
          <div>市值: {{ formatMoney(row.marketValue) }}</div>
        </template>
      </el-table-column>
      <el-table-column label="盈亏" min-width="150">
        <template #default="{ row }">
          <div :class="getProfitClass(row.profitAmount)">
            {{ formatMoney(row.profitAmount) }}
          </div>
          <div :class="getProfitClass(row.profitRate)">
            {{ formatPercent(row.profitRate) }}
          </div>
        </template>
      </el-table-column>
      <el-table-column label="操作" width="250" fixed="right">
        <template #default="{ row }">
          <el-button type="primary" size="small" @click="showUpdatePriceDialog(row)">
            更新价格
          </el-button>
          <el-button v-if="row.status !== 'sold'" type="warning" size="small" @click="showSellDialog(row)">
            卖出
          </el-button>
          <el-button type="danger" size="small" @click="handleDelete(row)">
            删除
          </el-button>
        </template>
      </el-table-column>
    </el-table>

    <!-- 添加持仓对话框 -->
    <el-dialog v-model="dialogs.position.visible" title="添加持仓" width="600px">
      <el-form :model="dialogs.position.form" label-width="100px">
        <el-form-item label="交易平台">
          <el-select v-model="dialogs.position.form.platformId" placeholder="选择平台">
            <el-option
              v-for="platform in platforms"
              :key="platform.id"
              :label="platform.name"
              :value="platform.id"
            />
          </el-select>
        </el-form-item>
        <el-form-item label="股票代码">
          <el-input v-model="dialogs.position.form.code" placeholder="如: 000001" />
        </el-form-item>
        <el-form-item label="市场">
          <el-radio-group v-model="dialogs.position.form.market">
            <el-radio label="SH">上海</el-radio>
            <el-radio label="SZ">深圳</el-radio>
          </el-radio-group>
        </el-form-item>
        <el-form-item label="股票名称">
          <el-input v-model="dialogs.position.form.name" placeholder="股票名称" />
        </el-form-item>
        <el-form-item label="买入价格">
          <el-input-number v-model="dialogs.position.form.buyPrice" :precision="2" :min="0.01" />
        </el-form-item>
        <el-form-item label="买入数量">
          <el-input-number v-model="dialogs.position.form.buyQuantity" :min="1" :step="100" />
        </el-form-item>
        <el-form-item label="买入日期">
          <el-date-picker v-model="dialogs.position.form.buyDate" type="date" placeholder="选择日期" />
        </el-form-item>
        <el-form-item label="交易策略">
          <el-input v-model="dialogs.position.form.strategy" placeholder="如: 价值投资" />
        </el-form-item>
        <el-form-item label="止损价">
          <el-input-number v-model="dialogs.position.form.stopLossPrice" :precision="2" :min="0" />
        </el-form-item>
        <el-form-item label="目标价">
          <el-input-number v-model="dialogs.position.form.targetPrice" :precision="2" :min="0" />
        </el-form-item>
        <el-form-item label="交易笔记">
          <el-input v-model="dialogs.position.form.notes" type="textarea" rows="3" />
        </el-form-item>
        <el-form-item label="标签">
          <el-input v-model="dialogs.position.form.tags" placeholder="逗号分隔,如: 白马股,长期持有" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="dialogs.position.visible = false">取消</el-button>
        <el-button type="primary" @click="handleAddPosition">确定</el-button>
      </template>
    </el-dialog>

    <!-- 卖出对话框 -->
    <el-dialog v-model="dialogs.sell.visible" title="卖出持仓" width="500px">
      <el-form :model="dialogs.sell.form" label-width="100px">
        <el-form-item label="股票代码">
          <span>{{ dialogs.sell.data?.code }}</span>
        </el-form-item>
        <el-form-item label="当前持仓">
          <span>{{ dialogs.sell.data?.currentQuantity }}</span>
        </el-form-item>
        <el-form-item label="卖出价格">
          <el-input-number v-model="dialogs.sell.form.sellPrice" :precision="2" :min="0.01" />
        </el-form-item>
        <el-form-item label="卖出数量">
          <el-input-number 
            v-model="dialogs.sell.form.sellQuantity" 
            :min="1" 
            :max="dialogs.sell.data?.currentQuantity"
            :step="100"
          />
          <el-checkbox v-model="dialogs.sell.all">全部卖出</el-checkbox>
        </el-form-item>
        <el-form-item label="卖出日期">
          <el-date-picker v-model="dialogs.sell.form.sellDate" type="date" placeholder="选择日期" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="dialogs.sell.visible = false">取消</el-button>
        <el-button type="primary" @click="handleSell">确定</el-button>
      </template>
    </el-dialog>

    <!-- 更新价格对话框 -->
    <el-dialog v-model="dialogs.price.visible" title="更新当前价格" width="400px">
      <el-form :model="dialogs.price.form" label-width="100px">
        <el-form-item label="股票代码">
          <span>{{ dialogs.price.data?.code }}</span>
        </el-form-item>
        <el-form-item label="当前价格">
          <el-input-number v-model="dialogs.price.form.currentPrice" :precision="2" :min="0.01" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="dialogs.price.visible = false">取消</el-button>
        <el-button type="primary" @click="handleUpdatePrice">确定</el-button>
      </template>
    </el-dialog>

    <!-- 平台管理对话框 -->
    <el-dialog v-model="dialogs.platform.visible" title="平台管理" width="700px">
      <el-button type="primary" @click="showAddPlatformDialog" style="margin-bottom: 15px">
        添加平台
      </el-button>
      <el-table :data="platforms" border stripe>
        <el-table-column prop="name" label="平台名称" />
        <el-table-column prop="accountNo" label="账户号码" />
        <el-table-column prop="accountType" label="账户类型" width="100" />
        <el-table-column label="操作" width="150">
          <template #default="{ row }">
            <el-button type="danger" size="small" @click="handleDeletePlatform(row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-dialog>

    <!-- 添加平台对话框 -->
    <el-dialog v-model="dialogs.addPlatform.visible" title="添加平台" width="500px">
      <el-form :model="dialogs.addPlatform.form" label-width="120px">
        <el-form-item label="平台名称">
          <el-input v-model="dialogs.addPlatform.form.name" placeholder="如: 华泰证券" />
        </el-form-item>
        <el-form-item label="账户号码">
          <el-input v-model="dialogs.addPlatform.form.accountNo" placeholder="账户号码" />
        </el-form-item>
        <el-form-item label="账户类型">
          <el-select v-model="dialogs.addPlatform.form.accountType">
            <el-option label="股票账户" value="stock" />
            <el-option label="融资融券" value="margin" />
            <el-option label="港股通" value="hk" />
          </el-select>
        </el-form-item>
        <el-form-item label="买入佣金费率">
          <el-input-number v-model="dialogs.addPlatform.form.buyCommissionRate" :precision="5" :min="0" :max="0.01" />
          <span class="form-tip">默认万2.5 (0.00025)</span>
        </el-form-item>
        <el-form-item label="卖出佣金费率">
          <el-input-number v-model="dialogs.addPlatform.form.sellCommissionRate" :precision="5" :min="0" :max="0.01" />
          <span class="form-tip">默认万2.5 (0.00025)</span>
        </el-form-item>
        <el-form-item label="印花税费率">
          <el-input-number v-model="dialogs.addPlatform.form.stampTaxRate" :precision="4" :min="0" :max="0.01" />
          <span class="form-tip">默认千1 (0.001)</span>
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="dialogs.addPlatform.visible = false">取消</el-button>
        <el-button type="primary" @click="handleAddPlatform">确定</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, reactive, onMounted, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Setting, Refresh } from '@element-plus/icons-vue'
import {
  getPlatforms,
  createPlatform,
  deletePlatform,
  getPositions,
  createPosition,
  updatePositionPrice,
  sellPosition,
  deletePosition,
  getSummary
} from '@/api/stockNote'

// ==================== 数据状态 ====================
const loading = ref(false)
const positions = ref([])
const platforms = ref([])
const summary = reactive({
  totalCost: 0,
  totalMarketValue: 0,
  totalProfit: 0,
  totalProfitRate: 0,
  positionCount: 0
})

const filter = reactive({
  platformId: null,
  status: null,
  code: ''
})

// ==================== 对话框状态 ====================
const dialogs = reactive({
  position: {
    visible: false,
    form: {
      platformId: null,
      code: '',
      market: 'SZ',
      name: '',
      buyPrice: 0,
      buyQuantity: 100,
      buyDate: new Date(),
      strategy: '',
      stopLossPrice: 0,
      targetPrice: 0,
      notes: '',
      tags: ''
    }
  },
  sell: {
    visible: false,
    data: null,
    all: false,
    form: {
      sellPrice: 0,
      sellQuantity: 0,
      sellDate: new Date()
    }
  },
  price: {
    visible: false,
    data: null,
    form: {
      currentPrice: 0
    }
  },
  platform: {
    visible: false
  },
  addPlatform: {
    visible: false,
    form: {
      name: '',
      accountNo: '',
      accountType: 'stock',
      buyCommissionRate: 0.00025,
      sellCommissionRate: 0.00025,
      stampTaxRate: 0.001
    }
  }
})

// ==================== 生命周期 ====================
onMounted(() => {
  loadPlatforms()
  loadPositions()
  loadSummary()
})

// ==================== 加载数据 ====================
async function loadPlatforms() {
  try {
    const res = await getPlatforms()
    if (res.data.code === 200) {
      platforms.value = res.data.data
    }
  } catch (error) {
    console.error('加载平台列表失败:', error)
  }
}

async function loadPositions() {
  loading.value = true
  try {
    const params = {}
    if (filter.platformId) params.platformId = filter.platformId
    if (filter.status) params.status = filter.status
    if (filter.code) params.code = filter.code

    const res = await getPositions(params)
    if (res.data.code === 200) {
      positions.value = res.data.data
    }
  } catch (error) {
    console.error('加载持仓列表失败:', error)
    ElMessage.error('加载持仓列表失败')
  } finally {
    loading.value = false
  }
}

async function loadSummary() {
  try {
    const res = await getSummary(filter.platformId)
    if (res.data.code === 200) {
      Object.assign(summary, res.data.data)
    }
  } catch (error) {
    console.error('加载汇总统计失败:', error)
  }
}

// ==================== 事件处理 ====================
function handleFilterChange() {
  loadPositions()
  loadSummary()
}

function refreshData() {
  loadPositions()
  loadSummary()
  ElMessage.success('数据已刷新')
}

// ==================== 持仓操作 ====================
function showAddPositionDialog() {
  dialogs.position.form = {
    platformId: platforms.value[0]?.id || null,
    code: '',
    market: 'SZ',
    name: '',
    buyPrice: 0,
    buyQuantity: 100,
    buyDate: new Date(),
    strategy: '',
    stopLossPrice: 0,
    targetPrice: 0,
    notes: '',
    tags: ''
  }
  dialogs.position.visible = true
}

async function handleAddPosition() {
  try {
    const form = dialogs.position.form
    if (!form.platformId) {
      ElMessage.warning('请选择交易平台')
      return
    }
    if (!form.code) {
      ElMessage.warning('请输入股票代码')
      return
    }
    if (form.buyPrice <= 0) {
      ElMessage.warning('买入价格必须大于0')
      return
    }
    if (form.buyQuantity <= 0) {
      ElMessage.warning('买入数量必须大于0')
      return
    }

    const res = await createPosition(form)
    if (res.data.code === 200) {
      ElMessage.success('添加持仓成功')
      dialogs.position.visible = false
      loadPositions()
      loadSummary()
    } else {
      ElMessage.error(res.data.message || '添加失败')
    }
  } catch (error) {
    console.error('添加持仓失败:', error)
    ElMessage.error('添加持仓失败')
  }
}

function showSellDialog(row) {
  dialogs.sell.data = row
  dialogs.sell.all = false
  dialogs.sell.form = {
    sellPrice: row.currentPrice || row.buyPrice,
    sellQuantity: row.currentQuantity,
    sellDate: new Date()
  }
  dialogs.sell.visible = true
}

watch(() => dialogs.sell.all, (val) => {
  if (val) {
    dialogs.sell.form.sellQuantity = dialogs.sell.data?.currentQuantity
  }
})

async function handleSell() {
  try {
    const form = dialogs.sell.form
    if (form.sellPrice <= 0) {
      ElMessage.warning('卖出价格必须大于0')
      return
    }
    if (form.sellQuantity <= 0) {
      ElMessage.warning('卖出数量必须大于0')
      return
    }

    const res = await sellPosition(dialogs.sell.data.id, form)
    if (res.data.code === 200) {
      ElMessage.success('卖出成功')
      dialogs.sell.visible = false
      loadPositions()
      loadSummary()
    } else {
      ElMessage.error(res.data.message || '卖出失败')
    }
  } catch (error) {
    console.error('卖出失败:', error)
    ElMessage.error('卖出失败')
  }
}

function showUpdatePriceDialog(row) {
  dialogs.price.data = row
  dialogs.price.form = {
    currentPrice: row.currentPrice || row.buyPrice
  }
  dialogs.price.visible = true
}

async function handleUpdatePrice() {
  try {
    const form = dialogs.price.form
    if (form.currentPrice <= 0) {
      ElMessage.warning('当前价格必须大于0')
      return
    }

    const res = await updatePositionPrice(dialogs.price.data.id, form.currentPrice)
    if (res.data.code === 200) {
      ElMessage.success('更新价格成功')
      dialogs.price.visible = false
      loadPositions()
      loadSummary()
    } else {
      ElMessage.error(res.data.message || '更新失败')
    }
  } catch (error) {
    console.error('更新价格失败:', error)
    ElMessage.error('更新价格失败')
  }
}

async function handleDelete(row) {
  try {
    await ElMessageBox.confirm('确定要删除这条持仓记录吗？', '提示', {
      confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning'
    })

    const res = await deletePosition(row.id)
    if (res.data.code === 200) {
      ElMessage.success('删除成功')
      loadPositions()
      loadSummary()
    } else {
      ElMessage.error(res.data.message || '删除失败')
    }
  } catch (error) {
    if (error !== 'cancel') {
      console.error('删除失败:', error)
      ElMessage.error('删除失败')
    }
  }
}

// ==================== 平台管理 ====================
function showPlatformDialog() {
  dialogs.platform.visible = true
}

function showAddPlatformDialog() {
  dialogs.addPlatform.form = {
    name: '',
    accountNo: '',
    accountType: 'stock',
    buyCommissionRate: 0.00025,
    sellCommissionRate: 0.00025,
    stampTaxRate: 0.001
  }
  dialogs.addPlatform.visible = true
}

async function handleAddPlatform() {
  try {
    const form = dialogs.addPlatform.form
    if (!form.name) {
      ElMessage.warning('请输入平台名称')
      return
    }

    const res = await createPlatform(form)
    if (res.data.code === 200) {
      ElMessage.success('添加平台成功')
      dialogs.addPlatform.visible = false
      loadPlatforms()
    } else {
      ElMessage.error(res.data.message || '添加失败')
    }
  } catch (error) {
    console.error('添加平台失败:', error)
    ElMessage.error('添加平台失败')
  }
}

async function handleDeletePlatform(row) {
  try {
    await ElMessageBox.confirm('确定要删除这个平台吗？', '提示', {
      confirmButtonText: '确定',
      cancelButtonText: '取消',
      type: 'warning'
    })

    const res = await deletePlatform(row.id)
    if (res.data.code === 200) {
      ElMessage.success('删除成功')
      loadPlatforms()
    } else {
      ElMessage.error(res.data.message || '删除失败')
    }
  } catch (error) {
    if (error !== 'cancel') {
      console.error('删除失败:', error)
      ElMessage.error('删除失败')
    }
  }
}

// ==================== 工具函数 ====================
function formatMoney(value) {
  if (value === null || value === undefined) return '-'
  return '¥' + Number(value).toFixed(2)
}

function formatPercent(value) {
  if (value === null || value === undefined) return '-'
  const sign = value >= 0 ? '+' : ''
  return sign + Number(value).toFixed(2) + '%'
}

function getProfitClass(value) {
  if (value === null || value === undefined) return ''
  return value >= 0 ? 'profit-positive' : 'profit-negative'
}
</script>

