<template>
  <!-- 服务器详情页面 -->
  <div class="server-detail-page" v-if="server">
    <!-- 页面头部 -->
    <div class="page-header">
      <div class="header-left">
        <el-button @click="goBack">
          <el-icon><ArrowLeft /></el-icon>
          返回
        </el-button>
        <h1 class="page-title">
          {{ server.name }}
          <el-tag v-if="server.isDefault" type="success" effect="dark">默认</el-tag>
        </h1>
      </div>
      <div class="header-actions">
        <el-button type="primary" @click="checkStatus" :loading="checking">
          <el-icon><Refresh /></el-icon>
          检查状态
        </el-button>
        <el-button type="warning" @click="editServer">
          <el-icon><Edit /></el-icon>
          编辑
        </el-button>
      </div>
    </div>

    <!-- 服务器基本信息 -->
    <el-row :gutter="20">
      <el-col :span="12">
        <el-card class="info-card">
          <template #header>
            <div class="card-header">
              <el-icon><InfoFilled /></el-icon>
              <span>基本信息</span>
            </div>
          </template>
          <el-descriptions :column="1" border>
            <el-descriptions-item label="服务器ID">{{ server.id }}</el-descriptions-item>
            <el-descriptions-item label="服务器名称">{{ server.name }}</el-descriptions-item>
            <el-descriptions-item label="IP地址">{{ server.host }}</el-descriptions-item>
            <el-descriptions-item label="端口">{{ server.port }}</el-descriptions-item>
            <el-descriptions-item label="位置">{{ server.location || '-' }}</el-descriptions-item>
            <el-descriptions-item label="类型">{{ server.serverType }}</el-descriptions-item>
            <el-descriptions-item label="权重">{{ server.weight }}</el-descriptions-item>
            <el-descriptions-item label="超时时间">{{ server.timeout }}秒</el-descriptions-item>
            <el-descriptions-item label="最大重试">{{ server.maxRetries }}次</el-descriptions-item>
            <el-descriptions-item label="启用状态">
              <el-tag :type="server.isEnabled ? 'success' : 'danger'">
                {{ server.isEnabled ? '已启用' : '已禁用' }}
              </el-tag>
            </el-descriptions-item>
            <el-descriptions-item label="描述">{{ server.description || '-' }}</el-descriptions-item>
          </el-descriptions>
        </el-card>
      </el-col>

      <el-col :span="12">
        <el-card class="status-card">
          <template #header>
            <div class="card-header">
              <el-icon><Monitor /></el-icon>
              <span>运行状态</span>
            </div>
          </template>
          <div class="status-content">
            <div class="status-item">
              <div class="status-label">当前状态</div>
              <div class="status-value">
                <el-tag :type="getStatusType(server.status)" size="large" effect="dark">
                  {{ getStatusText(server.status) }}
                </el-tag>
              </div>
            </div>
            <div class="status-item">
              <div class="status-label">响应时间</div>
              <div class="status-value">
                <span v-if="server.responseTime" class="highlight">{{ server.responseTime.toFixed(2) }}ms</span>
                <span v-else>-</span>
              </div>
            </div>
            <div class="status-item">
              <div class="status-label">成功率</div>
              <div class="status-value">
                <el-progress
                  v-if="server.successRate !== undefined"
                  :percentage="Math.round(server.successRate)"
                  :status="server.successRate > 80 ? 'success' : server.successRate > 50 ? 'warning' : 'exception'"
                />
                <span v-else>-</span>
              </div>
            </div>
            <div class="status-item">
              <div class="status-label">总请求数</div>
              <div class="status-value">{{ server.totalRequests || 0 }}</div>
            </div>
            <div class="status-item">
              <div class="status-label">成功请求</div>
              <div class="status-value">{{ server.successRequests || 0 }}</div>
            </div>
            <div class="status-item">
              <div class="status-label">连续失败</div>
              <div class="status-value" :class="{ 'text-danger': server.failCount > 0 }">
                {{ server.failCount || 0 }}次
              </div>
            </div>
            <div class="status-item">
              <div class="status-label">最后检查</div>
              <div class="status-value">{{ formatDateTime(server.lastCheck) }}</div>
            </div>
            <div class="status-item">
              <div class="status-label">更新时间</div>
              <div class="status-value">{{ formatDateTime(server.updatedAt) }}</div>
            </div>
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 编辑对话框 -->
    <el-dialog
      v-model="dialogVisible"
      title="编辑服务器"
      width="500px"
      destroy-on-close
    >
      <el-form
        ref="formRef"
        :model="formData"
        :rules="formRules"
        label-width="100px"
      >
        <el-form-item label="服务器名称" prop="name">
          <el-input v-model="formData.name" />
        </el-form-item>
        <el-form-item label="IP地址" prop="host">
          <el-input v-model="formData.host" />
        </el-form-item>
        <el-form-item label="端口" prop="port">
          <el-input-number v-model="formData.port" :min="1" :max="65535" style="width: 100%" />
        </el-form-item>
        <el-form-item label="位置" prop="location">
          <el-input v-model="formData.location" />
        </el-form-item>
        <el-form-item label="权重" prop="weight">
          <el-input-number v-model="formData.weight" :min="1" :max="1000" style="width: 100%" />
        </el-form-item>
        <el-form-item label="超时时间" prop="timeout">
          <el-input-number v-model="formData.timeout" :min="1" :max="60" style="width: 100%">
            <template #suffix>秒</template>
          </el-input-number>
        </el-form-item>
        <el-form-item label="重试次数" prop="maxRetries">
          <el-input-number v-model="formData.maxRetries" :min="0" :max="10" style="width: 100%" />
        </el-form-item>
        <el-form-item label="描述" prop="description">
          <el-input v-model="formData.description" type="textarea" :rows="3" />
        </el-form-item>
        <el-form-item label="启用">
          <el-switch v-model="formData.isEnabled" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="submitForm" :loading="submitting">更新</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script>
/**
 * 服务器详情页面组件
 * 功能：展示单个TDX服务器的详细信息和运行状态
 */
import { ref, reactive, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { serverApi } from '../api/server'

export default {
  name: 'ServerDetail',

  props: {
    id: {
      type: String,
      required: true
    }
  },

  setup(props) {
    // eslint-disable-next-line no-unused-vars
    const route = useRoute()
    const router = useRouter()

    // 响应式数据
    const server = ref(null)
    const loading = ref(false)
    const checking = ref(false)
    const submitting = ref(false)
    const dialogVisible = ref(false)
    const formRef = ref(null)

    // 表单数据
    const formData = reactive({
      name: '',
      host: '',
      port: 7709,
      location: '',
      weight: 100,
      timeout: 10,
      maxRetries: 3,
      description: '',
      isEnabled: true
    })

    // 表单验证规则
    const formRules = {
      name: [
        { required: true, message: '请输入服务器名称', trigger: 'blur' },
        { max: 100, message: '名称不能超过100个字符', trigger: 'blur' }
      ],
      host: [
        { required: true, message: '请输入IP地址', trigger: 'blur' },
        {
          pattern: /^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/,
          message: 'IP地址格式不正确',
          trigger: 'blur'
        }
      ],
      port: [
        { required: true, message: '请输入端口', trigger: 'blur' }
      ]
    }

    // 获取服务器详情
    const fetchServerDetail = async () => {
      loading.value = true
      try {
        const res = await serverApi.getServerById(props.id)
        if (res.code === 200) {
          server.value = res.data
        }
      } catch (error) {
        ElMessage.error('获取服务器详情失败: ' + error.message)
      } finally {
        loading.value = false
      }
    }

    // 获取状态标签类型
    const getStatusType = (status) => {
      const statusLower = (status || '').toLowerCase()
      const typeMap = {
        'online': 'success',
        'offline': 'danger',
        'unstable': 'warning',
        'maintenance': 'info',
        'unknown': 'info'
      }
      return typeMap[statusLower] || 'info'
    }

    // 获取状态显示文本
    const getStatusText = (status) => {
      const statusLower = (status || '').toLowerCase()
      const textMap = {
        'online': '在线',
        'offline': '离线',
        'unstable': '不稳定',
        'maintenance': '维护中',
        'unknown': '未知'
      }
      return textMap[statusLower] || status
    }

    // 格式化日期时间
    const formatDateTime = (datetime) => {
      if (!datetime) return '-'
      const date = new Date(datetime)
      return date.toLocaleString('zh-CN')
    }

    // 返回列表页
    const goBack = () => {
      router.push('/servers')
    }

    // 检查状态
    const checkStatus = async () => {
      checking.value = true
      try {
        const res = await serverApi.checkServerStatus(server.value.id)
        if (res.code === 200) {
          ElMessage.success('状态检查完成')
          fetchServerDetail()
        }
      } catch (error) {
        ElMessage.error('检查失败: ' + error.message)
      } finally {
        checking.value = false
      }
    }

    // 编辑服务器
    const editServer = () => {
      Object.assign(formData, server.value)
      dialogVisible.value = true
    }

    // 提交表单
    const submitForm = async () => {
      const valid = await formRef.value.validate().catch(() => false)
      if (!valid) return

      submitting.value = true
      try {
        const res = await serverApi.updateServer(server.value.id, formData)
        if (res.code === 200) {
          ElMessage.success('更新成功')
          dialogVisible.value = false
          fetchServerDetail()
        } else {
          ElMessage.error(res.message)
        }
      } catch (error) {
        ElMessage.error('更新失败: ' + error.message)
      } finally {
        submitting.value = false
      }
    }

    // 页面加载时获取数据
    onMounted(() => {
      fetchServerDetail()
    })

    return {
      server,
      loading,
      checking,
      submitting,
      dialogVisible,
      formData,
      formRules,
      formRef,
      getStatusType,
      getStatusText,
      formatDateTime,
      goBack,
      checkStatus,
      editServer,
      submitForm
    }
  }
}
</script>

