        <el-icon size="28"><PriceTag /></el-icon>
        标签管理
      </h1>
      <p class="page-desc">统一管理股票的题材、行业、概念、技术指标等各类标签</p>
    </div>

    <!-- 标签类型选择卡 -->
    <div class="tag-type-tabs">
      <el-radio-group v-model="currentTagType" size="large" @change="handleTagTypeChange">
        <el-radio-button label="">全部标签</el-radio-button>
        <el-radio-button label="theme">题材</el-radio-button>
        <el-radio-button label="industry">行业</el-radio-button>
        <el-radio-button label="concept">概念</el-radio-button>
        <el-radio-button label="technical">技术指标</el-radio-button>
        <el-radio-button label="region">地域</el-radio-button>
        <el-radio-button label="style">风格</el-radio-button>
      </el-radio-group>
    </div>

    <!-- 操作栏 -->
    <div class="action-bar">
      <div class="search-section">
        <el-input
          v-model="searchKeyword"
          placeholder="搜索标签名称、关键词..."
          clearable
          size="large"
          class="search-input"
          @keyup.enter="handleSearch"
        >
          <template #prefix>
            <el-icon><Search /></el-icon>
          </template>
        </el-input>
        <el-button type="primary" size="large" @click="handleSearch" :loading="loading">
          <el-icon><Search /></el-icon>
          搜索
        </el-button>
        <el-button size="large" @click="resetSearch">
          <el-icon><RefreshRight /></el-icon>
          重置
        </el-button>
      </div>
      <div class="action-section">
        <el-button type="success" size="large" @click="showCreateDialog">
          <el-icon><Plus /></el-icon>
          新建标签
        </el-button>
        <el-tag v-if="tagStats.total" type="info" size="large" effect="plain">
          共 {{ tagStats.total }} 个标签
        </el-tag>
      </div>
    </div>

    <!-- 主内容区：三栏布局 -->
    <div class="main-content">
      <!-- 左侧：标签列表 -->
      <div class="left-panel">
        <div class="panel-header">
          <div class="header-left">
            <el-icon><List /></el-icon>
            <span>{{ currentTagTypeLabel }}</span>
            <el-tag v-if="filteredTags.length" type="info" size="small">
              {{ filteredTags.length }}
            </el-tag>
          </div>
        </div>

        <div class="tag-list" v-loading="loading">
          <div
            v-for="tag in filteredTags"
            :key="tag.tagId"
            class="tag-item"
            :class="{ active: selectedTag?.tagId === tag.tagId }"
            @click="selectTag(tag)"
          >
            <div class="tag-item-header">
              <el-tag
                :type="getTagTypeColor(tag.tagType)"
                size="small"
                effect="dark"
                class="type-tag"
              >
                {{ getTagTypeLabel(tag.tagType) }}
              </el-tag>
              <span class="tag-name">{{ tag.tagName }}</span>
            </div>
            <div class="tag-item-info">
              <span class="stock-count">
                <el-icon><User /></el-icon>
                {{ tag.stockCount || 0 }} 只股票
              </span>
              <span v-if="tag.keywords" class="keywords">{{ tag.keywords }}</span>
            </div>
          </div>

          <el-empty v-if="!loading && filteredTags.length === 0" description="暂无标签数据" />
        </div>
      </div>

      <!-- 中间：标签详情 -->
      <div class="center-panel" v-if="selectedTag">
        <div class="panel-header">
          <div class="header-left">
            <el-icon><InfoFilled /></el-icon>
            <span>标签详情</span>
          </div>
          <div class="header-actions">
            <el-button type="primary" size="small" @click="showEditDialog">
              <el-icon><Edit /></el-icon>
              编辑
            </el-button>
            <el-button type="danger" size="small" @click="handleDeleteTag">
              <el-icon><Delete /></el-icon>
              删除
            </el-button>
          </div>
        </div>

        <div class="tag-detail">
          <div class="detail-header">
            <h3 class="detail-title">{{ selectedTag.tagName }}</h3>
            <el-tag :type="getTagTypeColor(selectedTag.tagType)" effect="dark">
              {{ getTagTypeLabel(selectedTag.tagType) }}
            </el-tag>
          </div>

          <div class="detail-info">
            <div class="info-item">
              <span class="info-label">标签ID：</span>
              <span class="info-value">{{ selectedTag.tagId }}</span>
            </div>
            <div class="info-item">
              <span class="info-label">关联股票：</span>
              <span class="info-value">{{ selectedTag.stockCount || 0 }} 只</span>
            </div>
            <div class="info-item" v-if="selectedTag.keywords">
              <span class="info-label">关键词：</span>
              <span class="info-value">{{ selectedTag.keywords }}</span>
            </div>
            <div class="info-item" v-if="selectedTag.description">
              <span class="info-label">描述：</span>
              <span class="info-value">{{ selectedTag.description }}</span>
            </div>
            <div class="info-item" v-if="selectedTag.color">
              <span class="info-label">颜色：</span>
              <span class="color-preview" :style="{ backgroundColor: selectedTag.color }"></span>
              <span class="info-value">{{ selectedTag.color }}</span>
            </div>
            <div class="info-item">
              <span class="info-label">创建时间：</span>
              <span class="info-value">{{ formatDate(selectedTag.createdAt) }}</span>
            </div>
          </div>
        </div>
      </div>

      <!-- 右侧：关联股票列表 -->
      <div class="right-panel" v-if="selectedTag">
        <div class="panel-header">
          <div class="header-left">
            <el-icon><User /></el-icon>
            <span>关联股票</span>
            <el-tag type="info" size="small">{{ tagStocks.length }}</el-tag>
          </div>
        </div>

        <div class="stock-list" v-loading="stockLoading">
          <div
            v-for="stock in tagStocks"
            :key="`${stock.market}${stock.code}`"
            class="stock-item"
            @click="goToStockDetail(stock)"
          >
            <div class="stock-code">{{ stock.market }}:{{ stock.code }}</div>
            <div class="stock-name">{{ stock.name }}</div>
            <div class="stock-industry" v-if="stock.industry">{{ stock.industry }}</div>
          </div>

          <el-empty v-if="!stockLoading && tagStocks.length === 0" description="暂无关联股票" />
        </div>
      </div>
    </div>

    <!-- 新建/编辑标签对话框 -->
    <el-dialog
      v-model="dialogVisible"
      :title="isEdit ? '编辑标签' : '新建标签'"
      width="600px"
      destroy-on-close
    >
      <el-form :model="tagForm" :rules="tagRules" ref="tagFormRef" label-width="100px">
        <el-form-item label="标签名称" prop="tagName">
          <el-input v-model="tagForm.tagName" placeholder="请输入标签名称" />
        </el-form-item>
        <el-form-item label="标签类型" prop="tagType">
          <el-select v-model="tagForm.tagType" placeholder="请选择标签类型" style="width: 100%">
            <el-option label="题材" value="theme" />
            <el-option label="行业" value="industry" />
            <el-option label="概念" value="concept" />
            <el-option label="技术指标" value="technical" />
            <el-option label="地域" value="region" />
            <el-option label="风格" value="style" />
          </el-select>
        </el-form-item>
