</template>

<script setup>
import { ref, computed, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import {
  PriceTag, Search, RefreshRight, Plus, List,
  InfoFilled, Edit, Delete, User
} from '@element-plus/icons-vue'
import {
  getTags, searchTags, createTag, updateTag, deleteTag,
  getTagStocks, getTagStats
} from '@/api/stockTag'

// 响应式数据
const loading = ref(false)
const stockLoading = ref(false)
const submitLoading = ref(false)
const dialogVisible = ref(false)
const isEdit = ref(false)
const tagFormRef = ref(null)

const currentTagType = ref('')
const searchKeyword = ref('')
const tags = ref([])
const selectedTag = ref(null)
const tagStocks = ref([])
const tagStats = ref({ total: 0 })

const tagForm = ref({
  tagId: '',
  tagName: '',
  tagType: 'theme',
  keywords: '',
  description: '',
  color: ''
})

const tagRules = {
  tagName: [{ required: true, message: '请输入标签名称', trigger: 'blur' }],
  tagType: [{ required: true, message: '请选择标签类型', trigger: 'change' }],
  tagId: [{ required: true, message: '请输入标签ID', trigger: 'blur' }]
}

// 标签类型映射
const tagTypeMap = {
  theme: { label: '题材', color: 'primary' },
  industry: { label: '行业', color: 'success' },
  concept: { label: '概念', color: 'warning' },
  technical: { label: '技术指标', color: 'danger' },
  region: { label: '地域', color: 'info' },
  style: { label: '风格', color: '' }
}

// 计算属性
const currentTagTypeLabel = computed(() => {
  if (!currentTagType.value) return '全部标签'
  return tagTypeMap[currentTagType.value]?.label + '标签' || '标签列表'
})

const filteredTags = computed(() => {
  if (!currentTagType.value) return tags.value
  return tags.value.filter(tag => tag.tagType === currentTagType.value)
})

// 方法
const loadTags = async () => {
  loading.value = true
  try {
    const res = await getTags()
    tags.value = res.data || []
  } catch (error) {
    ElMessage.error('加载标签失败: ' + error.message)
  } finally {
    loading.value = false
  }
}

const loadTagStats = async () => {
  try {
    const res = await getTagStats()
    tagStats.value = res.data || { total: 0 }
  } catch (error) {
    console.error('加载统计失败', error)
  }
}

const handleTagTypeChange = () => {
  selectedTag.value = null
  tagStocks.value = []
}

const handleSearch = async () => {
  if (!searchKeyword.value.trim()) {
    loadTags()
    return
  }
  loading.value = true
  try {
    const res = await searchTags(searchKeyword.value, currentTagType.value)
    tags.value = res.data || []
  } catch (error) {
    ElMessage.error('搜索失败: ' + error.message)
  } finally {
    loading.value = false
  }
}

const resetSearch = () => {
  searchKeyword.value = ''
  currentTagType.value = ''
  loadTags()
}

const selectTag = async (tag) => {
  selectedTag.value = tag
  await loadTagStocks(tag.tagId)
}

const loadTagStocks = async (tagId) => {
  stockLoading.value = true
  try {
    const res = await getTagStocks(tagId, 100)
    tagStocks.value = res.data?.data || []
  } catch (error) {
    ElMessage.error('加载关联股票失败: ' + error.message)
  } finally {
    stockLoading.value = false
  }
}

const getTagTypeLabel = (type) => {
  return tagTypeMap[type]?.label || type
}

const getTagTypeColor = (type) => {
  return tagTypeMap[type]?.color || ''
}

const formatDate = (dateStr) => {
  if (!dateStr) return '-'
  const date = new Date(dateStr)
  return date.toLocaleString('zh-CN')
}

const goToStockDetail = (stock) => {
  // 可以跳转到股票详情页
  console.log('查看股票详情:', stock)
}

// 对话框操作
const showCreateDialog = () => {
  isEdit.value = false
  tagForm.value = {
    tagId: '',
    tagName: '',
    tagType: currentTagType.value || 'theme',
    keywords: '',
    description: '',
    color: ''
  }
  dialogVisible.value = true
}

const showEditDialog = () => {
  if (!selectedTag.value) return
  isEdit.value = true
  tagForm.value = {
    tagId: selectedTag.value.tagId,
    tagName: selectedTag.value.tagName,
    tagType: selectedTag.value.tagType,
    keywords: selectedTag.value.keywords || '',
    description: selectedTag.value.description || '',
    color: selectedTag.value.color || ''
  }
  dialogVisible.value = true
}

const handleSubmit = async () => {
  const valid = await tagFormRef.value?.validate().catch(() => false)
  if (!valid) return

  submitLoading.value = true
  try {
    if (isEdit.value) {
      await updateTag(tagForm.value.tagId, tagForm.value)
      ElMessage.success('更新成功')
    } else {
      await createTag(tagForm.value)
      ElMessage.success('创建成功')
    }
    dialogVisible.value = false
    loadTags()
    loadTagStats()
  } catch (error) {
    ElMessage.error('操作失败: ' + error.message)
  } finally {
    submitLoading.value = false
  }
}

const handleDeleteTag = async () => {
  if (!selectedTag.value) return
  try {
    await ElMessageBox.confirm(
      `确定要删除标签 "${selectedTag.value.tagName}" 吗？`,
      '确认删除',
      { type: 'warning' }
    )
    await deleteTag(selectedTag.value.tagId)
    ElMessage.success('删除成功')
    selectedTag.value = null
    tagStocks.value = []
    loadTags()
    loadTagStats()
  } catch (error) {
    if (error !== 'cancel') {
      ElMessage.error('删除失败: ' + error.message)
    }
  }
}

// 生命周期
onMounted(() => {
  loadTags()
  loadTagStats()
})
</script>

