<template>
  <!-- 原始数据面板组件 - 展示公司信息的原始数据结构 -->
  <div class="raw-data-panel">
    <!-- 数据分类选择 -->
    <el-card class="category-selector" shadow="hover">
      <template #header>
        <div class="card-header">
          <el-icon><FolderOpened /></el-icon>
          <span>数据分类</span>
        </div>
      </template>
      <el-radio-group v-model="selectedCategory" size="large">
        <el-radio-button label="all">全部数据</el-radio-button>
        <el-radio-button label="basic">基本信息</el-radio-button>
        <el-radio-button label="finance">财务数据</el-radio-button>
        <el-radio-button label="shares">股本信息</el-radio-button>
        <el-radio-button label="contact">联系信息</el-radio-button>
        <el-radio-button label="raw">原始文本</el-radio-button>
      </el-radio-group>
    </el-card>

    <!-- 数据展示 -->
    <el-card class="data-display" shadow="hover">
      <template #header>
        <div class="card-header">
          <div class="header-title">
            <el-icon><DataAnalysis /></el-icon>
            <span>{{ getDisplayTitle() }}</span>
          </div>
          <el-button type="primary" size="small" @click="copyData">
            <el-icon><CopyDocument /></el-icon>
            复制JSON
          </el-button>
        </div>
      </template>

      <!-- JSON格式展示 -->
      <div class="json-display">
        <pre v-highlightjs><code class="json">{{ formattedJson }}</code></pre>
      </div>
    </el-card>

    <!-- 数据字段说明 -->
    <el-card class="field-docs" shadow="hover">
      <template #header>
        <div class="card-header">
          <el-icon><InfoFilled /></el-icon>
          <span>字段说明</span>
        </div>
      </template>

      <el-collapse v-model="activeCollapse">
        <el-collapse-item title="基本信息字段" name="basic">
          <el-descriptions :column="2" border>
            <el-descriptions-item label="code">股票代码</el-descriptions-item>
            <el-descriptions-item label="name">股票名称</el-descriptions-item>
            <el-descriptions-item label="market">市场代码 (0=深圳, 1=上海)</el-descriptions-item>
            <el-descriptions-item label="marketName">市场名称</el-descriptions-item>
            <el-descriptions-item label="fullName">公司全称</el-descriptions-item>
            <el-descriptions-item label="englishName">英文名称</el-descriptions-item>
            <el-descriptions-item label="industry">所属行业</el-descriptions-item>
            <el-descriptions-item label="listingDate">上市日期</el-descriptions-item>
          </el-descriptions>
        </el-collapse-item>

        <el-collapse-item title="股本信息字段" name="shares">
          <el-descriptions :column="2" border>
            <el-descriptions-item label="totalShares">总股本</el-descriptions-item>
            <el-descriptions-item label="circulatingShares">流通股本</el-descriptions-item>
            <el-descriptions-item label="totalSharesFormatted">格式化总股本</el-descriptions-item>
            <el-descriptions-item label="circulatingSharesFormatted">格式化流通股本</el-descriptions-item>
            <el-descriptions-item label="totalShareholders">股东总数</el-descriptions-item>
            <el-descriptions-item label="institutionalShareholders">机构股东数</el-descriptions-item>
          </el-descriptions>
        </el-collapse-item>

        <el-collapse-item title="财务指标字段" name="finance">
          <el-descriptions :column="2" border>
            <el-descriptions-item label="eps">每股收益</el-descriptions-item>
            <el-descriptions-item label="navps">每股净资产</el-descriptions-item>
            <el-descriptions-item label="roe">净资产收益率</el-descriptions-item>
            <el-descriptions-item label="revenuePerShare">每股营收</el-descriptions-item>
            <el-descriptions-item label="operatingCashFlowPerShare">每股现金流</el-descriptions-item>
            <el-descriptions-item label="grossProfitMargin">毛利率</el-descriptions-item>
            <el-descriptions-item label="netProfitMargin">净利率</el-descriptions-item>
            <el-descriptions-item label="debtToAssetRatio">资产负债率</el-descriptions-item>
            <el-descriptions-item label="peRatio">市盈率</el-descriptions-item>
            <el-descriptions-item label="pbRatio">市净率</el-descriptions-item>
          </el-descriptions>
        </el-collapse-item>

        <el-collapse-item title="联系信息字段" name="contact">
          <el-descriptions :column="2" border>
            <el-descriptions-item label="registeredAddress">注册地址</el-descriptions-item>
            <el-descriptions-item label="officeAddress">办公地址</el-descriptions-item>
            <el-descriptions-item label="phone">联系电话</el-descriptions-item>
            <el-descriptions-item label="fax">传真</el-descriptions-item>
            <el-descriptions-item label="email">电子邮箱</el-descriptions-item>
            <el-descriptions-item label="website">公司网址</el-descriptions-item>
            <el-descriptions-item label="postalCode">邮政编码</el-descriptions-item>
          </el-descriptions>
        </el-collapse-item>
      </el-collapse>
    </el-card>
  </div>
</template>

<script>
import { ref, computed } from 'vue'
import { FolderOpened, DataAnalysis, CopyDocument, InfoFilled } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'

export default {
  name: 'RawDataPanel',

  components: {
    FolderOpened,
    DataAnalysis,
    CopyDocument,
    InfoFilled
  },

  props: {
    data: {
      type: Object,
      required: true
    }
  },

  setup(props) {
    const selectedCategory = ref('all')
    const activeCollapse = ref(['basic'])

    /**
     * 根据选择过滤数据
     */
    const filteredData = computed(() => {
      const category = selectedCategory.value
      const data = props.data

      if (category === 'all') {
        return data
      }

      if (category === 'basic') {
        return {
          code: data.code,
          name: data.name,
          market: data.market,
          marketName: data.marketName,
          fullName: data.fullName,
          englishName: data.englishName,
          industry: data.industry,
          website: data.website,
          listingDate: data.listingDate,
          companyProfile: data.companyProfile,
          businessScope: data.businessScope,
          mainBusiness: data.mainBusiness
        }
      }

      if (category === 'finance') {
        return {
          eps: data.eps,
          navps: data.navps,
          roe: data.roe,
          revenuePerShare: data.revenuePerShare,
          operatingCashFlowPerShare: data.operatingCashFlowPerShare,
          grossProfitMargin: data.grossProfitMargin,
          netProfitMargin: data.netProfitMargin,
          debtToAssetRatio: data.debtToAssetRatio,
          peRatio: data.peRatio,
          pbRatio: data.pbRatio,
          dividendPerShare: data.dividendPerShare,
          dividendYield: data.dividendYield,
          lastDividendDate: data.lastDividendDate
        }
      }

      if (category === 'shares') {
        return {
          totalShares: data.totalShares,
          circulatingShares: data.circulatingShares,
          totalSharesFormatted: data.totalSharesFormatted,
          circulatingSharesFormatted: data.circulatingSharesFormatted,
          totalShareholders: data.totalShareholders,
          institutionalShareholders: data.institutionalShareholders,
          top10Shareholders: data.top10Shareholders
        }
      }

      if (category === 'contact') {
        return {
          registeredAddress: data.registeredAddress,
          officeAddress: data.officeAddress,
          phone: data.phone,
          fax: data.fax,
          email: data.email,
          postalCode: data.postalCode,
          website: data.website
        }
      }

      if (category === 'raw') {
        return {
          categoryData: data.categoryData,
          categories: data.categories,
          companyProfile: data.companyProfile
        }
      }

      return data
    })

    /**
     * 格式化JSON
     */
    const formattedJson = computed(() => {
      return JSON.stringify(filteredData.value, null, 2)
    })

    /**
     * 获取显示标题
     */
    const getDisplayTitle = () => {
      const titles = {
        all: '完整数据',
        basic: '基本信息',
        finance: '财务数据',
        shares: '股本信息',
        contact: '联系信息',
        raw: '原始文本数据'
      }
      return titles[selectedCategory.value] || '数据'
    }

    /**
     * 复制数据到剪贴板
     */
    const copyData = () => {
      navigator.clipboard.writeText(formattedJson.value).then(() => {
        ElMessage.success('数据已复制到剪贴板')
      }).catch(() => {
        ElMessage.error('复制失败')
      })
    }

    return {
      selectedCategory,
      activeCollapse,
      formattedJson,
      getDisplayTitle,
      copyData
    }
  }
}
</script>

