<script>
import { Money, TrendCharts, Histogram, DataAnalysis, OfficeBuilding, PieChart, Collection } from '@element-plus/icons-vue'

export default {
  name: 'OverviewPanel',

  components: {
    Money,
    TrendCharts,
    Histogram,
    DataAnalysis,
    OfficeBuilding,
    PieChart,
    Collection
  },

  props: {
    data: {
      type: Object,
      required: true
    }
  },

  setup() {
    /**
     * 格式化数值
     */
    const formatValue = (value, unit = '') => {
      if (value === null || value === undefined) return '-'
      return `${value}${unit}`
    }

    /**
     * 格式化百分比
     */
    const formatPercent = (value) => {
      if (value === null || value === undefined) return '-'
      return `${value}%`
    }

    /**
     * 格式化日期
     */
    const formatDate = (dateStr) => {
      if (!dateStr) return '-'
      return dateStr
    }

    return {
      formatValue,
      formatPercent,
      formatDate
    }
  }
}
</script>

