<template>
  <!-- F10公司资料页面 - 优化版 -->
  <div class="company-info-page">
    <!-- 页面标题 -->
    <div class="page-header">
      <h1 class="page-title">
        <el-icon><Document /></el-icon>
        F10 公司资料
      </h1>
      <div class="page-actions">
        <el-button type="primary" @click="fetchCompanyInfo" :loading="loading">
          <el-icon><Refresh /></el-icon>
          刷新
        </el-button>
      </div>
    </div>

    <!-- 搜索条件 -->
    <el-card class="search-card" shadow="hover">
      <el-form :inline="true" :model="searchForm" class="search-form">
        <el-form-item label="市场">
          <el-select v-model="searchForm.market" placeholder="选择市场" style="width: 100px">
            <el-option label="上海" value="SH" />
            <el-option label="深圳" value="SZ" />
          </el-select>
        </el-form-item>
        <el-form-item label="股票代码">
          <el-input 
            v-model="searchForm.code" 
            placeholder="输入股票代码" 
            style="width: 150px"
            @keyup.enter="fetchCompanyInfo"
          />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="fetchCompanyInfo" :loading="loading">
            <el-icon><Search /></el-icon>
            查询
          </el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <!-- 加载状态 -->
    <div v-if="loading" class="loading-container">
      <el-skeleton :rows="10" animated />
    </div>

    <!-- 公司信息展示 -->
    <template v-else-if="companyInfo">
      <!-- 公司头部信息卡片 -->
      <el-card class="company-header-card" shadow="hover">
        <div class="company-header">
          <div class="company-basic">
            <h2 class="company-name">{{ companyInfo.name || companyInfo.code }}</h2>
            <div class="company-tags">
              <el-tag size="large" type="primary" effect="dark">
                {{ companyInfo.code }}
              </el-tag>
              <el-tag size="large" type="info">
                {{ companyInfo.marketName }}
              </el-tag>
              <el-tag v-if="companyInfo.industry" size="large" type="success">
                {{ companyInfo.industry }}
              </el-tag>
            </div>
          </div>
          <div v-if="companyInfo.website" class="company-website">
            <el-link :href="formatWebsite(companyInfo.website)" target="_blank" type="primary">
              <el-icon><LinkIcon /></el-icon>
              访问官网
            </el-link>
          </div>
        </div>
      </el-card>

      <!-- 分类标签页 -->
      <el-card class="content-card" shadow="hover">
        <el-tabs v-model="activeTab" type="border-card" class="company-tabs">
          <!-- 概览 -->
          <el-tab-pane label="概览" name="overview">
            <div class="tab-content">
              <OverviewPanel :data="companyInfo" />
            </div>
          </el-tab-pane>

          <!-- 股本结构 -->
          <el-tab-pane label="股本结构" name="shares">
            <div class="tab-content">
              <SharesPanel :data="companyInfo" />
            </div>
          </el-tab-pane>

          <!-- 财务指标 -->
          <el-tab-pane label="财务指标" name="finance">
            <div class="tab-content">
              <FinancePanel :data="companyInfo" />
            </div>
          </el-tab-pane>

          <!-- 股东研究 -->
          <el-tab-pane label="股东研究" name="shareholders">
            <div class="tab-content">
              <ShareholdersPanel :data="companyInfo" />
            </div>
          </el-tab-pane>

          <!-- 联系信息 -->
          <el-tab-pane label="联系信息" name="contact">
            <div class="tab-content">
              <ContactPanel :data="companyInfo" />
            </div>
          </el-tab-pane>

          <!-- 公司简介 -->
          <el-tab-pane label="公司简介" name="profile">
            <div class="tab-content">
              <ProfilePanel :data="companyInfo" />
            </div>
          </el-tab-pane>

          <!-- 原始数据 -->
          <el-tab-pane label="原始数据" name="raw">
            <div class="tab-content">
              <RawDataPanel :data="companyInfo" />
            </div>
          </el-tab-pane>
        </el-tabs>
      </el-card>
    </template>

    <!-- 空状态 -->
    <el-empty v-else description="请输入股票代码查询公司资料">
      <template #image>
        <el-icon :size="60" color="#909399"><Document /></el-icon>
      </template>
    </el-empty>
  </div>
</template>

<script>
import { ref, reactive, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Document, Refresh, Search, Link as LinkIcon } from '@element-plus/icons-vue'
import { getCompanyInfo } from '@/api/stock'
import OverviewPanel from '@/components/company/OverviewPanel.vue'
import SharesPanel from '@/components/company/SharesPanel.vue'
import FinancePanel from '@/components/company/FinancePanel.vue'
import ShareholdersPanel from '@/components/company/ShareholdersPanel.vue'
import ContactPanel from '@/components/company/ContactPanel.vue'
import ProfilePanel from '@/components/company/ProfilePanel.vue'
import RawDataPanel from '@/components/company/RawDataPanel.vue'

export default {
  name: 'CompanyInfoView',

  components: {
    Document,
    Refresh,
    Search,
    LinkIcon,
    OverviewPanel,
    SharesPanel,
    FinancePanel,
    ShareholdersPanel,
    ContactPanel,
    ProfilePanel,
    RawDataPanel
  },

  setup() {
    const route = useRoute()

    // 加载状态
    const loading = ref(false)

    // 当前激活的标签页
    const activeTab = ref('overview')

    // 搜索表单
    const searchForm = reactive({
      market: 'SZ',
      code: ''
    })

    // 公司信息
    const companyInfo = ref(null)

    /**
     * 获取公司信息
     */
    const fetchCompanyInfo = async () => {
      if (!searchForm.code) {
        ElMessage.warning('请输入股票代码')
        return
      }

      loading.value = true
      try {
        const response = await getCompanyInfo(searchForm.market, searchForm.code)

        if (response.data.code === 200) {
          companyInfo.value = response.data.data
          ElMessage.success('获取公司资料成功')
        } else {
          ElMessage.error(response.data.message || '获取公司资料失败')
          companyInfo.value = null
        }
      } catch (error) {
        console.error('获取公司资料失败:', error)
        ElMessage.error('获取公司资料失败: ' + (error.message || '未知错误'))
        companyInfo.value = null
      } finally {
        loading.value = false
      }
    }

    /**
     * 格式化网址
     */
    const formatWebsite = (url) => {
      if (!url) return ''
      if (url.startsWith('http')) return url
      return 'http://' + url
    }

    onMounted(() => {
      // 如果URL中有参数，使用URL参数
      if (route.query.code) {
        searchForm.code = route.query.code
      }
      if (route.query.market) {
        searchForm.market = route.query.market
      }
      if (searchForm.code) {
        fetchCompanyInfo()
      }
    })

    return {
      loading,
      activeTab,
      searchForm,
      companyInfo,
      fetchCompanyInfo,
      formatWebsite
    }
  }
}
</script>

