/**
 * 股票标签管理API接口
 * 提供标签增删改查、股票标签关联、技术指标标签等功能
 */

import axios from 'axios'

const BASE_URL = process.env.VUE_APP_API_URL || 'http://localhost:8080'

const apiClient = axios.create({
  baseURL: BASE_URL,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json'
  }
})

// 请求拦截器
apiClient.interceptors.request.use(
  config => {
    console.log(`[API请求] ${config.method.toUpperCase()} ${config.url}`)
    return config
  },
  error => {
    console.error('[API请求错误]', error)
    return Promise.reject(error)
  }
)

// 响应拦截器
apiClient.interceptors.response.use(
  response => {
    console.log(`[API响应] ${response.config.url}`, response.data)
    const data = response.data
    if (data.code !== 200) {
      return Promise.reject(new Error(data.message || '操作失败'))
    }
    return data
  },
  error => {
    console.error('[API响应错误]', error)
    const message = error.response?.data?.message || error.message || '网络请求失败'
    return Promise.reject(new Error(message))
  }
)

/**
 * 获取标签列表
 * @param {string} tagType - 标签类型(可选)
 * @param {string} parentTagId - 父标签ID(可选)
 */
export function getTags(tagType, parentTagId) {
  const params = {}
  if (tagType) params.tagType = tagType
  if (parentTagId) params.parentTagId = parentTagId
  return apiClient.get('/api/stock-tags/tags', { params })
}

/**
 * 搜索标签
 * @param {string} keyword - 搜索关键词
 * @param {string} tagType - 标签类型(可选)
 */
export function searchTags(keyword, tagType) {
  const params = { keyword }
  if (tagType) params.tagType = tagType
  return apiClient.get('/api/stock-tags/tags/search', { params })
}

/**
 * 获取标签详情
 * @param {string} tagId - 标签ID
 */
export function getTagDetail(tagId) {
  return apiClient.get(`/api/stock-tags/tags/${tagId}`)
}

/**
 * 创建标签
 * @param {Object} data - 标签数据
 */
export function createTag(data) {
  return apiClient.post('/api/stock-tags/tags', data)
}

/**
 * 更新标签
 * @param {string} tagId - 标签ID
 * @param {Object} data - 更新数据
 */
export function updateTag(tagId, data) {
  return apiClient.put(`/api/stock-tags/tags/${tagId}`, data)
}

/**
 * 删除标签
 * @param {string} tagId - 标签ID
 */
export function deleteTag(tagId) {
  return apiClient.delete(`/api/stock-tags/tags/${tagId}`)
}

/**
 * 为股票添加标签
 * @param {Object} data - {code, market, tagId, weight, operator}
 */
export function addTagToStock(data) {
  return apiClient.post('/api/stock-tags/stock-tags', data)
}

/**
 * 移除股票标签
 * @param {string} code - 股票代码
 * @param {string} market - 市场代码
 * @param {string} tagId - 标签ID
 * @param {string} operator - 操作人(可选)
 */
export function removeTagFromStock(code, market, tagId, operator) {
  const params = { code, market, tagId }
  if (operator) params.operator = operator
  return apiClient.delete('/api/stock-tags/stock-tags', { params })
}

/**
 * 获取股票的标签列表
 * @param {string} market - 市场代码
 * @param {string} code - 股票代码
 * @param {string} tagType - 标签类型(可选)
 */
export function getStockTags(market, code, tagType) {
  const params = {}
  if (tagType) params.tagType = tagType
  return apiClient.get(`/api/stock-tags/stock/${market}/${code}`, { params })
}

/**
 * 获取标签关联的股票列表
 * @param {string} tagId - 标签ID
 * @param {number} limit - 数量限制
 */
export function getTagStocks(tagId, limit = 100) {
  return apiClient.get(`/api/stock-tags/tag/${tagId}/stocks`, { params: { limit } })
}

/**
 * 添加技术指标标签
 * @param {Object} data - 技术指标标签数据
 */
export function addTechnicalTag(data) {
  return apiClient.post('/api/stock-tags/technical-tags', data)
}

/**
 * 查询技术指标标签
 * @param {Object} params - 查询参数
 */
export function getTechnicalTags(params = {}) {
  return apiClient.get('/api/stock-tags/technical-tags', { params })
}

/**
 * 按信号类型查询股票
 * @param {Object} params - {indicatorName, signalType, tradeDate, minStrength}
 */
export function getStocksByTechnicalSignal(params) {
  return apiClient.get('/api/stock-tags/technical-signals', { params })
}

/**
 * 设置股票行业分类
 * @param {Object} data - 行业分类数据
 */
export function setStockIndustry(data) {
  return apiClient.post('/api/stock-tags/industries', data)
}

/**
 * 获取股票行业分类
 * @param {string} market - 市场代码
 * @param {string} code - 股票代码
 */
export function getStockIndustries(market, code) {
  return apiClient.get(`/api/stock-tags/industries/${market}/${code}`)
}

/**
 * 获取标签统计信息
 */
export function getTagStats() {
  return apiClient.get('/api/stock-tags/stats')
}

export default {
  getTags,
  searchTags,
  getTagDetail,
  createTag,
  updateTag,
  deleteTag,
  addTagToStock,
  removeTagFromStock,
  getStockTags,
  getTagStocks,
  addTechnicalTag,
  getTechnicalTags,
  getStocksByTechnicalSignal,
  setStockIndustry,
  getStockIndustries,
  getTagStats
}
