<template>
  <!-- 财务指标面板组件 - 展示公司财务相关指标 -->
  <div class="finance-panel">
    <!-- 盈利能力指标 -->
    <el-card class="finance-section" shadow="hover">
      <template #header>
        <div class="section-header">
          <el-icon><TrendCharts /></el-icon>
          <span>盈利能力</span>
        </div>
      </template>
      <el-row :gutter="20">
        <el-col :span="8" v-for="item in profitabilityIndicators" :key="item.key">
          <div class="indicator-item">
            <div class="indicator-label">{{ item.label }}</div>
            <div class="indicator-value" :class="getValueClass(item.value, item.type)">
              {{ formatValue(item.value, item.unit) }}
            </div>
            <el-progress
              v-if="item.percentage !== null"
              :percentage="item.percentage"
              :color="item.color"
              :show-text="false"
              :stroke-width="8"
            />
          </div>
        </el-col>
      </el-row>
    </el-card>

    <!-- 成长能力指标 -->
    <el-card class="finance-section" shadow="hover">
      <template #header>
        <div class="section-header">
          <el-icon><DataLine /></el-icon>
          <span>每股指标</span>
        </div>
      </template>
      <el-row :gutter="20">
        <el-col :span="8" v-for="item in perShareIndicators" :key="item.key">
          <div class="indicator-item">
            <div class="indicator-label">{{ item.label }}</div>
            <div class="indicator-value">{{ formatValue(item.value, item.unit) }}</div>
            <div class="indicator-desc">{{ item.description }}</div>
          </div>
        </el-col>
      </el-row>
    </el-card>

    <!-- 偿债能力指标 -->
    <el-card class="finance-section" shadow="hover">
      <template #header>
        <div class="section-header">
          <el-icon><ScaleToOriginal /></el-icon>
          <span>偿债能力</span>
        </div>
      </template>
      <el-row :gutter="20">
        <el-col :span="12" v-for="item in solvencyIndicators" :key="item.key">
          <div class="indicator-item large">
            <div class="indicator-info">
              <div class="indicator-label">{{ item.label }}</div>
              <div class="indicator-value">{{ formatValue(item.value, item.unit) }}</div>
            </div>
            <el-progress
              type="dashboard"
              :percentage="item.percentage || 0"
              :color="item.color"
              :stroke-width="10"
            />
          </div>
        </el-col>
      </el-row>
    </el-card>

    <!-- 估值指标 -->
    <el-card class="finance-section" shadow="hover">
      <template #header>
        <div class="section-header">
          <el-icon><Money /></el-icon>
          <span>估值指标</span>
        </div>
      </template>
      <el-row :gutter="20">
        <el-col :span="8" v-for="item in valuationIndicators" :key="item.key">
          <div class="indicator-item valuation">
            <div class="indicator-label">{{ item.label }}</div>
            <div class="indicator-value highlight">{{ formatValue(item.value, item.unit) }}</div>
            <div class="indicator-desc">{{ item.description }}</div>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
import { computed } from 'vue'
import { TrendCharts, DataLine, ScaleToOriginal, Money } from '@element-plus/icons-vue'

export default {
  name: 'FinancePanel',

  components: {
    TrendCharts,
    DataLine,
    ScaleToOriginal,
    Money
  },

  props: {
    data: {
      type: Object,
      required: true
    }
  },

  setup(props) {
    /**
     * 盈利能力指标
     */
    const profitabilityIndicators = computed(() => [
      {
        key: 'roe',
        label: '净资产收益率 (ROE)',
        value: props.data.roe,
        unit: '%',
        type: 'higher',
        percentage: props.data.roe ? Math.min(props.data.roe * 5, 100) : 0,
        color: '#67c23a'
      },
      {
        key: 'grossProfitMargin',
        label: '毛利率',
        value: props.data.grossProfitMargin,
        unit: '%',
        type: 'higher',
        percentage: props.data.grossProfitMargin || 0,
        color: '#409eff'
      },
      {
        key: 'netProfitMargin',
        label: '净利率',
        value: props.data.netProfitMargin,
        unit: '%',
        type: 'higher',
        percentage: props.data.netProfitMargin ? Math.min(props.data.netProfitMargin * 2, 100) : 0,
        color: '#e6a23c'
      }
    ])

    /**
     * 每股指标
     */
    const perShareIndicators = computed(() => [
      {
        key: 'eps',
        label: '每股收益 (EPS)',
        value: props.data.eps,
        unit: '元',
        description: '每股创造的净利润'
      },
      {
        key: 'navps',
        label: '每股净资产',
        value: props.data.navps,
        unit: '元',
        description: '每股对应的净资产'
      },
      {
        key: 'revenuePerShare',
        label: '每股营收',
        value: props.data.revenuePerShare,
        unit: '元',
        description: '每股创造的营业收入'
      },
      {
        key: 'operatingCashFlowPerShare',
        label: '每股现金流',
        value: props.data.operatingCashFlowPerShare,
        unit: '元',
        description: '每股经营活动现金流'
      }
    ])

    /**
     * 偿债能力指标
     */
    const solvencyIndicators = computed(() => [
      {
        key: 'debtToAssetRatio',
        label: '资产负债率',
        value: props.data.debtToAssetRatio,
        unit: '%',
        percentage: props.data.debtToAssetRatio || 0,
        color: props.data.debtToAssetRatio > 70 ? '#f56c6c' : props.data.debtToAssetRatio > 50 ? '#e6a23c' : '#67c23a'
      }
    ])

    /**
     * 估值指标
     */
    const valuationIndicators = computed(() => [
      {
        key: 'peRatio',
        label: '市盈率 (PE)',
        value: props.data.peRatio,
        unit: '倍',
        description: '股价/每股收益'
      },
      {
        key: 'pbRatio',
        label: '市净率 (PB)',
        value: props.data.pbRatio,
        unit: '倍',
        description: '股价/每股净资产'
      },
      {
        key: 'dividendYield',
        label: '股息率',
        value: props.data.dividendYield,
        unit: '%',
        description: '年度分红/股价'
      }
    ])

    /**
     * 格式化数值
     */
    const formatValue = (value, unit = '') => {
      if (value === null || value === undefined) return '-'
      return `${value}${unit}`
    }

    /**
     * 根据数值获取样式类
     */
    const getValueClass = (value, type) => {
      if (value === null || value === undefined) return ''
      if (type === 'higher' && value > 15) return 'good'
      if (type === 'higher' && value > 10) return 'normal'
      if (type === 'higher' && value < 5) return 'warning'
      return ''
    }

    return {
      profitabilityIndicators,
      perShareIndicators,
      solvencyIndicators,
      valuationIndicators,
      formatValue,
      getValueClass
    }
  }
}
</script>

