            <div class="card-header">
              <span>数据输入</span>
              <div class="header-actions">
                <el-button type="primary" size="small" @click="loadExample">
                  <el-icon><ViewIcon /></el-icon>
                  加载示例
                </el-button>
                <el-button type="danger" size="small" @click="clearInput">
                  <el-icon><Delete /></el-icon>
                  清空
                </el-button>
              </div>
            </div>
          </template>

          <el-input
            v-model="inputText"
            type="textarea"
            :rows="15"
            placeholder="请粘贴F10数据文本...&#10;支持港澳资讯V8.0 ASCII框线格式&#10;例如：&#10;◇000005 ST星源&#10;更新日期：2025-09-01&#10;..."
            class="data-input"
          />

          <div class="input-actions">
            <el-button type="primary" size="large" @click="parseData" :loading="parsing">
              <el-icon><Search /></el-icon>
              解析数据
            </el-button>
            <el-upload
              class="upload-btn"
              action=""
              :auto-upload="false"
              :on-change="handleFileChange"
              :show-file-list="false"
              accept=".txt"
            >
              <el-button size="large">
                <el-icon><Upload /></el-icon>
                上传文件
              </el-button>
            </el-upload>
          </div>
        </el-card>
      </div>

      <!-- 解析结果区域 -->
      <div class="result-section" v-if="parsedData">
        <!-- 股票元数据 -->
        <el-card class="result-card" v-if="parsedData.metadata">
          <template #header>
            <div class="card-header">
              <span>股票信息</span>
              <el-tag :type="stockTagType" size="small">{{ parsedData.metadata.stockCode }}</el-tag>
            </div>
          </template>
          <div class="metadata-grid">
            <div class="metadata-item">
              <label>股票代码：</label>
              <span class="value">{{ parsedData.metadata.stockCode }}</span>
            </div>
            <div class="metadata-item">
              <label>股票名称：</label>
              <span class="value">{{ parsedData.metadata.stockName }}</span>
            </div>
            <div class="metadata-item">
              <label>更新日期：</label>
              <span class="value">{{ parsedData.metadata.updateDate }}</span>
            </div>
            <div class="metadata-item">
              <label>数据来源：</label>
              <span class="value">{{ parsedData.metadata.dataSource }}</span>
            </div>
          </div>
        </el-card>

        <!-- 风险提示 -->
        <el-card class="result-card risk-card" v-if="parsedData.riskAlerts && parsedData.riskAlerts.length > 0">
          <template #header>
            <div class="card-header">
              <span>
                <el-icon><Warning /></el-icon>
                风险提示
              </span>
              <el-tag type="danger" size="small">{{ parsedData.riskAlerts.length }} 项</el-tag>
            </div>
          </template>
          <div class="risk-list">
            <div
              v-for="(risk, index) in parsedData.riskAlerts"
              :key="index"
              class="risk-item"
              :class="'risk-level-' + getRiskLevelClass(risk.riskLevel)"
            >
              <div class="risk-header">
                <span class="risk-type">{{ risk.riskType }}</span>
                <el-tag :type="getRiskTagType(risk.riskLevel)" size="small">{{ risk.riskLevel }}</el-tag>
              </div>
              <div class="risk-content" v-if="risk.title">{{ risk.title }}</div>
              <div class="risk-detail" v-if="risk.content">{{ risk.content }}</div>
              <div class="risk-date" v-if="risk.alertDate">日期：{{ risk.alertDate }}</div>
            </div>
          </div>
        </el-card>

        <!-- 财务指标 -->
        <el-card class="result-card" v-if="parsedData.financialIndicators && parsedData.financialIndicators.length > 0">
          <template #header>
            <div class="card-header">
              <span>最新主要指标</span>
              <el-tag type="success" size="small">{{ parsedData.financialIndicators.length }} 项</el-tag>
            </div>
          </template>
          <el-table :data="parsedData.financialIndicators" stripe size="small">
            <el-table-column prop="indicatorName" label="指标名称" min-width="150" />
            <el-table-column prop="value" label="数值" min-width="120">
              <template #default="{ row }">
                <span :class="{ 'negative': row.isNegative, 'positive': !row.isNegative && row.value > 0 }">
                  {{ formatValue(row) }}
                </span>
              </template>
            </el-table-column>
            <el-table-column prop="unit" label="单位" width="80" />
            <el-table-column prop="reportDate" label="报告期" min-width="120" />
          </el-table>
        </el-card>

        <!-- 持股变化 -->
        <el-card class="result-card" v-if="parsedData.holdingChanges && parsedData.holdingChanges.length > 0">
          <template #header>
            <div class="card-header">
              <span>机构持股变化</span>
              <el-tag type="info" size="small">{{ parsedData.holdingChanges.length }} 条</el-tag>
            </div>
          </template>
          <el-table :data="parsedData.holdingChanges" stripe size="small">
            <el-table-column prop="reportDate" label="报告日期" min-width="120" />
            <el-table-column prop="institutionCount" label="机构数量" min-width="100" />
            <el-table-column prop="totalHeld" label="累计持有" min-width="150">
              <template #default="{ row }">
                {{ formatNumber(row.totalHeld) }}
              </template>
            </el-table-column>
            <el-table-column prop="holdingRatio" label="持仓比例" min-width="100">
              <template #default="{ row }">
                {{ row.holdingRatio ? row.holdingRatio.toFixed(2) + '%' : '-' }}
              </template>
            </el-table-column>
            <el-table-column prop="changeFromPrevious" label="较上期变化" min-width="150">
              <template #default="{ row }">
                <span :class="getChangeClass(row.changeFromPrevious)">
                  {{ formatChange(row.changeFromPrevious) }}
                </span>
              </template>
            </el-table-column>
          </el-table>
        </el-card>

        <!-- EPS历史 -->
        <el-card class="result-card" v-if="parsedData.epsHistory && parsedData.epsHistory.length > 0">
          <template #header>
            <div class="card-header">
              <span>近五年每股收益对比</span>
              <el-tag type="warning" size="small">{{ parsedData.epsHistory.length }} 年</el-tag>
            </div>
          </template>
          <el-table :data="parsedData.epsHistory" stripe size="small">
            <el-table-column prop="year" label="年度" width="80" />
            <el-table-column prop="annualEps" label="年度EPS" min-width="100">
              <template #default="{ row }">
                <span :class="getEpsClass(row.annualEps)">{{ formatEps(row.annualEps) }}</span>
              </template>
            </el-table-column>
            <el-table-column prop="q3Eps" label="三季报" min-width="100">
              <template #default="{ row }">
                <span :class="getEpsClass(row.q3Eps)">{{ formatEps(row.q3Eps) }}</span>
              </template>
            </el-table-column>
            <el-table-column prop="halfYearEps" label="中期" min-width="100">
              <template #default="{ row }">
                <span :class="getEpsClass(row.halfYearEps)">{{ formatEps(row.halfYearEps) }}</span>
              </template>
            </el-table-column>
            <el-table-column prop="q1Eps" label="一季报" min-width="100">
              <template #default="{ row }">
                <span :class="getEpsClass(row.q1Eps)">{{ formatEps(row.q1Eps) }}</span>
              </template>
            </el-table-column>
          </el-table>
        </el-card>

        <!-- 导出操作 -->
        <el-card class="result-card export-card" v-if="parsedData">
          <template #header>
            <div class="card-header">
              <span>数据导出</span>
            </div>
          </template>
          <div class="export-actions">
            <el-button type="primary" @click="exportData('csv')">
              <el-icon><Download /></el-icon>
              导出CSV
            </el-button>
            <el-button type="success" @click="exportData('json')">
              <el-icon><Download /></el-icon>
              导出JSON
            </el-button>
            <el-button type="warning" @click="exportData('excel')">
              <el-icon><Download /></el-icon>
              导出Excel
            </el-button>
          </div>
        </el-card>
      </div>

      <!-- 空状态 -->
      <div class="empty-state" v-else-if="!parsing">
        <el-empty description="请输入F10数据并点击解析" />
      </div>
    </div>
  </div>
</template>

<script>
import { ref, computed } from 'vue'
import { ElMessage } from 'element-plus'
import {
  Document,
  View as ViewIcon,
  Delete,
  Search,
  Upload,
  Download,
  Warning
} from '@element-plus/icons-vue'
import axios from 'axios'

/**
 * F10数据解析器页面
 * 功能：解析港澳资讯V8.0格式的F10数据，展示解析结果并支持导出
 */
export default {
  name: 'F10Parser',

  components: {
    Document,
    ViewIcon,
    Delete,
    Search,
    Upload,
    Download,
    Warning
  },

  setup() {
    const inputText = ref('')
    const parsing = ref(false)
    const parsedData = ref(null)

    // 示例数据
    const exampleData = `◇000005 ST星源
更新日期：2025-09-01
数据来源：港澳资讯 V8.0

【1.最新主要指标】
┌──────────┬──────────┬──────────┬──────────┐
｜指标名称  ｜2024-06-30｜2024-03-31｜2023-12-31｜
├──────────┼──────────┼──────────┼──────────┤
｜每股收益(元)｜ -0.0129  ｜ -0.0014  ｜  0.0095  ｜
｜每股净资产(元)｜  0.6433  ｜  0.6548  ｜  0.6562  ｜
｜净资产收益率(％)｜ -2.0100  ｜ -0.2200  ｜  1.4500  ｜
｜总股本(亿股)｜ 10.5854  ｜ 10.5854  ｜ 10.5854  ｜
└──────────┴──────────┴──────────┴──────────┘

【2.机构持股变化】
┌──────────┬──────────┬──────────┬──────────┐
｜报告日期  ｜机构数量  ｜累计持有  ｜持仓比例  ｜
├──────────┼──────────┼──────────┼──────────┤
｜2024-06-30｜    3     ｜ 1.26亿   ｜ 11.92%   ｜
｜2024-03-31｜    2     ｜ 1.25亿   ｜ 11.85%   ｜
└──────────┴──────────┴──────────┴──────────┘

【3.近五年每股收益对比】
┌──────┬────────┬────────┬────────┬────────┐
｜ 年度  ｜  年度   ｜  三季   ｜  中期   ｜  一季   ｜
├──────┼────────┼────────┼────────┼────────┤
｜ 2024  ｜        ｜        ｜-0.0129 ｜-0.0014 ｜
｜ 2023  ｜ 0.0095 ｜ 0.0095 ｜ 0.0065 ｜ 0.0021 ｜
｜ 2022  ｜-0.1883  ｜-0.0978  ｜-0.0664  ｜ 0.0050 ｜
└──────┴────────┴────────┴────────┴────────┘

【4.风险提示】
退市：2024-04-26 退市
股权质押：控股股东质押比例 99.87%
2024-04-26 关于对公司的问询函 PDF原文
2024-03-15 关于公司股价异常波动的关注函 PDF原文`

    // 计算属性：股票标签类型
    const stockTagType = computed(() => {
      if (!parsedData.value?.metadata?.stockName) return ''
      const name = parsedData.value.metadata.stockName
      if (name.includes('ST') || name.includes('*ST')) return 'danger'
      if (name.includes('退市')) return 'info'
      return 'primary'
    })

    /**
     * 加载示例数据
     */
    const loadExample = () => {
      inputText.value = exampleData
      ElMessage.success('示例数据已加载')
    }

    /**
     * 清空输入
     */
    const clearInput = () => {
      inputText.value = ''
      parsedData.value = null
      ElMessage.info('已清空')
    }

    /**
     * 解析数据
     */
    const parseData = async () => {
      if (!inputText.value.trim()) {
        ElMessage.warning('请输入F10数据')
        return
      }

      parsing.value = true
      try {
        const response = await axios.post('/api/f10/parse', {
          content: inputText.value
        })
        parsedData.value = response.data
        ElMessage.success('解析成功')
      } catch (error) {
        console.error('解析失败:', error)
        ElMessage.error('解析失败：' + (error.response?.data?.message || error.message))
      } finally {
        parsing.value = false
      }
    }

    /**
     * 处理文件上传
     */
    const handleFileChange = (file) => {
      const reader = new FileReader()
      reader.onload = (e) => {
        inputText.value = e.target.result
        ElMessage.success('文件已加载')
      }
      reader.readAsText(file.raw)
    }

    /**
     * 获取风险等级样式类
     */
    const getRiskLevelClass = (level) => {
      if (!level) return 'low'
      if (level.includes('极高')) return 'extreme'
      if (level.includes('高')) return 'high'
      if (level.includes('中')) return 'medium'
      return 'low'
    }

    /**
     * 获取风险标签类型
     */
    const getRiskTagType = (level) => {
      if (!level) return 'info'
      if (level.includes('极高')) return 'danger'
      if (level.includes('高')) return 'warning'
      if (level.includes('中')) return 'primary'
      return 'success'
    }

    /**
     * 格式化数值
     */
    const formatValue = (row) => {
      if (row.value === null || row.value === undefined) return '-'
      return row.value.toFixed(4)
    }

    /**
     * 格式化数字
     */
    const formatNumber = (num) => {
      if (num === null || num === undefined) return '-'
      if (num >= 100000000) {
        return (num / 100000000).toFixed(2) + '亿'
      }
      if (num >= 10000) {
        return (num / 10000).toFixed(2) + '万'
      }
      return num.toString()
    }

    /**
     * 获取变化样式类
     */
    const getChangeClass = (change) => {
      if (!change) return ''
      return change > 0 ? 'positive' : 'negative'
    }

    /**
     * 格式化变化值
     */
    const formatChange = (change) => {
      if (change === null || change === undefined) return '-'
      const prefix = change > 0 ? '+' : ''
      return prefix + formatNumber(change)
    }

    /**
     * 获取EPS样式类
     */
    const getEpsClass = (eps) => {
      if (eps === null || eps === undefined) return ''
      return eps >= 0 ? 'positive' : 'negative'
    }

    /**
     * 格式化EPS
     */
    const formatEps = (eps) => {
      if (eps === null || eps === undefined) return '-'
      return eps.toFixed(4)
    }

    /**
     * 导出数据
     */
    const exportData = async (format) => {
      try {
        const response = await axios.post(`/api/f10/export/${format}`, {
          data: parsedData.value
        }, {
          responseType: 'blob'
        })

        const blob = new Blob([response.data])
        const url = window.URL.createObjectURL(blob)
        const link = document.createElement('a')
        link.href = url
        link.download = `F10_${parsedData.value.metadata.stockCode}_${format}.${format === 'excel' ? 'xlsx' : format}`
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)
        window.URL.revokeObjectURL(url)

        ElMessage.success(`导出${format.toUpperCase()}成功`)
      } catch (error) {
        console.error('导出失败:', error)
        ElMessage.error('导出失败')
      }
    }

    return {
      inputText,
      parsing,
      parsedData,
      stockTagType,
      loadExample,
      clearInput,
      parseData,
      handleFileChange,
      getRiskLevelClass,
      getRiskTagType,
      formatValue,
      formatNumber,
      getChangeClass,
      formatChange,
      getEpsClass,
      formatEps,
      exportData
    }
  }
}
</script>

