/**
 * 持仓笔记API
 * 功能：提供持仓笔记相关的API调用
 *
 * @author MooTDX
 * @since 1.0.0
 */
import axios from 'axios'

// API基础URL
const BASE_URL = process.env.VUE_APP_API_URL || 'http://localhost:8080'

// 创建axios实例
const apiClient = axios.create({
  baseURL: BASE_URL,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json'
  }
})

/**
 * 创建交易平台
 * @param {Object} data - 平台数据
 * @returns {Promise} 创建结果
 */
export function createPlatform(data) {
  return apiClient.post('/api/stock-notes/platforms', data)
}

/**
 * 获取平台列表
 * @param {boolean} activeOnly - 是否只返回启用的平台
 * @returns {Promise} 平台列表
 */
export function getPlatforms(activeOnly = true) {
  return apiClient.get('/api/stock-notes/platforms', { params: { activeOnly } })
}

/**
 * 根据ID获取平台
 * @param {number} id - 平台ID
 * @returns {Promise} 平台信息
 */
export function getPlatformById(id) {
  return apiClient.get(`/api/stock-notes/platforms/${id}`)
}

/**
 * 更新平台信息
 * @param {number} id - 平台ID
 * @param {Object} data - 更新数据
 * @returns {Promise} 更新结果
 */
export function updatePlatform(id, data) {
  return apiClient.put(`/api/stock-notes/platforms/${id}`, data)
}

/**
 * 删除平台
 * @param {number} id - 平台ID
 * @returns {Promise} 删除结果
 */
export function deletePlatform(id) {
  return apiClient.delete(`/api/stock-notes/platforms/${id}`)
}

/**
 * 创建持仓记录
 * @param {Object} data - 持仓数据
 * @returns {Promise} 创建结果
 */
export function createPosition(data) {
  return apiClient.post('/api/stock-notes/positions', data)
}

/**
 * 获取持仓列表
 * @param {Object} params - 查询参数
 * @returns {Promise} 持仓列表
 */
export function getPositions(params = {}) {
  return apiClient.get('/api/stock-notes/positions', { params })
}

/**
 * 获取持仓中的股票列表
 * @param {number} platformId - 平台ID(可选)
 * @returns {Promise} 持仓列表
 */
export function getHoldingPositions(platformId) {
  return apiClient.get('/api/stock-notes/positions/holding', { params: { platformId } })
}

/**
 * 根据ID获取持仓
 * @param {number} id - 持仓ID
 * @returns {Promise} 持仓信息
 */
export function getPositionById(id) {
  return apiClient.get(`/api/stock-notes/positions/${id}`)
}

/**
 * 更新持仓信息
 * @param {number} id - 持仓ID
 * @param {Object} data - 更新数据
 * @returns {Promise} 更新结果
 */
export function updatePosition(id, data) {
  return apiClient.put(`/api/stock-notes/positions/${id}`, data)
}

/**
 * 更新持仓当前价格和盈亏
 * @param {number} id - 持仓ID
 * @param {number} currentPrice - 当前价格
 * @returns {Promise} 更新结果
 */
export function updatePositionPrice(id, currentPrice) {
  return apiClient.put(`/api/stock-notes/positions/${id}/price`, { currentPrice })
}

/**
 * 卖出持仓
 * @param {number} id - 持仓ID
 * @param {Object} data - 卖出数据
 * @returns {Promise} 卖出结果
 */
export function sellPosition(id, data) {
  return apiClient.post(`/api/stock-notes/positions/${id}/sell`, data)
}

/**
 * 删除持仓
 * @param {number} id - 持仓ID
 * @returns {Promise} 删除结果
 */
export function deletePosition(id) {
  return apiClient.delete(`/api/stock-notes/positions/${id}`)
}

/**
 * 获取持仓汇总统计
 * @param {number} platformId - 平台ID(可选)
 * @returns {Promise} 汇总统计
 */
export function getSummary(platformId) {
  return apiClient.get('/api/stock-notes/summary', { params: { platformId } })
}
