/**
 * 服务器管理API接口
 * 功能：封装与后端服务器的所有HTTP请求
 */
import axios from 'axios'

// 创建axios实例
const apiClient = axios.create({
  baseURL: process.env.VUE_APP_API_URL || '/api',
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json'
  }
})

// 请求拦截器
apiClient.interceptors.request.use(
  config => {
    console.log(`[API请求] ${config.method.toUpperCase()} ${config.url}`)
    return config
  },
  error => {
    console.error('[API请求错误]', error)
    return Promise.reject(error)
  }
)

// 响应拦截器
apiClient.interceptors.response.use(
  response => {
    console.log(`[API响应] ${response.config.url}`, response.data)
    return response.data
  },
  error => {
    console.error('[API响应错误]', error)
    const message = error.response?.data?.message || '网络请求失败'
    return Promise.reject(new Error(message))
  }
)

/**
 * 服务器管理API
 */
export const serverApi = {
  /**
   * 获取服务器列表
   * @param {boolean} enabledOnly - 是否只返回启用的服务器
   * @returns {Promise} 服务器列表
   */
  getServers(enabledOnly = false) {
    return apiClient.get('/servers', { params: { enabled_only: enabledOnly } })
  },

  /**
   * 获取单个服务器详情
   * @param {number} id - 服务器ID
   * @returns {Promise} 服务器详情
   */
  getServerById(id) {
    return apiClient.get(`/servers/${id}`)
  },

  /**
   * 创建服务器
   * @param {Object} data - 服务器配置数据
   * @returns {Promise} 创建结果
   */
  createServer(data) {
    return apiClient.post('/servers', data)
  },

  /**
   * 更新服务器
   * @param {number} id - 服务器ID
   * @param {Object} data - 服务器配置数据
   * @returns {Promise} 更新结果
   */
  updateServer(id, data) {
    return apiClient.put(`/servers/${id}`, data)
  },

  /**
   * 删除服务器
   * @param {number} id - 服务器ID
   * @returns {Promise} 删除结果
   */
  deleteServer(id) {
    return apiClient.delete(`/servers/${id}`)
  },

  /**
   * 设置默认服务器
   * @param {number} id - 服务器ID
   * @returns {Promise} 设置结果
   */
  setDefaultServer(id) {
    return apiClient.post(`/servers/${id}/default`)
  },

  /**
   * 检查服务器状态
   * @param {number} id - 服务器ID
   * @returns {Promise} 状态检查结果
   */
  checkServerStatus(id) {
    return apiClient.post(`/servers/${id}/check`)
  },

  /**
   * 检查所有服务器状态
   * @returns {Promise} 所有服务器状态
   */
  checkAllServers() {
    return apiClient.post('/servers/check-all')
  },

  /**
   * 获取最佳服务器
   * @returns {Promise} 最佳服务器
   */
  getBestServer() {
    return apiClient.get('/servers/best')
  },

  /**
   * 获取默认服务器
   * @returns {Promise} 默认服务器
   */
  getDefaultServer() {
    return apiClient.get('/servers/default')
  },

  /**
   * 获取服务器统计信息
   * @returns {Promise} 统计数据
   */
  getStatistics() {
    return apiClient.get('/servers/statistics')
  }
}

export default serverApi
