/**
 * 定时任务管理API
 * 功能：提供定时任务管理相关的API调用
 *
 * @author MooTDX
 * @since 1.0.0
 */
import axios from 'axios'

// API基础URL
const BASE_URL = process.env.VUE_APP_API_URL || 'http://localhost:8080'

// 创建axios实例
const apiClient = axios.create({
  baseURL: BASE_URL,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json'
  }
})

/**
 * 获取所有定时任务
 * @returns {Promise} 任务列表
 */
export function getAllTasks() {
  return apiClient.get('/api/scheduler/tasks')
}

/**
 * 根据ID获取定时任务
 * @param {string} taskId - 任务ID
 * @returns {Promise} 任务信息
 */
export function getTaskById(taskId) {
  return apiClient.get(`/api/scheduler/tasks/${taskId}`)
}

/**
 * 启用定时任务
 * @param {string} taskId - 任务ID
 * @returns {Promise} 操作结果
 */
export function enableTask(taskId) {
  return apiClient.post(`/api/scheduler/tasks/${taskId}/enable`)
}

/**
 * 禁用定时任务
 * @param {string} taskId - 任务ID
 * @returns {Promise} 操作结果
 */
export function disableTask(taskId) {
  return apiClient.post(`/api/scheduler/tasks/${taskId}/disable`)
}

/**
 * 更新任务执行频率
 * @param {string} taskId - 任务ID
 * @param {number} fixedRate - 固定频率(毫秒)
 * @returns {Promise} 操作结果
 */
export function updateTaskRate(taskId, fixedRate) {
  return apiClient.put(`/api/scheduler/tasks/${taskId}/rate?fixedRate=${fixedRate}`)
}

/**
 * 立即执行定时任务
 * @param {string} taskId - 任务ID
 * @returns {Promise} 操作结果
 */
export function executeTaskImmediately(taskId) {
  return apiClient.post(`/api/scheduler/tasks/${taskId}/execute`)
}
