<template>
  <div class="db-manager-page">
    <!-- 页面标题 -->
    <div class="page-header">
      <h1 class="page-title">
        <el-icon size="28"><Management /></el-icon>
        数据库管理
      </h1>
      <p class="page-desc">查看和管理数据库中的所有表，执行SQL操作</p>
    </div>

    <!-- 新增表提示 -->
    <el-alert
      v-if="newTables.length > 0"
      :title="`检测到 ${newTables.length} 个新增表`"
      type="success"
      :closable="true"
      @close="clearNewTablesNotification"
      class="new-tables-alert"
    >
      <template #default>
        <span>新表列表: {{ newTables.join(', ') }}</span>
      </template>
    </el-alert>

    <!-- 主体内容：左右分栏 -->
    <div class="page-content">
      <!-- 左侧：表列表 -->
      <div class="tables-section">
        <div class="section-header">
          <h3>
            <el-icon><List /></el-icon>
            数据表列表
            <el-tag v-if="filteredTables.length" type="info" size="small">{{ filteredTables.length }}</el-tag>
          </h3>
          <el-button type="primary" size="small" @click="handleRefresh" :loading="tablesLoading">
            <el-icon><Refresh /></el-icon>
            刷新
          </el-button>
        </div>

        <!-- 分类筛选 -->
        <div class="category-filter">
          <el-radio-group v-model="selectedCategory" size="small">
            <el-radio-button label="">全部</el-radio-button>
            <el-radio-button
              v-for="cat in categories"
              :key="cat.name"
              :label="cat.name"
            >
              {{ cat.name }}
            </el-radio-button>
          </el-radio-group>
        </div>

        <!-- 搜索框 -->
        <div class="table-search">
          <el-input
            v-model="tableSearch"
            placeholder="搜索表名..."
            clearable
            size="small"
            :prefix-icon="Search"
          />
        </div>

        <!-- 表列表 -->
        <div class="tables-list" v-loading="tablesLoading">
          <el-card
            v-for="table in filteredTables"
            :key="table.name"
            class="table-card"
            :class="{ active: selectedTable === table.name, 'is-new': table.isNew }"
            shadow="hover"
            @click="selectTable(table.name)"
          >
            <div class="table-card-header">
              <span class="table-name">{{ table.name }}</span>
              <el-tag
                v-if="table.isNew"
                type="success"
                size="small"
                effect="dark"
                class="new-tag"
              >
                新
              </el-tag>
            </div>
            <div class="table-meta">
              <el-tag type="info" size="small" effect="plain">
                {{ table.rowCount !== null ? table.rowCount.toLocaleString() : '-' }} 行
              </el-tag>
              <el-tag type="warning" size="small" effect="plain">
                {{ table.columnsCount }} 列
              </el-tag>
            </div>
            <div class="table-category">
              <el-tag :type="getCategoryType(table.category.name)" size="small">
                {{ table.category.name }}
              </el-tag>
            </div>
          </el-card>

          <el-empty v-if="!tablesLoading && filteredTables.length === 0" description="暂无数据表" />
        </div>
      </div>

      <!-- 右侧：表详情 -->
      <div class="detail-section" v-if="selectedTable">
        <el-tabs v-model="activeTab" type="border-card">
          <!-- 数据标签页 -->
          <el-tab-pane label="表数据" name="data">
            <div class="tab-content data-tab">
              <div class="data-toolbar">
                <div class="toolbar-left">
                  <el-radio-group v-model="showColumnName" size="small">
                    <el-radio-button :label="false">显示备注</el-radio-button>
                    <el-radio-button :label="true">显示字段名</el-radio-button>
                  </el-radio-group>
                </div>
                <div class="toolbar-right">
                  <el-pagination
                    v-model:current-page="currentPage"
                    v-model:page-size="pageSize"
                    :page-sizes="[10, 20, 50, 100]"
                    :total="totalRecords"
                    layout="total, sizes, prev, pager, next"
                    size="small"
                    @size-change="handleSizeChange"
                    @current-change="handlePageChange"
                  />
                </div>
              </div>

              <el-table
                :data="tableData"
                border
                stripe
                v-loading="dataLoading"
                class="data-table"
                max-height="calc(100vh - 320px)"
              >
                <el-table-column
                  v-for="col in tableColumns"
                  :key="col.name"
                  :prop="col.name"
                  :label="showColumnName ? col.name : (col.comment || col.name)"
                  min-width="120"
                  show-overflow-tooltip
                  sortable
                />
              </el-table>
            </div>
          </el-tab-pane>

          <!-- 结构标签页 -->
          <el-tab-pane label="表结构" name="structure">
            <div class="tab-content structure-tab">
              <div class="structure-header">
                <h4>列信息</h4>
                <el-tag type="info">共 {{ structureData.columns?.length || 0 }} 列</el-tag>
              </div>
              <el-table :data="structureData.columns" border stripe>
                <el-table-column prop="name" label="字段名" min-width="150" />
                <el-table-column prop="type" label="数据类型" min-width="120" />
                <el-table-column prop="nullable" label="可空" width="80">
                  <template #default="{ row }">
                    <el-tag :type="row.nullable ? 'info' : 'danger'" size="small">
                      {{ row.nullable ? '是' : '否' }}
                    </el-tag>
                  </template>
                </el-table-column>
                <el-table-column prop="defaultValue" label="默认值" min-width="120">
                  <template #default="{ row }">
                    {{ row.defaultValue || '-' }}
                  </template>
                </el-table-column>
                <el-table-column prop="comment" label="注释" min-width="200">
                  <template #default="{ row }">
                    {{ row.comment || '-' }}
                  </template>
                </el-table-column>
                <el-table-column prop="isPrimaryKey" label="主键" width="80">
                  <template #default="{ row }">
                    <el-tag v-if="row.isPrimaryKey" type="success" size="small">是</el-tag>
                    <span v-else>-</span>
                  </template>
                </el-table-column>
              </el-table>
            </div>
          </el-tab-pane>

          <!-- 索引标签页 -->
          <el-tab-pane label="索引" name="indexes">
            <div class="tab-content indexes-tab">
              <div class="structure-header">
                <h4>索引信息</h4>
                <el-tag type="info">共 {{ structureData.indexes?.length || 0 }} 个索引</el-tag>
              </div>
              <el-table :data="structureData.indexes" border stripe>
                <el-table-column prop="name" label="索引名" min-width="200" />
                <el-table-column prop="columns" label="索引列" min-width="200">
                  <template #default="{ row }">
                    {{ row.columns?.join(', ') }}
                  </template>
                </el-table-column>
                <el-table-column prop="unique" label="唯一" width="100">
                  <template #default="{ row }">
                    <el-tag :type="row.unique ? 'success' : 'info'" size="small">
                      {{ row.unique ? '是' : '否' }}
                    </el-tag>
                  </template>
                </el-table-column>
              </el-table>
            </div>
          </el-tab-pane>

          <!-- SQL执行标签页 -->
          <el-tab-pane label="SQL执行" name="sql">
            <div class="tab-content sql-executor">
              <!-- 执行模式切换 -->
              <div class="execution-mode">
                <el-radio-group v-model="executionMode" size="small">
                  <el-radio-button label="single">单条执行</el-radio-button>
                  <el-radio-button label="batch">批量执行</el-radio-button>
                  <el-radio-button label="transaction">事务执行</el-radio-button>
                </el-radio-group>
                <el-tag v-if="executionMode !== 'single'" type="info" size="small">
                  检测到 {{ sqlStatements.length }} 条SQL
                </el-tag>
              </div>

              <!-- SQL编辑器 -->
              <div class="sql-editor-section">
                <div class="editor-header">
                  <h4>
                    <el-icon><Edit /></el-icon>
                    SQL编辑器
                  </h4>
                  <div class="editor-actions">
                    <el-button
                      type="primary"
                      size="small"
                      @click="executeSql"
                      :loading="sqlExecuting"
                      :disabled="!sqlInput.trim()"
                    >
                      <el-icon><VideoPlay /></el-icon>
                      {{ executionMode === 'single' ? '执行 (Ctrl+Enter)' : '批量执行' }}
                    </el-button>
                    <el-button size="small" @click="clearSql">
                      <el-icon><Delete /></el-icon>
                      清空
                    </el-button>
                    <el-dropdown size="small" @command="insertTemplate">
                      <el-button size="small">
                        <el-icon><Document /></el-icon>
                        模板
                      </el-button>
                      <template #dropdown>
                        <el-dropdown-menu>
                          <el-dropdown-item
                            v-for="template in sqlTemplates"
                            :key="template.id"
                            :command="template.id"
                          >
                            {{ template.name }}
                          </el-dropdown-item>
                        </el-dropdown-menu>
                      </template>
                    </el-dropdown>
                  </div>
                </div>

                <el-input
                  v-model="sqlInput"
                  type="textarea"
                  :rows="8"
                  class="sql-editor"
                  placeholder="-- 支持多SQL执行，使用分号(;)分隔每条SQL&#10;-- 快捷键：Ctrl+Enter 执行&#10;SELECT * FROM users WHERE id = 1;&#10;UPDATE users SET name = 'test' WHERE id = 2;"
                  @keydown.ctrl.enter="handleCtrlEnter"
                />

                <!-- SQL分隔提示 -->
                <div class="sql-tips" v-if="executionMode !== 'single' && sqlStatements.length > 1">
                  <el-alert
                    title="批量执行提示"
                    type="info"
                    :closable="false"
                    show-icon
                  >
                    <template #default>
                      多条SQL使用分号(;)分隔，共检测到 {{ sqlStatements.length }} 条SQL语句
                    </template>
                  </el-alert>
                </div>
              </div>

              <!-- 执行结果 -->
              <div class="sql-result-section" v-if="sqlResult || batchResults.length > 0">
                <!-- 单条执行结果 -->
                <template v-if="executionMode === 'single' && sqlResult">
                  <div class="result-header">
                    <h4>执行结果</h4>
                    <div class="result-summary">
                      <el-tag :type="sqlResult.success ? 'success' : 'danger'">
                        {{ sqlResult.success ? '成功' : '失败' }}
                      </el-tag>
                      <span class="execution-time">{{ sqlResult.executionTime }}ms</span>
                    </div>
                  </div>

                  <el-alert
                    :title="sqlResult.message"
                    :type="sqlResult.success ? 'success' : 'error'"
                    :closable="false"
                    show-icon
                  />

                  <!-- 查询结果表格 -->
                  <el-table
                    v-if="sqlResult.data && sqlResult.data.length > 0"
                    :data="sqlResult.data"
                    border
                    stripe
                    max-height="300"
                    class="result-table"
                  >
                    <el-table-column
                      v-for="key in Object.keys(sqlResult.data[0])"
                      :key="key"
                      :prop="key"
                      :label="key"
                      min-width="120"
                      show-overflow-tooltip
                    />
                  </el-table>
                </template>

                <!-- 批量执行结果 -->
                <template v-if="executionMode !== 'single' && batchResults.length > 0">
                  <div class="result-header">
                    <h4>执行结果</h4>
                    <div class="result-summary">
                      <el-tag type="success">成功: {{ successCount }}</el-tag>
                      <el-tag type="danger" style="margin-left: 8px;">失败: {{ failCount }}</el-tag>
                      <span class="total-time">总耗时: {{ totalExecutionTime }}ms</span>
                      <el-tag v-if="newTablesFromBatch.length > 0" type="warning" style="margin-left: 8px;">
                        发现 {{ newTablesFromBatch.length }} 个新表
                      </el-tag>
                    </div>
                  </div>

                  <!-- 新表提示 -->
                  <el-alert
                    v-if="newTablesFromBatch.length > 0"
                    :title="`批量执行中创建了 ${newTablesFromBatch.length} 个新表`"
                    type="warning"
                    :closable="false"
                    show-icon
                    style="margin-bottom: 12px;"
                  >
                    <template #default>
                      新表: {{ newTablesFromBatch.join(', ') }}
                      <el-button type="primary" link size="small" @click="handleRefresh">
                        立即刷新表列表
                      </el-button>
                    </template>
                  </el-alert>

                  <!-- 结果折叠面板 -->
                  <el-collapse v-model="activeResults">
                    <el-collapse-item
                      v-for="(result, index) in batchResults"
                      :key="index"
                      :name="index"
                      :class="{ 'result-success': result.success, 'result-error': !result.success }"
                    >
                      <template #title>
                        <div class="collapse-title">
                          <el-icon v-if="result.success" color="#67c23a"><CircleCheck /></el-icon>
                          <el-icon v-else color="#f56c6c"><CircleClose /></el-icon>
                          <span class="sql-index">#{{ index + 1 }}</span>
                          <el-tag size="small" effect="plain">{{ result.sql_type }}</el-tag>
                          <span class="sql-preview">{{ truncateSql(result.sql) }}</span>
                          <el-tag size="small" :type="result.success ? 'success' : 'danger'">
                            {{ result.execution_time }}ms
                          </el-tag>
                        </div>
                      </template>

                      <div class="result-detail">
                        <div class="sql-full">{{ result.sql }}</div>
                        <div v-if="result.success && result.data" class="result-data">
                          <el-table
                            :data="result.data"
                            border
                            stripe
                            max-height="200"
                          >
                            <el-table-column
                              v-for="col in Object.keys(result.data[0] || {})"
                              :key="col"
                              :prop="col"
                              :label="col"
                              min-width="120"
                            />
                          </el-table>
                          <div class="result-count">共返回 {{ result.row_count }} 行</div>
                        </div>
                        <div v-if="!result.success" class="error-detail">
                          <el-alert :title="result.message" type="error" :closable="false" />
                        </div>
                      </div>
                    </el-collapse-item>
                  </el-collapse>
                </template>
              </div>

              <!-- SQL历史记录 -->
              <div class="sql-history-section" v-if="sqlHistory.length > 0">
                <div class="history-header">
                  <h4>
                    <el-icon><Clock /></el-icon>
                    执行历史
                  </h4>
                  <el-button type="danger" link size="small" @click="clearHistory">
                    清空历史
                  </el-button>
                </div>
                <div class="history-list">
                  <div
                    v-for="item in sqlHistory"
                    :key="item.id"
                    class="history-item"
                    :class="{ success: item.success, error: !item.success }"
                    @click="loadHistorySql(item)"
                  >
                    <div class="history-sql">{{ truncateSql(item.sql, 60) }}</div>
                    <div class="history-meta">
                      <el-tag :type="item.success ? 'success' : 'danger'" size="small">
                        {{ item.success ? '成功' : '失败' }}
                      </el-tag>
                      <span class="history-type">{{ item.sqlType }}</span>
                      <span class="history-time">{{ formatTime(item.executedAt) }}</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </el-tab-pane>
        </el-tabs>
      </div>

      <!-- 未选择表时的提示 -->
      <div class="detail-section empty-state" v-else>
        <el-empty description="请选择左侧数据表查看详情">
          <template #image>
            <el-icon :size="80" color="#dcdfe6"><Management /></el-icon>
          </template>
        </el-empty>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import {
  Management, List, Refresh, Search, Edit, VideoPlay, Delete,
  Document, Clock, CircleCheck, CircleClose
} from '@element-plus/icons-vue'
import {
  getTables, refreshTables, getTableStructure, getTableData,
  executeSql as apiExecuteSql, executeBatchSql, getSqlHistory,
  clearSqlHistory, getSqlTemplates, applySqlTemplate
} from '@/api/dbManager'

// ========== 响应式数据 ==========

/** 表列表数据 */
const tables = ref([])
/** 分类列表 */
const categories = ref([])
/** 选中的分类 */
const selectedCategory = ref('')
/** 表搜索关键词 */
const tableSearch = ref('')
/** 表列表加载状态 */
const tablesLoading = ref(false)
/** 当前选中的表名 */
const selectedTable = ref('')
/** 当前激活的标签页 */
const activeTab = ref('data')
/** 是否显示字段名（否则显示备注） */
const showColumnName = ref(false)
/** 新增表列表 */
const newTables = ref([])

/** 表数据加载状态 */
const dataLoading = ref(false)
/** 表数据 */
const tableData = ref([])
/** 表列定义 */
const tableColumns = ref([])
/** 当前页码 */
const currentPage = ref(1)
/** 每页条数 */
const pageSize = ref(50)
/** 总记录数 */
const totalRecords = ref(0)

/** 表结构数据 */
const structureData = ref({
  name: '',
  comment: '',
  columns: [],
  indexes: [],
  primaryKeys: []
})

// SQL执行相关
const sqlInput = ref('')
const sqlExecuting = ref(false)
const sqlResult = ref(null)
const sqlHistory = ref([])
const executionMode = ref('single')
const batchResults = ref([])
const activeResults = ref([0])
const newTablesFromBatch = ref([])

// SQL模板相关
const sqlTemplates = ref([])

// ========== 计算属性 ==========

/** 过滤后的表列表 */
const filteredTables = computed(() => {
  let result = tables.value

  // 按分类筛选
  if (selectedCategory.value) {
    result = result.filter(t => t.category?.name === selectedCategory.value)
  }

  // 按搜索关键词筛选
  if (tableSearch.value) {
    const keyword = tableSearch.value.toLowerCase()
    result = result.filter(t => t.name.toLowerCase().includes(keyword))
  }

  return result
})

/** 成功数 */
const successCount = computed(() => {
  return batchResults.value.filter(r => r.success).length
})

/** 失败数 */
const failCount = computed(() => {
  return batchResults.value.filter(r => !r.success).length
})

/** 总执行时间 */
const totalExecutionTime = computed(() => {
  return batchResults.value.reduce((sum, r) => sum + (r.execution_time || 0), 0).toFixed(2)
})

/** 解析SQL语句 */
const sqlStatements = computed(() => {
  if (!sqlInput.value.trim()) return []

  const statements = []
  let current = ''
  let inString = false
  let stringChar = ''

  for (let i = 0; i < sqlInput.value.length; i++) {
    const char = sqlInput.value[i]
    const nextChar = sqlInput.value[i + 1]

    // 处理字符串
    if (!inString && (char === "'" || char === '"')) {
      inString = true
      stringChar = char
    } else if (inString && char === stringChar) {
      // 检查是否是转义
      if (nextChar === stringChar) {
        current += char
        i++ // 跳过下一个引号
      } else {
        inString = false
        stringChar = ''
      }
    }

    // 处理语句分隔
    if (char === ';' && !inString) {
      const trimmed = current.trim()
      if (trimmed) {
        statements.push(trimmed)
      }
      current = ''
    } else {
      current += char
    }
  }

  // 处理最后一条（没有分号结尾）
  const trimmed = current.trim()
  if (trimmed) {
    statements.push(trimmed)
  }

  return statements
})

// ========== 方法 ==========

/**
 * 加载所有表信息
 */
const loadTables = async () => {
  tablesLoading.value = true
  try {
    const response = await getTables()
    tables.value = response.data?.tables || []
    categories.value = response.data?.categories || []

    // 检查是否有新表
    if (response.data?.hasNewTables) {
      newTables.value = tables.value.filter(t => t.isNew).map(t => t.name)
    }
  } catch (error) {
    console.error('加载表列表失败:', error)
    ElMessage.error('加载表列表失败: ' + error.message)
  } finally {
    tablesLoading.value = false
  }
}

/**
 * 刷新表列表并检测新增表
 */
const handleRefresh = async () => {
  tablesLoading.value = true
  try {
    const response = await refreshTables()
    tables.value = response.data?.tables || []
    categories.value = response.data?.categories || []

    // 显示新增表提示
    if (response.data?.hasNewTables) {
      newTables.value = tables.value.filter(t => t.isNew).map(t => t.name)
      ElMessage.success(`刷新成功，发现 ${response.data.newTableCount} 个新表`)
    } else {
      newTables.value = []
      ElMessage.success('刷新成功，暂无新表')
    }
  } catch (error) {
    console.error('刷新表列表失败:', error)
    ElMessage.error('刷新表列表失败: ' + error.message)
  } finally {
    tablesLoading.value = false
  }
}

/**
 * 清除新增表通知
 */
const clearNewTablesNotification = () => {
  newTables.value = []
}

/**
 * 选择表
 */
const selectTable = (tableName) => {
  selectedTable.value = tableName
  currentPage.value = 1
  activeTab.value = 'data'
  loadTableData()
  loadTableStructure()
}

/**
 * 加载表数据
 */
const loadTableData = async () => {
  if (!selectedTable.value) return

  dataLoading.value = true
  try {
    const response = await getTableData(selectedTable.value, {
      page: currentPage.value,
      pageSize: pageSize.value
    })

    tableData.value = response.data?.data || []
    tableColumns.value = response.data?.columns || []
    totalRecords.value = response.data?.total || 0
  } catch (error) {
    console.error('加载表数据失败:', error)
    ElMessage.error('加载表数据失败: ' + error.message)
  } finally {
    dataLoading.value = false
  }
}

/**
 * 加载表结构
 */
const loadTableStructure = async () => {
  if (!selectedTable.value) return

  try {
    const response = await getTableStructure(selectedTable.value)
    structureData.value = response.data || {
      name: selectedTable.value,
      comment: '',
      columns: [],
      indexes: [],
      primaryKeys: []
    }
  } catch (error) {
    console.error('加载表结构失败:', error)
    ElMessage.error('加载表结构失败: ' + error.message)
  }
}

/**
 * 处理分页大小变化
 */
const handleSizeChange = (size) => {
  pageSize.value = size
  currentPage.value = 1
  loadTableData()
}

/**
 * 处理页码变化
 */
const handlePageChange = (page) => {
  currentPage.value = page
  loadTableData()
}

/**
 * 获取分类标签类型
 */
const getCategoryType = (categoryName) => {
  const typeMap = {
    '股票基础': 'primary',
    '股票扩展': 'success',
    '板块管理': 'warning',
    '量化数据': 'danger',
    '交易记录': 'info',
    '系统配置': '',
    '其他': 'info'
  }
  return typeMap[categoryName] || 'info'
}

/**
 * 加载SQL模板
 */
const loadSqlTemplates = async () => {
  try {
    const response = await getSqlTemplates()
    sqlTemplates.value = response.data?.templates || []
  } catch (error) {
    console.error('加载SQL模板失败:', error)
  }
}

/**
 * 插入SQL模板
 */
const insertTemplate = async (templateId) => {
  try {
    const response = await applySqlTemplate({
      template_id: templateId,
      table_name: selectedTable.value
    })

    const sql = response.data?.sql || ''
    if (sqlInput.value.trim()) {
      sqlInput.value += '\n\n' + sql
    } else {
      sqlInput.value = sql
    }
  } catch (error) {
    ElMessage.error('应用模板失败: ' + error.message)
  }
}

/**
 * 执行SQL
 */
const executeSql = async () => {
  if (executionMode.value === 'single') {
    await executeSingleSql()
  } else {
    await executeBatch()
  }
}

/**
 * 单条执行SQL
 */
const executeSingleSql = async () => {
  if (!sqlInput.value.trim()) {
    ElMessage.warning('请输入SQL语句')
    return
  }

  sqlExecuting.value = true
  sqlResult.value = null
  batchResults.value = []

  try {
    const response = await apiExecuteSql({ sql: sqlInput.value.trim() })
    sqlResult.value = response.data

    if (response.data?.success) {
      ElMessage.success(response.data.message)
    } else {
      ElMessage.error(response.data?.message || '执行失败')
    }

    loadSqlHistory()
  } catch (error) {
    ElMessage.error('SQL执行失败: ' + error.message)
  } finally {
    sqlExecuting.value = false
  }
}

/**
 * 批量执行SQL
 */
const executeBatch = async () => {
  if (sqlStatements.value.length === 0) {
    ElMessage.warning('请输入SQL语句')
    return
  }

  sqlExecuting.value = true
  batchResults.value = []
  sqlResult.value = null
  newTablesFromBatch.value = []

  try {
    const response = await executeBatchSql({
      statements: sqlStatements.value,
      mode: executionMode.value
    })

    batchResults.value = response.data?.results || []

    // 检查是否有新表
    if (response.data?.hasNewTables) {
      newTablesFromBatch.value = response.data.newTables || []
    }

    const success = batchResults.value.filter(r => r.success).length
    const fail = batchResults.value.length - success

    if (fail === 0) {
      ElMessage.success(`全部执行成功，共 ${success} 条`)
    } else {
      ElMessage.warning(`执行完成，成功: ${success}, 失败: ${fail}`)
    }

    loadSqlHistory()
  } catch (error) {
    console.error('批量执行失败:', error)
    ElMessage.error('批量执行失败: ' + error.message)
  } finally {
    sqlExecuting.value = false
  }
}

/**
 * 处理Ctrl+Enter快捷键
 */
const handleCtrlEnter = (e) => {
  e.preventDefault()
  executeSql()
}

/**
 * 清空SQL
 */
const clearSql = () => {
  sqlInput.value = ''
  sqlResult.value = null
  batchResults.value = []
  newTablesFromBatch.value = []
}

/**
 * 加载SQL历史记录
 */
const loadSqlHistory = async () => {
  try {
    const response = await getSqlHistory(20)
    sqlHistory.value = response.data?.history || []
  } catch (error) {
    console.error('加载SQL历史失败:', error)
  }
}

/**
 * 加载历史SQL到编辑器
 */
const loadHistorySql = (item) => {
  sqlInput.value = item.sql
}

/**
 * 清空历史记录
 */
const clearHistory = async () => {
  try {
    await ElMessageBox.confirm('确定要清空所有SQL执行历史吗？', '确认', { type: 'warning' })
    await clearSqlHistory()
    sqlHistory.value = []
    ElMessage.success('历史记录已清空')
  } catch (error) {
    if (error !== 'cancel') {
      console.error('清空历史失败:', error)
    }
  }
}

/**
 * 截断SQL显示
 */
const truncateSql = (sql, maxLength = 50) => {
  if (!sql) return ''
  if (sql.length <= maxLength) return sql
  return sql.substring(0, maxLength) + '...'
}

/**
 * 格式化时间
 */
const formatTime = (timeStr) => {
  if (!timeStr) return '-'
  const date = new Date(timeStr)
  return date.toLocaleString('zh-CN')
}

// ========== 生命周期 ==========

onMounted(() => {
  loadTables()
  loadSqlTemplates()
  loadSqlHistory()
})

// 监听选中表变化，更新当前表名用于模板
watch(selectedTable, (newVal) => {
  if (newVal && sqlTemplates.value.length === 0) {
    loadSqlTemplates()
  }
})
</script>

