<template>
  <!-- 服务器列表页面 -->
  <div class="server-list-page">
    <!-- 页面标题和操作栏 -->
    <div class="page-header">
      <h1 class="page-title">
        <el-icon><List /></el-icon>
        服务器列表
      </h1>
      <div class="page-actions">
        <el-button type="primary" @click="showAddDialog">
          <el-icon><Plus /></el-icon>
          添加服务器
        </el-button>
        <el-button type="success" @click="checkAllServers" :loading="checking">
          <el-icon><Refresh /></el-icon>
          检查所有状态
        </el-button>
      </div>
    </div>

    <!-- 统计信息卡片 -->
    <el-row :gutter="20" class="statistics-row">
      <el-col :span="4" v-for="stat in statisticsList" :key="stat.key">
        <el-card class="stat-card" :class="stat.type">
          <div class="stat-value">{{ stat.value }}</div>
          <div class="stat-label">{{ stat.label }}</div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 服务器列表表格 -->
    <el-card class="server-table-card">
      <template #header>
        <div class="card-header">
          <span>服务器列表</span>
          <el-radio-group v-model="filterEnabled" size="small" @change="handleFilterChange">
            <el-radio-button :label="false">全部</el-radio-button>
            <el-radio-button :label="true">仅启用</el-radio-button>
          </el-radio-group>
        </div>
      </template>

      <el-table
        :data="servers"
        v-loading="loading"
        stripe
        border
        style="width: 100%"
      >
        <!-- ID列 -->
        <el-table-column prop="id" label="ID" width="60" />

        <!-- 服务器名称列 -->
        <el-table-column prop="name" label="服务器名称" min-width="150">
          <template #default="{ row }">
            <div class="server-name">
              <el-tag v-if="row.isDefault" type="success" size="small" effect="dark">默认</el-tag>
              <span>{{ row.name }}</span>
            </div>
          </template>
        </el-table-column>

        <!-- 地址列 -->
        <el-table-column label="地址" min-width="180">
          <template #default="{ row }">
            {{ row.host }}:{{ row.port }}
          </template>
        </el-table-column>

        <!-- 位置列 -->
        <el-table-column prop="location" label="位置" width="100" />

        <!-- 状态列 -->
        <el-table-column label="状态" width="100">
          <template #default="{ row }">
            <el-tag :type="getStatusType(row.status)" effect="dark">
              {{ getStatusText(row.status) }}
            </el-tag>
          </template>
        </el-table-column>

        <!-- 响应时间列 -->
        <el-table-column label="响应时间" width="120">
          <template #default="{ row }">
            <span v-if="row.responseTime">{{ row.responseTime.toFixed(2) }}ms</span>
            <span v-else>-</span>
          </template>
        </el-table-column>

        <!-- 成功率列 -->
        <el-table-column label="成功率" width="100">
          <template #default="{ row }">
            <span v-if="row.successRate">{{ row.successRate.toFixed(1) }}%</span>
            <span v-else>-</span>
          </template>
        </el-table-column>

        <!-- 启用状态列 -->
        <el-table-column label="启用" width="80">
          <template #default="{ row }">
            <el-switch
              v-model="row.isEnabled"
              @change="handleEnableChange(row)"
              :loading="row.updating"
            />
          </template>
        </el-table-column>

        <!-- 操作列 -->
        <el-table-column label="操作" width="280" fixed="right">
          <template #default="{ row }">
            <el-button-group>
              <el-button type="primary" size="small" @click="checkServer(row)">
                <el-icon><Refresh /></el-icon>
              </el-button>
              <el-button type="warning" size="small" @click="editServer(row)">
                <el-icon><Edit /></el-icon>
              </el-button>
              <el-button
                type="success"
                size="small"
                @click="setDefault(row)"
                :disabled="row.isDefault"
              >
                <el-icon><Star /></el-icon>
              </el-button>
              <el-button type="danger" size="small" @click="deleteServer(row)">
                <el-icon><Delete /></el-icon>
              </el-button>
            </el-button-group>
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <!-- 添加/编辑服务器对话框 -->
    <el-dialog
      v-model="dialogVisible"
      :title="isEdit ? '编辑服务器' : '添加服务器'"
      width="500px"
      destroy-on-close
    >
      <el-form
        ref="formRef"
        :model="formData"
        :rules="formRules"
        label-width="100px"
      >
        <el-form-item label="服务器名称" prop="name">
          <el-input v-model="formData.name" placeholder="请输入服务器名称" />
        </el-form-item>
        <el-form-item label="IP地址" prop="host">
          <el-input v-model="formData.host" placeholder="例如: 119.147.212.81" />
        </el-form-item>
        <el-form-item label="端口" prop="port">
          <el-input-number v-model="formData.port" :min="1" :max="65535" style="width: 100%" />
        </el-form-item>
        <el-form-item label="位置" prop="location">
          <el-input v-model="formData.location" placeholder="例如: 电信、联通" />
        </el-form-item>
        <el-form-item label="权重" prop="weight">
          <el-input-number v-model="formData.weight" :min="1" :max="1000" style="width: 100%" />
        </el-form-item>
        <el-form-item label="超时时间" prop="timeout">
          <el-input-number v-model="formData.timeout" :min="1" :max="60" style="width: 100%">
            <template #suffix>秒</template>
          </el-input-number>
        </el-form-item>
        <el-form-item label="重试次数" prop="maxRetries">
          <el-input-number v-model="formData.maxRetries" :min="0" :max="10" style="width: 100%" />
        </el-form-item>
        <el-form-item label="描述" prop="description">
          <el-input
            v-model="formData.description"
            type="textarea"
            :rows="3"
            placeholder="请输入服务器描述"
          />
        </el-form-item>
        <el-form-item label="启用">
          <el-switch v-model="formData.isEnabled" />
        </el-form-item>
        <el-form-item label="设为默认">
          <el-switch v-model="formData.isDefault" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="submitForm" :loading="submitting">
          {{ isEdit ? '更新' : '创建' }}
        </el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script>
/**
 * 服务器列表页面组件
 * 功能：展示TDX服务器列表，支持增删改查、状态检查、设置默认服务器
 */
import { ref, reactive, onMounted, computed } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { serverApi } from '../api/server'

export default {
  name: 'ServerList',

  setup() {
    // 响应式数据
    const loading = ref(false)
    const checking = ref(false)
    const submitting = ref(false)
    const dialogVisible = ref(false)
    const isEdit = ref(false)
    const filterEnabled = ref(false)
    const servers = ref([])
    const statistics = ref({})
    const formRef = ref(null)

    // 表单数据
    const formData = reactive({
      id: null,
      name: '',
      host: '',
      port: 7709,
      location: '',
      weight: 100,
      timeout: 10,
      maxRetries: 3,
      description: '',
      isEnabled: true,
      isDefault: false
    })

    // 表单验证规则
    const formRules = {
      name: [
        { required: true, message: '请输入服务器名称', trigger: 'blur' },
        { max: 100, message: '名称不能超过100个字符', trigger: 'blur' }
      ],
      host: [
        { required: true, message: '请输入IP地址', trigger: 'blur' },
        {
          pattern: /^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/,
          message: 'IP地址格式不正确',
          trigger: 'blur'
        }
      ],
      port: [
        { required: true, message: '请输入端口', trigger: 'blur' }
      ]
    }

    // 统计信息列表
    const statisticsList = computed(() => [
      { key: 'total', label: '服务器总数', value: statistics.value.totalServers || 0, type: 'primary' },
      { key: 'enabled', label: '已启用', value: statistics.value.enabledServers || 0, type: 'success' },
      { key: 'online', label: '在线', value: statistics.value.onlineNodes || 0, type: 'success' },
      { key: 'offline', label: '离线', value: statistics.value.offlineNodes || 0, type: 'danger' },
      { key: 'unstable', label: '不稳定', value: statistics.value.unstableNodes || 0, type: 'warning' },
      { key: 'avgTime', label: '平均响应', value: `${(statistics.value.avgResponseTime || 0).toFixed(0)}ms`, type: 'info' }
    ])

    // 获取服务器列表
    const fetchServers = async () => {
      loading.value = true
      try {
        const res = await serverApi.getServers(filterEnabled.value)
        if (res.code === 200) {
          servers.value = res.data.map(s => ({ ...s, updating: false }))
        }
      } catch (error) {
        ElMessage.error('获取服务器列表失败: ' + error.message)
      } finally {
        loading.value = false
      }
    }

    // 获取统计信息
    const fetchStatistics = async () => {
      try {
        const res = await serverApi.getStatistics()
        if (res.code === 200) {
          statistics.value = res.data
        }
      } catch (error) {
        console.error('获取统计信息失败:', error)
      }
    }

    // 获取状态标签类型
    const getStatusType = (status) => {
      const statusLower = (status || '').toLowerCase()
      const typeMap = {
        'online': 'success',
        'offline': 'danger',
        'unstable': 'warning',
        'maintenance': 'info',
        'unknown': 'info'
      }
      return typeMap[statusLower] || 'info'
    }

    // 获取状态显示文本
    const getStatusText = (status) => {
      const statusLower = (status || '').toLowerCase()
      const textMap = {
        'online': '在线',
        'offline': '离线',
        'unstable': '不稳定',
        'maintenance': '维护中',
        'unknown': '未知'
      }
      return textMap[statusLower] || status
    }

    // 显示添加对话框
    const showAddDialog = () => {
      isEdit.value = false
      resetForm()
      dialogVisible.value = true
    }

    // 编辑服务器
    const editServer = (row) => {
      isEdit.value = true
      Object.assign(formData, row)
      dialogVisible.value = true
    }

    // 重置表单
    const resetForm = () => {
      formData.id = null
      formData.name = ''
      formData.host = ''
      formData.port = 7709
      formData.location = ''
      formData.weight = 100
      formData.timeout = 10
      formData.maxRetries = 3
      formData.description = ''
      formData.isEnabled = true
      formData.isDefault = false
    }

    // 提交表单
    const submitForm = async () => {
      const valid = await formRef.value.validate().catch(() => false)
      if (!valid) return

      submitting.value = true
      try {
        const apiCall = isEdit.value
          ? serverApi.updateServer(formData.id, formData)
          : serverApi.createServer(formData)

        const res = await apiCall
        if (res.code === 200) {
          ElMessage.success(isEdit.value ? '更新成功' : '创建成功')
          dialogVisible.value = false
          fetchServers()
          fetchStatistics()
        } else {
          ElMessage.error(res.message)
        }
      } catch (error) {
        ElMessage.error('操作失败: ' + error.message)
      } finally {
        submitting.value = false
      }
    }

    // 删除服务器
    const deleteServer = async (row) => {
      try {
        await ElMessageBox.confirm(
          `确定要删除服务器 "${row.name}" 吗？`,
          '确认删除',
          { type: 'warning' }
        )

        const res = await serverApi.deleteServer(row.id)
        if (res.code === 200) {
          ElMessage.success('删除成功')
          fetchServers()
          fetchStatistics()
        }
      } catch (error) {
        if (error !== 'cancel') {
          ElMessage.error('删除失败: ' + error.message)
        }
      }
    }

    // 设置默认服务器
    const setDefault = async (row) => {
      try {
        const res = await serverApi.setDefaultServer(row.id)
        if (res.code === 200) {
          ElMessage.success('设置默认服务器成功')
          fetchServers()
        }
      } catch (error) {
        ElMessage.error('设置失败: ' + error.message)
      }
    }

    // 检查单个服务器状态
    const checkServer = async (row) => {
      row.updating = true
      try {
        const res = await serverApi.checkServerStatus(row.id)
        if (res.code === 200) {
          ElMessage.success('状态检查完成')
          fetchServers()
          fetchStatistics()
        }
      } catch (error) {
        ElMessage.error('检查失败: ' + error.message)
      } finally {
        row.updating = false
      }
    }

    // 检查所有服务器状态
    const checkAllServers = async () => {
      checking.value = true
      try {
        const res = await serverApi.checkAllServers()
        if (res.code === 200) {
          ElMessage.success('所有服务器状态检查完成')
          fetchServers()
          fetchStatistics()
        }
      } catch (error) {
        ElMessage.error('检查失败: ' + error.message)
      } finally {
        checking.value = false
      }
    }

    // 处理启用状态变更
    const handleEnableChange = async (row) => {
      row.updating = true
      try {
        const res = await serverApi.updateServer(row.id, { isEnabled: row.isEnabled })
        if (res.code === 200) {
          ElMessage.success('状态更新成功')
          fetchStatistics()
        }
      } catch (error) {
        row.isEnabled = !row.isEnabled
        ElMessage.error('更新失败: ' + error.message)
      } finally {
        row.updating = false
      }
    }

    // 处理筛选变更
    const handleFilterChange = () => {
      fetchServers()
    }

    // 页面加载时获取数据
    onMounted(() => {
      fetchServers()
      fetchStatistics()
    })

    return {
      loading,
      checking,
      submitting,
      dialogVisible,
      isEdit,
      filterEnabled,
      servers,
      statistics,
      statisticsList,
      formData,
      formRules,
      formRef,
      getStatusType,
      getStatusText,
      showAddDialog,
      editServer,
      submitForm,
      deleteServer,
      setDefault,
      checkServer,
      checkAllServers,
      handleEnableChange,
      handleFilterChange
    }
  }
}
</script>

<style scoped>
