<template>
  <!-- 缓存管理页面 -->
  <div class="cache-manager-page">
    <!-- 页面标题 -->
    <div class="page-header">
      <h1 class="page-title">
        <el-icon><Box /></el-icon>
        缓存管理
      </h1>
      <div class="page-actions">
        <el-button type="danger" @click="clearAllCache">
          <el-icon><Delete /></el-icon>
          清空全部缓存
        </el-button>
        <el-button type="primary" @click="refreshCacheInfo">
          <el-icon><Refresh /></el-icon>
          刷新
        </el-button>
      </div>
    </div>

    <!-- 缓存统计卡片 -->
    <el-row :gutter="20" class="statistics-row">
      <el-col :span="6">
        <el-card class="stat-card">
          <div class="stat-value">{{ cacheStats.totalEntries }}</div>
          <div class="stat-label">总缓存条目</div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card class="stat-card">
          <div class="stat-value">{{ cacheStats.klineEntries }}</div>
          <div class="stat-label">K线缓存</div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card class="stat-card">
          <div class="stat-value">{{ cacheStats.quoteEntries }}</div>
          <div class="stat-label">行情缓存</div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card class="stat-card">
          <div class="stat-value">{{ formatSize(cacheStats.totalSize) }}</div>
          <div class="stat-label">缓存大小</div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 缓存操作区域 -->
    <el-row :gutter="20">
      <!-- K线缓存管理 -->
      <el-col :span="12">
        <el-card class="cache-card">
          <template #header>
            <div class="card-header">
              <span>K线缓存管理</span>
              <el-button type="primary" size="small" @click="showClearKlineDialog">
                清除指定缓存
              </el-button>
            </div>
          </template>

          <el-form :model="klineForm" label-width="80px">
            <el-form-item label="市场">
              <el-select v-model="klineForm.market" placeholder="选择市场">
                <el-option label="上海" value="SH" />
                <el-option label="深圳" value="SZ" />
              </el-select>
            </el-form-item>
            <el-form-item label="股票代码">
              <el-input v-model="klineForm.code" placeholder="输入股票代码" />
            </el-form-item>
            <el-form-item label="周期">
              <el-select v-model="klineForm.freq" placeholder="选择周期">
                <el-option label="1分钟" value="1min" />
                <el-option label="5分钟" value="5min" />
                <el-option label="15分钟" value="15min" />
                <el-option label="30分钟" value="30min" />
                <el-option label="60分钟" value="60min" />
                <el-option label="日线" value="day" />
                <el-option label="周线" value="week" />
                <el-option label="月线" value="month" />
                <el-option label="季线" value="quarter" />
                <el-option label="年线" value="year" />
              </el-select>
            </el-form-item>
            <el-form-item>
              <el-button type="danger" @click="clearKlineCache" :loading="clearing">
                清除缓存
              </el-button>
              <el-button @click="viewCacheInfo">查看缓存信息</el-button>
            </el-form-item>
          </el-form>
        </el-card>
      </el-col>

      <!-- 历史数据下载 -->
      <el-col :span="12">
        <el-card class="cache-card">
          <template #header>
            <div class="card-header">
              <span>历史数据下载</span>
            </div>
          </template>

          <el-form :model="downloadForm" label-width="80px">
            <el-form-item label="市场">
              <el-select v-model="downloadForm.market" placeholder="选择市场">
                <el-option label="上海" value="SH" />
                <el-option label="深圳" value="SZ" />
              </el-select>
            </el-form-item>
            <el-form-item label="股票代码">
              <el-input v-model="downloadForm.code" placeholder="输入股票代码" />
            </el-form-item>
            <el-form-item label="周期">
              <el-select v-model="downloadForm.freq" placeholder="选择周期">
                <el-option label="1分钟" value="1min" />
                <el-option label="5分钟" value="5min" />
                <el-option label="15分钟" value="15min" />
                <el-option label="30分钟" value="30min" />
                <el-option label="60分钟" value="60min" />
                <el-option label="日线" value="day" />
                <el-option label="周线" value="week" />
                <el-option label="月线" value="month" />
              </el-select>
            </el-form-item>
            <el-form-item label="数量">
              <el-slider v-model="downloadForm.limit" :min="100" :max="2000" :step="100" show-stops />
              <span class="limit-value">{{ downloadForm.limit }}条</span>
            </el-form-item>
            <el-form-item>
              <el-button type="primary" @click="downloadHistory" :loading="downloading">
                <el-icon><Download /></el-icon>
                下载数据
              </el-button>
            </el-form-item>
          </el-form>
        </el-card>
      </el-col>
    </el-row>

    <!-- 缓存条目列表 -->
    <el-card class="cache-list-card">
      <template #header>
        <div class="card-header">
          <span>缓存条目列表</span>
          <el-input
            v-model="searchKeyword"
            placeholder="搜索缓存键"
            style="width: 200px"
            clearable
            size="small"
          >
            <template #prefix>
              <el-icon><Search /></el-icon>
            </template>
          </el-input>
        </div>
      </template>

      <el-table :data="filteredCacheEntries" stripe border style="width: 100%">
        <el-table-column type="index" width="50" />
        <el-table-column prop="key" label="缓存键" min-width="200" show-overflow-tooltip />
        <el-table-column prop="type" label="类型" width="100">
          <template #default="{ row }">
            <el-tag :type="getTypeTag(row.type)" size="small">{{ row.type }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="size" label="大小" width="100">
          <template #default="{ row }">
            {{ formatSize(row.size) }}
          </template>
        </el-table-column>
        <el-table-column prop="createTime" label="创建时间" width="180" />
        <el-table-column prop="expireTime" label="过期时间" width="180" />
        <el-table-column label="操作" width="120" fixed="right">
          <template #default="{ row }">
            <el-button type="danger" size="small" @click="deleteCacheEntry(row)">
              删除
            </el-button>
          </template>
        </el-table-column>
      </el-table>

      <div class="pagination-footer">
        <el-pagination
          v-model:current-page="pagination.current"
          v-model:page-size="pagination.size"
          :page-sizes="[10, 20, 50, 100]"
          :total="filteredCacheEntries.length"
          layout="total, sizes, prev, pager, next"
        />
      </div>
    </el-card>

    <!-- 缓存信息对话框 -->
    <el-dialog v-model="infoDialogVisible" title="缓存信息" width="500px">
      <div v-if="selectedCache" class="cache-info">
        <p><strong>缓存键:</strong> {{ selectedCache.key }}</p>
        <p><strong>类型:</strong> {{ selectedCache.type }}</p>
        <p><strong>大小:</strong> {{ formatSize(selectedCache.size) }}</p>
        <p><strong>创建时间:</strong> {{ selectedCache.createTime }}</p>
        <p><strong>过期时间:</strong> {{ selectedCache.expireTime }}</p>
        <p><strong>数据条数:</strong> {{ selectedCache.count || '-' }}</p>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import { ref, reactive, computed, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Box, Delete, Refresh, Download, Search } from '@element-plus/icons-vue'
import { clearKlineCache as clearKlineCacheApi, getKlineData } from '@/api/stock'

export default {
  name: 'CacheManagerView',

  components: {
    Box,
    Delete,
    Refresh,
    Download,
    Search
  },

  setup() {
    // 加载状态
    const loading = ref(false)
    const clearing = ref(false)
    const downloading = ref(false)

    // 缓存统计
    const cacheStats = reactive({
      totalEntries: 0,
      klineEntries: 0,
      quoteEntries: 0,
      totalSize: 0
    })

    // K线缓存表单
    const klineForm = reactive({
      market: 'SZ',
      code: '',
      freq: 'day'
    })

    // 下载表单
    const downloadForm = reactive({
      market: 'SZ',
      code: '',
      freq: 'day',
      limit: 500
    })

    // 搜索关键词
    const searchKeyword = ref('')

    // 缓存条目列表
    const cacheEntries = ref([])

    // 分页
    const pagination = reactive({
      current: 1,
      size: 20
    })

    // 信息对话框
    const infoDialogVisible = ref(false)
    const selectedCache = ref(null)

    /**
     * 筛选后的缓存条目
     */
    const filteredCacheEntries = computed(() => {
      if (!searchKeyword.value) return cacheEntries.value
      return cacheEntries.value.filter(entry =>
        entry.key.toLowerCase().includes(searchKeyword.value.toLowerCase())
      )
    })

    /**
     * 刷新缓存信息
     */
    const refreshCacheInfo = () => {
      // 从localStorage获取缓存统计
      const klineCache = JSON.parse(localStorage.getItem('klineCache') || '{}')
      const quoteCache = JSON.parse(localStorage.getItem('quoteCache') || '{}')

      cacheStats.klineEntries = Object.keys(klineCache).length
      cacheStats.quoteEntries = Object.keys(quoteCache).length
      cacheStats.totalEntries = cacheStats.klineEntries + cacheStats.quoteEntries

      // 计算缓存大小
      cacheStats.totalSize = estimateSize(klineCache) + estimateSize(quoteCache)

      // 构建缓存条目列表
      cacheEntries.value = []

      Object.entries(klineCache).forEach(([key, value]) => {
        cacheEntries.value.push({
          key,
          type: 'K线',
          size: estimateSize(value),
          createTime: value.createTime || '-',
          expireTime: value.expireTime || '-',
          count: value.data?.length || 0
        })
      })

      Object.entries(quoteCache).forEach(([key, value]) => {
        cacheEntries.value.push({
          key,
          type: '行情',
          size: estimateSize(value),
          createTime: value.createTime || '-',
          expireTime: value.expireTime || '-'
        })
      })

      ElMessage.success('缓存信息已刷新')
    }

    /**
     * 估算对象大小
     */
    const estimateSize = (obj) => {
      const str = JSON.stringify(obj)
      return str ? str.length * 2 : 0 // 粗略估算：每个字符2字节
    }

    /**
     * 格式化大小
     */
    const formatSize = (bytes) => {
      if (bytes === 0) return '0 B'
      const k = 1024
      const sizes = ['B', 'KB', 'MB', 'GB']
      const i = Math.floor(Math.log(bytes) / Math.log(k))
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
    }

    /**
     * 显示清除K线对话框
     */
    const showClearKlineDialog = () => {
      klineForm.code = ''
    }

    /**
     * 清除K线缓存
     */
    const clearKlineCache = async () => {
      if (!klineForm.code) {
        ElMessage.warning('请输入股票代码')
        return
      }

      clearing.value = true
      try {
        const response = await clearKlineCacheApi(klineForm.market, klineForm.code, klineForm.freq)
        if (response.data.code === 200) {
          ElMessage.success('缓存清除成功')
          refreshCacheInfo()
        } else {
          ElMessage.error(response.data.message || '清除失败')
        }
      } catch (error) {
        ElMessage.error('清除缓存失败: ' + error.message)
      } finally {
        clearing.value = false
      }
    }

    /**
     * 查看缓存信息
     */
    const viewCacheInfo = () => {
      if (!klineForm.code) {
        ElMessage.warning('请输入股票代码')
        return
      }

      const cacheKey = `${klineForm.market}_${klineForm.code}_${klineForm.freq}`
      const klineCache = JSON.parse(localStorage.getItem('klineCache') || '{}')
      const cache = klineCache[cacheKey]

      if (cache) {
        selectedCache.value = {
          key: cacheKey,
          type: 'K线',
          size: estimateSize(cache),
          createTime: cache.createTime || '-',
          expireTime: cache.expireTime || '-',
          count: cache.data?.length || 0
        }
        infoDialogVisible.value = true
      } else {
        ElMessage.info('未找到该缓存')
      }
    }

    /**
     * 下载历史数据
     */
    const downloadHistory = async () => {
      if (!downloadForm.code) {
        ElMessage.warning('请输入股票代码')
        return
      }

      downloading.value = true
      try {
        const params = {
          freq: downloadForm.freq,
          limit: downloadForm.limit,
          forceRefresh: true
        }

        const response = await getKlineData(downloadForm.market, downloadForm.code, params)

        if (response.data.code === 200) {
          const data = response.data.data.data || []

          // 保存到本地存储
          const klineCache = JSON.parse(localStorage.getItem('klineCache') || '{}')
          klineCache[`${downloadForm.market}_${downloadForm.code}_${downloadForm.freq}`] = {
            data,
            createTime: new Date().toLocaleString(),
            expireTime: new Date(Date.now() + 24 * 60 * 60 * 1000).toLocaleString()
          }
          localStorage.setItem('klineCache', JSON.stringify(klineCache))

          ElMessage.success(`成功下载 ${data.length} 条数据`)
          refreshCacheInfo()
        } else {
          ElMessage.error(response.data.message || '下载失败')
        }
      } catch (error) {
        ElMessage.error('下载失败: ' + error.message)
      } finally {
        downloading.value = false
      }
    }

    /**
     * 清空全部缓存
     */
    const clearAllCache = () => {
      ElMessageBox.confirm(
        '确定要清空全部缓存吗？此操作不可恢复。',
        '警告',
        {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }
      ).then(() => {
        localStorage.removeItem('klineCache')
        localStorage.removeItem('quoteCache')
        localStorage.removeItem('stockList')
        localStorage.removeItem('watchList')

        refreshCacheInfo()
        ElMessage.success('全部缓存已清空')
      })
    }

    /**
     * 删除缓存条目
     */
    const deleteCacheEntry = (row) => {
      ElMessageBox.confirm(
        `确定要删除缓存 "${row.key}" 吗？`,
        '提示',
        { type: 'warning' }
      ).then(() => {
        if (row.type === 'K线') {
          const klineCache = JSON.parse(localStorage.getItem('klineCache') || '{}')
          delete klineCache[row.key]
          localStorage.setItem('klineCache', JSON.stringify(klineCache))
        } else {
          const quoteCache = JSON.parse(localStorage.getItem('quoteCache') || '{}')
          delete quoteCache[row.key]
          localStorage.setItem('quoteCache', JSON.stringify(quoteCache))
        }

        refreshCacheInfo()
        ElMessage.success('删除成功')
      })
    }

    /**
     * 获取类型标签样式
     */
    const getTypeTag = (type) => {
      switch (type) {
        case 'K线': return 'success'
        case '行情': return 'primary'
        default: return 'info'
      }
    }

    onMounted(() => {
      refreshCacheInfo()
    })

    return {
      loading,
      clearing,
      downloading,
      cacheStats,
      klineForm,
      downloadForm,
      searchKeyword,
      filteredCacheEntries,
      pagination,
      infoDialogVisible,
      selectedCache,
      refreshCacheInfo,
      formatSize,
      showClearKlineDialog,
      clearKlineCache,
      viewCacheInfo,
      downloadHistory,
      clearAllCache,
      deleteCacheEntry,
      getTypeTag
    }
  }
}
</script>

