<template>
  <!-- 股票列表页面 -->
  <div class="stock-list-page">
    <!-- 页面标题 -->
    <div class="page-header">
      <h1 class="page-title">
        <el-icon><List /></el-icon>
        股票列表
      </h1>
      <div class="page-actions">
        <el-button type="primary" @click="refreshList" :loading="loading">
          <el-icon><Refresh /></el-icon>
          刷新列表
        </el-button>
        <el-button @click="exportList">
          <el-icon><Download /></el-icon>
          导出列表
        </el-button>
      </div>
    </div>

    <!-- 统计信息 -->
    <el-row :gutter="20" class="statistics-row">
      <el-col :span="6">
        <el-card class="stat-card">
          <div class="stat-value">{{ statistics.total }}</div>
          <div class="stat-label">总股票数</div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card class="stat-card">
          <div class="stat-value">{{ statistics.shanghai }}</div>
          <div class="stat-label">上海市场</div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card class="stat-card">
          <div class="stat-value">{{ statistics.shenzhen }}</div>
          <div class="stat-label">深圳市场</div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card class="stat-card">
          <div class="stat-value">{{ statistics.updatedAt || '-' }}</div>
          <div class="stat-label">更新时间</div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 搜索和筛选 -->
    <el-card class="filter-card">
      <el-form :inline="true" :model="filterForm" class="filter-form">
        <el-form-item label="市场">
          <el-select v-model="filterForm.market" placeholder="全部市场" clearable style="width: 120px">
            <el-option label="上海" :value="1" />
            <el-option label="深圳" :value="0" />
          </el-select>
        </el-form-item>
        <el-form-item label="股票代码">
          <el-input v-model="filterForm.code" placeholder="输入代码" clearable style="width: 150px" />
        </el-form-item>
        <el-form-item label="股票名称">
          <el-input v-model="filterForm.name" placeholder="输入名称" clearable style="width: 150px" />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="handleSearch">
            <el-icon><Search /></el-icon>
            搜索
          </el-button>
          <el-button @click="handleReset">
            <el-icon><RefreshRight /></el-icon>
            重置
          </el-button>
        </el-form-item>
      </el-form>
    </el-card>

    <!-- 股票列表表格 -->
    <el-card class="table-card">
      <template #header>
        <div class="card-header">
          <span>股票列表</span>
          <el-pagination
            v-model:current-page="pagination.current"
            v-model:page-size="pagination.size"
            :page-sizes="[20, 50, 100, 200]"
            :total="filteredList.length"
            layout="total, sizes, prev, pager, next"
            @size-change="handleSizeChange"
            @current-change="handleCurrentChange"
          />
        </div>
      </template>

      <el-table
        :data="paginatedList"
        v-loading="loading"
        stripe
        border
        style="width: 100%"
        @row-click="handleRowClick"
        highlight-current-row
      >
        <el-table-column type="index" :index="getIndex" width="60" />
        <el-table-column prop="code" label="股票代码" width="100" sortable />
        <el-table-column prop="name" label="股票名称" width="150" sortable />
        <el-table-column label="市场" width="80">
          <template #default="{ row }">
            <el-tag :type="row.market === 1 ? 'success' : 'primary'" size="small">
              {{ row.market === 1 ? '上海' : '深圳' }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="280" fixed="right">
          <template #default="{ row }">
            <el-button type="primary" size="small" @click.stop="viewKline(row)">
              查看K线
            </el-button>
            <el-button type="warning" size="small" @click.stop="viewCompany(row)">
              F10资料
            </el-button>
            <el-button type="success" size="small" @click.stop="addToWatch(row)">
              加入自选
            </el-button>
          </template>
        </el-table-column>
      </el-table>

      <div class="pagination-footer">
        <el-pagination
          v-model:current-page="pagination.current"
          v-model:page-size="pagination.size"
          :page-sizes="[20, 50, 100, 200]"
          :total="filteredList.length"
          layout="total, sizes, prev, pager, next, jumper"
          @size-change="handleSizeChange"
          @current-change="handleCurrentChange"
        />
      </div>
    </el-card>
  </div>
</template>

<script>
import { ref, reactive, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { List, Refresh, Download, Search, RefreshRight } from '@element-plus/icons-vue'
import { getStockList } from '@/api/stock'

export default {
  name: 'StockListView',

  components: {
    List,
    Refresh,
    Download,
    Search,
    RefreshRight
  },

  setup() {
    const router = useRouter()
    
    // 加载状态
    const loading = ref(false)
    
    // 股票列表
    const stockList = ref([])
    
    // 筛选表单
    const filterForm = reactive({
      market: null,
      code: '',
      name: ''
    })
    
    // 分页
    const pagination = reactive({
      current: 1,
      size: 50
    })
    
    // 统计信息
    const statistics = reactive({
      total: 0,
      shanghai: 0,
      shenzhen: 0,
      updatedAt: null
    })

    /**
     * 筛选后的列表
     */
    const filteredList = computed(() => {
      return stockList.value.filter(stock => {
        if (filterForm.market !== null && filterForm.market !== undefined) {
          if (stock.market !== filterForm.market) return false
        }
        if (filterForm.code && !stock.code.includes(filterForm.code)) return false
        if (filterForm.name && !stock.name.includes(filterForm.name)) return false
        return true
      })
    })

    /**
     * 分页后的列表
     */
    const paginatedList = computed(() => {
      const start = (pagination.current - 1) * pagination.size
      const end = start + pagination.size
      return filteredList.value.slice(start, end)
    })

    /**
     * 获取股票列表
     */
    const fetchStockList = async () => {
      loading.value = true
      try {
        // 获取上海市场股票
        const shResponse = await getStockList(1)
        // 获取深圳市场股票
        const szResponse = await getStockList(0)
        
        const shStocks = shResponse.data.code === 200 ? shResponse.data.data : []
        const szStocks = szResponse.data.code === 200 ? szResponse.data.data : []
        
        // 合并列表
        stockList.value = [
          ...shStocks.map(s => ({ ...s, market: 1 })),
          ...szStocks.map(s => ({ ...s, market: 0 }))
        ]
        
        // 更新统计
        statistics.total = stockList.value.length
        statistics.shanghai = shStocks.length
        statistics.shenzhen = szStocks.length
        statistics.updatedAt = new Date().toLocaleString()
        
        // 保存到本地存储
        localStorage.setItem('stockList', JSON.stringify(stockList.value))
        localStorage.setItem('stockListUpdatedAt', statistics.updatedAt)
        
        ElMessage.success(`成功加载 ${stockList.value.length} 只股票`)
      } catch (error) {
        console.error('获取股票列表失败:', error)
        ElMessage.error('获取股票列表失败: ' + error.message)
        
        // 尝试从本地加载
        loadFromCache()
      } finally {
        loading.value = false
      }
    }

    /**
     * 从缓存加载
     */
    const loadFromCache = () => {
      const cached = localStorage.getItem('stockList')
      if (cached) {
        stockList.value = JSON.parse(cached)
        statistics.total = stockList.value.length
        statistics.shanghai = stockList.value.filter(s => s.market === 1).length
        statistics.shenzhen = stockList.value.filter(s => s.market === 0).length
        statistics.updatedAt = localStorage.getItem('stockListUpdatedAt')
        ElMessage.info('已从缓存加载股票列表')
      }
    }

    /**
     * 刷新列表
     */
    const refreshList = () => {
      fetchStockList()
    }

    /**
     * 导出列表
     */
    const exportList = () => {
      const data = filteredList.value.map(stock => ({
        代码: stock.code,
        名称: stock.name,
        市场: stock.market === 1 ? '上海' : '深圳'
      }))
      
      // 转换为CSV
      const headers = ['代码', '名称', '市场']
      const csvContent = [
        headers.join(','),
        ...data.map(row => headers.map(h => row[h]).join(','))
      ].join('\n')
      
      // 下载文件
      const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' })
      const link = document.createElement('a')
      link.href = URL.createObjectURL(blob)
      link.download = `股票列表_${new Date().toISOString().split('T')[0]}.csv`
      link.click()
      
      ElMessage.success('导出成功')
    }

    /**
     * 搜索
     */
    const handleSearch = () => {
      pagination.current = 1
    }

    /**
     * 重置
     */
    const handleReset = () => {
      filterForm.market = null
      filterForm.code = ''
      filterForm.name = ''
      pagination.current = 1
    }

    /**
     * 处理分页大小变化
     */
    const handleSizeChange = (size) => {
      pagination.size = size
      pagination.current = 1
    }

    /**
     * 处理页码变化
     */
    const handleCurrentChange = (page) => {
      pagination.current = page
    }

    /**
     * 获取序号
     */
    const getIndex = (index) => {
      return (pagination.current - 1) * pagination.size + index + 1
    }

    /**
     * 查看K线
     */
    const viewKline = (row) => {
      router.push({
        path: '/kline',
        query: {
          market: row.market === 1 ? 'SH' : 'SZ',
          code: row.code
        }
      })
    }

    /**
     * 查看F10资料
     */
    const viewCompany = (row) => {
      router.push({
        path: '/company',
        query: {
          market: row.market === 1 ? 'SH' : 'SZ',
          code: row.code
        }
      })
    }

    /**
     * 加入自选
     */
    const addToWatch = (row) => {
      const watchList = JSON.parse(localStorage.getItem('watchList') || '[]')
      const exists = watchList.find(item => item.code === row.code)
      
      if (exists) {
        ElMessage.warning('该股票已在自选股中')
        return
      }
      
      watchList.push({
        code: row.code,
        name: row.name,
        market: row.market === 1 ? 'SH' : 'SZ'
      })
      
      localStorage.setItem('watchList', JSON.stringify(watchList))
      ElMessage.success(`已将 ${row.name} 加入自选股`)
    }

    /**
     * 处理行点击
     */
    const handleRowClick = (row) => {
      viewKline(row)
    }

    onMounted(() => {
      // 优先从缓存加载
      loadFromCache()
      
      // 如果缓存为空或超过1小时，重新获取
      const updatedAt = localStorage.getItem('stockListUpdatedAt')
      if (!updatedAt || (new Date() - new Date(updatedAt)) > 3600000) {
        fetchStockList()
      }
    })

    return {
      loading,
      filterForm,
      pagination,
      statistics,
      filteredList,
      paginatedList,
      refreshList,
      exportList,
      handleSearch,
      handleReset,
      handleSizeChange,
      handleCurrentChange,
      getIndex,
      viewKline,
      viewCompany,
      addToWatch,
      handleRowClick
    }
  }
}
</script>

