<template>
  <!-- 联系信息面板组件 - 展示公司联系相关信息 -->
  <div class="contact-panel">
    <!-- 地址信息 -->
    <el-row :gutter="20" class="contact-section">
      <el-col :span="12">
        <el-card class="contact-card" shadow="hover">
          <template #header>
            <div class="card-header">
              <el-icon><Location /></el-icon>
              <span>注册地址</span>
            </div>
          </template>
          <div class="address-content">
            <p v-if="data.registeredAddress">{{ data.registeredAddress }}</p>
            <el-empty v-else description="暂无注册地址信息" />
          </div>
        </el-card>
      </el-col>
      <el-col :span="12">
        <el-card class="contact-card" shadow="hover">
          <template #header>
            <div class="card-header">
              <el-icon><OfficeBuilding /></el-icon>
              <span>办公地址</span>
            </div>
          </template>
          <div class="address-content">
            <p v-if="data.officeAddress">{{ data.officeAddress }}</p>
            <el-empty v-else description="暂无办公地址信息" />
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 联系方式 -->
    <el-card class="contact-methods" shadow="hover">
      <template #header>
        <div class="card-header">
          <el-icon><Phone /></el-icon>
          <span>联系方式</span>
        </div>
      </template>

      <el-row :gutter="20">
        <el-col :span="8" v-for="item in contactMethods" :key="item.key">
          <div class="method-item" :class="{ 'has-value': item.value }">
            <div class="method-icon">
              <el-icon :size="24">
                <component :is="item.icon" />
              </el-icon>
            </div>
            <div class="method-info">
              <div class="method-label">{{ item.label }}</div>
              <div class="method-value">
                <template v-if="item.value">
                  <el-link
                    v-if="item.type === 'link'"
                    :href="item.href"
                    target="_blank"
                    type="primary"
                  >
                    {{ item.value }}
                  </el-link>
                  <el-link
                    v-else-if="item.type === 'email'"
                    :href="'mailto:' + item.value"
                    type="primary"
                  >
                    {{ item.value }}
                  </el-link>
                  <el-link
                    v-else-if="item.type === 'phone'"
                    :href="'tel:' + item.value"
                    type="primary"
                  >
                    {{ item.value }}
                  </el-link>
                  <span v-else>{{ item.value }}</span>
                </template>
                <span v-else class="no-value">暂无信息</span>
              </div>
            </div>
          </div>
        </el-col>
      </el-row>
    </el-card>

    <!-- 公司信息汇总 -->
    <el-card class="company-summary" shadow="hover">
      <template #header>
        <div class="card-header">
          <el-icon><InfoFilled /></el-icon>
          <span>公司信息汇总</span>
        </div>
      </template>

      <el-descriptions :column="2" border>
        <el-descriptions-item label="公司全称" :span="2">
          {{ data.fullName || '-' }}
        </el-descriptions-item>
        <el-descriptions-item label="英文名称" :span="2">
          {{ data.englishName || '-' }}
        </el-descriptions-item>
        <el-descriptions-item label="股票代码">
          {{ data.code }}
        </el-descriptions-item>
        <el-descriptions-item label="所属市场">
          {{ data.marketName }}
        </el-descriptions-item>
        <el-descriptions-item label="所属行业">
          {{ data.industry || '-' }}
        </el-descriptions-item>
        <el-descriptions-item label="上市日期">
          {{ data.listingDate || '-' }}
        </el-descriptions-item>
        <el-descriptions-item label="邮政编码">
          {{ data.postalCode || '-' }}
        </el-descriptions-item>
        <el-descriptions-item label="公司网址">
          <el-link
            v-if="data.website"
            :href="formatWebsite(data.website)"
            target="_blank"
            type="primary"
          >
            {{ data.website }}
          </el-link>
          <span v-else>-</span>
        </el-descriptions-item>
      </el-descriptions>
    </el-card>

    <!-- 投资者关系提示 -->
    <el-card class="investor-tips" shadow="hover">
      <template #header>
        <div class="card-header">
          <el-icon><Bell /></el-icon>
          <span>投资者关系提示</span>
        </div>
      </template>
      <el-alert
        title="联系公司"
        type="info"
        :closable="false"
        show-icon
      >
        <template #default>
          <p>如需了解更多公司信息，可通过以下方式联系：</p>
          <ul>
            <li>投资者热线：{{ data.phone || '暂无信息' }}</li>
            <li>电子邮箱：{{ data.email || '暂无信息' }}</li>
            <li>公司官网：{{ data.website || '暂无信息' }}</li>
          </ul>
        </template>
      </el-alert>
    </el-card>
  </div>
</template>

<script>
import { computed } from 'vue'
import { Location, OfficeBuilding, Phone, Message, Link as LinkIcon, InfoFilled, Bell } from '@element-plus/icons-vue'

export default {
  name: 'ContactPanel',

  components: {
    Location,
    OfficeBuilding,
    Phone,
    Message,
    LinkIcon,
    InfoFilled,
    Bell
  },

  props: {
    data: {
      type: Object,
      required: true
    }
  },

  setup(props) {
    /**
     * 联系方式列表
     */
    const contactMethods = computed(() => [
      {
        key: 'phone',
        label: '联系电话',
        value: props.data.phone,
        icon: 'Phone',
        type: 'phone'
      },
      {
        key: 'fax',
        label: '传真',
        value: props.data.fax,
        icon: 'Message',
        type: 'text'
      },
      {
        key: 'email',
        label: '电子邮箱',
        value: props.data.email,
        icon: 'Message',
        type: 'email'
      },
      {
        key: 'website',
        label: '公司网址',
        value: props.data.website,
        icon: 'Link',
        type: 'link',
        href: formatWebsite(props.data.website)
      },
      {
        key: 'postalCode',
        label: '邮政编码',
        value: props.data.postalCode,
        icon: 'Location',
        type: 'text'
      }
    ])

    /**
     * 格式化网址
     */
    function formatWebsite(url) {
      if (!url) return ''
      if (url.startsWith('http')) return url
      return 'http://' + url
    }

    return {
      contactMethods,
      formatWebsite
    }
  }
}
</script>

