/**
 * 题材检索API接口
 * 提供题材搜索、导入、查询等功能
 */
import axios from 'axios';

const API_BASE_URL = process.env.VUE_APP_API_URL || 'http://localhost:8080';

/**
 * 从mark.dat文件导入题材数据
 * @param {Array} filePaths 文件路径列表
 * @returns {Promise} 导入结果
 */
export function importThemes(filePaths) {
  return axios.post(`${API_BASE_URL}/api/themes/import`, { filePaths });
}

/**
 * 获取默认导入路径
 * @returns {Promise} 路径信息
 */
export function getImportPath() {
  return axios.get(`${API_BASE_URL}/api/themes/import-path`);
}

/**
 * 获取所有题材列表
 * @returns {Promise} 题材列表
 */
export function getThemeList() {
  return axios.get(`${API_BASE_URL}/api/themes/list`);
}

/**
 * 获取热门题材（前20个）
 * @returns {Promise} 热门题材列表
 */
export function getHotThemes() {
  return axios.get(`${API_BASE_URL}/api/themes/hot`);
}

/**
 * 搜索题材
 * @param {string} keyword 搜索关键词
 * @returns {Promise} 匹配的题材列表
 */
export function searchThemes(keyword) {
  return axios.get(`${API_BASE_URL}/api/themes/search`, {
    params: { keyword }
  });
}

/**
 * 获取指定题材下的股票列表
 * @param {string} themeId 题材ID
 * @returns {Promise} 股票列表
 */
export function getThemeStocks(themeId) {
  return axios.get(`${API_BASE_URL}/api/themes/${themeId}/stocks`);
}

/**
 * 获取无题材的股票列表
 * @returns {Promise} 无题材股票列表
 */
export function getNoThemeStocks() {
  return axios.get(`${API_BASE_URL}/api/themes/no-theme/stocks`);
}

/**
 * 获取指定股票的题材信息
 * @param {string} market 市场代码(SH/SZ/BJ)
 * @param {string} code 股票代码
 * @returns {Promise} 股票题材信息
 */
export function getStockThemes(market, code) {
  return axios.get(`${API_BASE_URL}/api/themes/stock/${market}/${code}`);
}
