<template>
  <div class="scheduler-manager-container">
    <h1>定时任务管理</h1>

    <!-- 操作栏 -->
    <div class="operation-bar">
      <el-button type="primary" @click="refreshData">
        <el-icon><Refresh /></el-icon> 刷新
      </el-button>
    </div>

    <!-- 定时任务列表 -->
    <el-table :data="taskList" v-loading="loading" border stripe>
      <el-table-column type="index" width="50" />
      <el-table-column prop="taskName" label="任务名称" width="150" />
      <el-table-column prop="description" label="任务描述" min-width="250" />
      <el-table-column label="执行频率" width="150">
        <template #default="{ row }">
          <span v-if="row.fixedRate">{{ formatDuration(row.fixedRate) }}</span>
          <span v-else-if="row.cronExpression">{{ row.cronExpression }}</span>
          <span v-else>-</span>
        </template>
      </el-table-column>
      <el-table-column label="状态" width="100">
        <template #default="{ row }">
          <el-tag :type="row.enabled ? 'success' : 'danger'">
            {{ row.enabled ? '已启用' : '已禁用' }}
          </el-tag>
        </template>
      </el-table-column>
      <el-table-column prop="lastExecuteTime" label="最后执行时间" width="180" />
      <el-table-column prop="lastExecuteResult" label="最后执行结果" width="150" />
      <el-table-column prop="executeCount" label="执行次数" width="100" />
      <el-table-column label="操作" width="300" fixed="right">
        <template #default="{ row }">
          <el-button
            v-if="!row.enabled"
            type="success"
            size="small"
            @click="handleEnable(row)"
          >
            启用
          </el-button>
          <el-button
            v-else
            type="warning"
            size="small"
            @click="handleDisable(row)"
          >
            禁用
          </el-button>
          <el-button type="primary" size="small" @click="showEditRateDialog(row)">
            修改频率
          </el-button>
          <el-button type="info" size="small" @click="handleExecute(row)">
            立即执行
          </el-button>
        </template>
      </el-table-column>
    </el-table>

    <!-- 修改频率对话框 -->
    <el-dialog v-model="editRateDialog.visible" title="修改执行频率" width="400px">
      <el-form :model="editRateDialog.form" label-width="100px">
        <el-form-item label="任务名称">
          <span>{{ editRateDialog.task?.taskName }}</span>
        </el-form-item>
        <el-form-item label="执行频率">
          <el-input-number
            v-model="editRateDialog.form.fixedRate"
            :min="1000"
            :step="1000"
            style="width: 150px"
          />
          <span class="unit">毫秒</span>
        </el-form-item>
        <el-form-item>
          <div class="rate-presets">
            <el-button size="small" @click="setRate(10000)">10秒</el-button>
            <el-button size="small" @click="setRate(30000)">30秒</el-button>
            <el-button size="small" @click="setRate(60000)">1分钟</el-button>
            <el-button size="small" @click="setRate(300000)">5分钟</el-button>
            <el-button size="small" @click="setRate(600000)">10分钟</el-button>
          </div>
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="editRateDialog.visible = false">取消</el-button>
        <el-button type="primary" @click="handleUpdateRate">确定</el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref, reactive, onMounted } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Refresh } from '@element-plus/icons-vue'
import {
  getAllTasks,
  enableTask,
  disableTask,
  updateTaskRate,
  executeTaskImmediately
} from '@/api/scheduler'

// ==================== 数据状态 ====================
const loading = ref(false)
const taskList = ref([])

const editRateDialog = reactive({
  visible: false,
  task: null,
  form: {
    fixedRate: 60000
  }
})

// ==================== 生命周期 ====================
onMounted(() => {
  loadTasks()
})

// ==================== 加载数据 ====================
async function loadTasks() {
  loading.value = true
  try {
    const res = await getAllTasks()
    if (res.data.code === 200) {
      const tasks = res.data.data
      taskList.value = Object.values(tasks)
    } else {
      ElMessage.error(res.data.message || '加载失败')
    }
  } catch (error) {
    console.error('加载定时任务失败:', error)
    ElMessage.error('加载定时任务失败')
  } finally {
    loading.value = false
  }
}

function refreshData() {
  loadTasks()
  ElMessage.success('数据已刷新')
}

// ==================== 操作处理 ====================
async function handleEnable(row) {
  try {
    const res = await enableTask(row.taskId)
    if (res.data.code === 200) {
      ElMessage.success('启用成功')
      loadTasks()
    } else {
      ElMessage.error(res.data.message || '启用失败')
    }
  } catch (error) {
    console.error('启用任务失败:', error)
    ElMessage.error('启用任务失败')
  }
}

async function handleDisable(row) {
  try {
    await ElMessageBox.confirm(
      `确定要禁用任务 "${row.taskName}" 吗？禁用后将不再自动执行。`,
      '提示',
      {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }
    )

    const res = await disableTask(row.taskId)
    if (res.data.code === 200) {
      ElMessage.success('禁用成功')
      loadTasks()
    } else {
      ElMessage.error(res.data.message || '禁用失败')
    }
  } catch (error) {
    if (error !== 'cancel') {
      console.error('禁用任务失败:', error)
      ElMessage.error('禁用任务失败')
    }
  }
}

function showEditRateDialog(row) {
  editRateDialog.task = row
  editRateDialog.form.fixedRate = row.fixedRate || 60000
  editRateDialog.visible = true
}

function setRate(rate) {
  editRateDialog.form.fixedRate = rate
}

async function handleUpdateRate() {
  try {
    const res = await updateTaskRate(
      editRateDialog.task.taskId,
      editRateDialog.form.fixedRate
    )
    if (res.data.code === 200) {
      ElMessage.success('修改频率成功')
      editRateDialog.visible = false
      loadTasks()
    } else {
      ElMessage.error(res.data.message || '修改失败')
    }
  } catch (error) {
    console.error('修改频率失败:', error)
    ElMessage.error('修改频率失败')
  }
}

async function handleExecute(row) {
  try {
    await ElMessageBox.confirm(
      `确定要立即执行任务 "${row.taskName}" 吗？`,
      '提示',
      {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'info'
      }
    )

    const res = await executeTaskImmediately(row.taskId)
    if (res.data.code === 200) {
      ElMessage.success('任务执行成功')
      loadTasks()
    } else {
      ElMessage.error(res.data.message || '执行失败')
    }
  } catch (error) {
    if (error !== 'cancel') {
      console.error('执行任务失败:', error)
      ElMessage.error('执行任务失败')
    }
  }
}

// ==================== 工具函数 ====================
function formatDuration(ms) {
  if (ms < 1000) {
    return ms + '毫秒'
  } else if (ms < 60000) {
    return (ms / 1000) + '秒'
  } else if (ms < 3600000) {
    return (ms / 60000) + '分钟'
  } else {
    return (ms / 3600000) + '小时'
  }
}
</script>

<style scoped>
.scheduler-manager-container {
  padding: 20px;
}

.operation-bar {
  margin-bottom: 20px;
}

.unit {
  margin-left: 10px;
  color: #666;
}

.rate-presets {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
</style>
