<template>
  <div class="stock-theme-page">
    <!-- 页面标题 -->
    <div class="page-header">
      <h1 class="page-title">
        <el-icon size="28"><CollectionTag /></el-icon>
        题材检索
      </h1>
      <p class="page-desc">搜索和浏览股票题材标签，支持从通达信mark.dat导入</p>
    </div>

    <!-- 搜索栏 -->
    <div class="search-section">
      <el-input
        v-model="searchKeyword"
        placeholder="搜索题材名称..."
        clearable
        size="large"
        class="search-input"
        @keyup.enter="handleSearch"
      >
        <template #prefix>
          <el-icon><Search /></el-icon>
        </template>
      </el-input>
      <el-button type="primary" size="large" @click="handleSearch" :loading="loading">
        <el-icon><Search /></el-icon>
        搜索
      </el-button>
      <el-button size="large" @click="resetSearch">
        <el-icon><RefreshRight /></el-icon>
        重置
      </el-button>
      <el-button type="success" size="large" @click="showImportDialog">
        <el-icon><Upload /></el-icon>
        导入数据
      </el-button>
    </div>

    <!-- 热门题材标签云 -->
    <div class="hot-themes-section" v-if="!searchKeyword && hotThemes.length > 0">
      <div class="section-title">
        <el-icon><HotWater /></el-icon>
        热门题材
        <el-tag type="info" size="small">TOP 20</el-tag>
      </div>
      <div class="tag-cloud">
        <el-tag
          v-for="theme in hotThemes"
          :key="theme.themeId"
          :style="getTagStyle(theme)"
          class="theme-tag"
          effect="light"
          @click="selectTheme(theme)"
        >
          {{ theme.themeName }}
          <span class="stock-count">({{ theme.stockCount }})</span>
        </el-tag>
      </div>
    </div>

    <!-- 主内容区：左右分栏 -->
    <div class="main-content">
      <!-- 左侧：题材列表 -->
      <div class="left-panel">
        <div class="panel-header">
          <div class="header-left">
            <el-icon><List /></el-icon>
            <span>题材列表</span>
            <el-tag v-if="filteredThemes.length" type="info" size="small">
              {{ filteredThemes.length }}
            </el-tag>
          </div>
        </div>

        <div class="theme-list" v-loading="loading">
          <!-- 无题材选项 -->
          <div
            class="theme-item no-theme"
            :class="{ active: selectedTheme?.themeId === 'NO_THEME' }"
            @click="selectNoTheme"
          >
            <div class="theme-item-header">
              <el-icon><Warning /></el-icon>
              <span class="theme-name">无题材</span>
            </div>
            <div class="theme-item-info">
              <span class="stock-count">{{ noThemeCount }} 只股票</span>
            </div>
          </div>

          <!-- 题材列表 -->
          <div
            v-for="theme in filteredThemes"
            :key="theme.themeId"
            class="theme-item"
            :class="{ active: selectedTheme?.themeId === theme.themeId }"
            @click="selectTheme(theme)"
          >
            <div class="theme-item-header">
              <span
                class="color-dot"
                :style="{ backgroundColor: theme.color || '#409EFF' }"
              ></span>
              <span class="theme-name">{{ theme.themeName }}</span>
            </div>
            <div class="theme-item-info">
              <span class="stock-count">{{ theme.stockCount }} 只股票</span>
              <span v-if="theme.themeKeywords" class="keywords">{{ theme.themeKeywords }}</span>
            </div>
          </div>
        </div>
      </div>

      <!-- 右侧：股票列表 -->
      <div class="right-panel">
        <div class="panel-header">
          <div class="header-left">
            <el-icon><TrendCharts /></el-icon>
            <span>{{ selectedTheme ? selectedTheme.themeName : '请选择题材' }}</span>
            <el-tag v-if="themeStocks.length" type="info" size="small">
              {{ themeStocks.length }}
            </el-tag>
          </div>
        </div>

        <div class="stock-list" v-loading="stockLoading">
          <el-table
            :data="themeStocks"
            stripe
            style="width: 100%"
            v-if="themeStocks.length > 0"
          >
            <el-table-column prop="code" label="代码" width="100" sortable />
            <el-table-column prop="market" label="市场" width="80">
              <template #default="{ row }">
                <el-tag :type="getMarketType(row.market)" size="small">
                  {{ row.market }}
                </el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="name" label="名称" width="120" />
            <el-table-column prop="industry" label="行业" width="120" />
            <el-table-column prop="detail" label="题材描述" show-overflow-tooltip />
          </el-table>

          <el-empty
            v-else
            description="请选择左侧题材查看股票列表"
          />
        </div>
      </div>
    </div>

    <!-- 导入对话框 -->
    <el-dialog
      v-model="importDialogVisible"
      title="导入题材数据"
      width="600px"
    >
      <el-form :model="importForm" label-width="120px">
        <el-form-item label="默认路径">
          <el-input
            v-model="defaultPath"
            disabled
            :suffix-icon="defaultPathExists ? 'Check' : 'Close'"
          />
          <div class="path-status" :class="{ exists: defaultPathExists }">
            {{ defaultPathExists ? '文件存在' : '文件不存在' }}
          </div>
        </el-form-item>
        <el-form-item label="自定义路径">
          <el-input
            v-model="importForm.customPath"
            placeholder="可选：输入自定义mark.dat路径"
          />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="importDialogVisible = false">取消</el-button>
        <el-button type="primary" @click="handleImport" :loading="importLoading">
          开始导入
        </el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script>
import { ref, onMounted } from 'vue';
import { ElMessage } from 'element-plus';
import {
  Search,
  RefreshRight,
  Upload,
  CollectionTag,
  HotWater,
  List,
  TrendCharts,
  Warning
} from '@element-plus/icons-vue';
import {
  getThemeList,
  getHotThemes,
  searchThemes,
  getThemeStocks,
  getNoThemeStocks,
  importThemes,
  getImportPath
} from '../api/stockTheme';

export default {
  name: 'StockTheme',
  components: {
    Search,
    RefreshRight,
    Upload,
    CollectionTag,
    HotWater,
    List,
    TrendCharts,
    Warning
  },
  setup() {
    // 搜索相关
    const searchKeyword = ref('');
    const loading = ref(false);
    const stockLoading = ref(false);

    // 题材数据
    const allThemes = ref([]);
    const hotThemes = ref([]);
    const filteredThemes = ref([]);
    const selectedTheme = ref(null);
    const themeStocks = ref([]);
    const noThemeCount = ref(0);

    // 导入相关
    const importDialogVisible = ref(false);
    const importLoading = ref(false);
    const defaultPath = ref('');
    const defaultPathExists = ref(false);
    const importForm = ref({
      customPath: ''
    });

    // 获取标签样式（根据股票数量调整大小）
    const getTagStyle = (theme) => {
      const count = theme.stockCount || 0;
      let fontSize = 14;
      let padding = '6px 12px';

      if (count >= 100) {
        fontSize = 18;
        padding = '8px 16px';
      } else if (count >= 50) {
        fontSize = 16;
        padding = '7px 14px';
      }

      return {
        fontSize: `${fontSize}px`,
        padding,
        backgroundColor: theme.color ? `${theme.color}20` : '#409EFF20',
        borderColor: theme.color || '#409EFF',
        color: theme.color || '#409EFF'
      };
    };

    // 获取市场标签类型
    const getMarketType = (market) => {
      const types = {
        'SH': 'danger',
        'SZ': 'success',
        'BJ': 'warning'
      };
      return types[market] || 'info';
    };

    // 加载题材列表
    const loadThemes = async () => {
      loading.value = true;
      try {
        const response = await getThemeList();
        if (response.data && response.data.code === 200) {
          allThemes.value = response.data.data || [];
          filteredThemes.value = allThemes.value;
        }
      } catch (error) {
        ElMessage.error('加载题材列表失败');
        console.error(error);
      } finally {
        loading.value = false;
      }
    };

    // 加载热门题材
    const loadHotThemes = async () => {
      try {
        const response = await getHotThemes();
        if (response.data && response.data.code === 200) {
          hotThemes.value = response.data.data || [];
        }
      } catch (error) {
        console.error('加载热门题材失败', error);
      }
    };

    // 搜索题材
    const handleSearch = async () => {
      if (!searchKeyword.value.trim()) {
        filteredThemes.value = allThemes.value;
        return;
      }

      loading.value = true;
      try {
        const response = await searchThemes(searchKeyword.value.trim());
        if (response.data && response.data.code === 200) {
          filteredThemes.value = response.data.data || [];
        }
      } catch (error) {
        ElMessage.error('搜索失败');
        console.error(error);
      } finally {
        loading.value = false;
      }
    };

    // 重置搜索
    const resetSearch = () => {
      searchKeyword.value = '';
      filteredThemes.value = allThemes.value;
      selectedTheme.value = null;
      themeStocks.value = [];
    };

    // 选择题材
    const selectTheme = async (theme) => {
      selectedTheme.value = theme;
      stockLoading.value = true;
      try {
        const response = await getThemeStocks(theme.themeId);
        if (response.data && response.data.code === 200) {
          themeStocks.value = response.data.data.stocks || [];
        }
      } catch (error) {
        ElMessage.error('加载股票列表失败');
        console.error(error);
      } finally {
        stockLoading.value = false;
      }
    };

    // 选择无题材
    const selectNoTheme = async () => {
      selectedTheme.value = {
        themeId: 'NO_THEME',
        themeName: '无题材'
      };
      stockLoading.value = true;
      try {
        const response = await getNoThemeStocks();
        if (response.data && response.data.code === 200) {
          themeStocks.value = response.data.data.stocks || [];
          noThemeCount.value = response.data.data.stockCount || 0;
        }
      } catch (error) {
        ElMessage.error('加载无题材股票失败');
        console.error(error);
      } finally {
        stockLoading.value = false;
      }
    };

    // 显示导入对话框
    const showImportDialog = async () => {
      try {
        const response = await getImportPath();
        if (response.data && response.data.code === 200) {
          defaultPath.value = response.data.data.defaultPath;
          defaultPathExists.value = response.data.data.exists;
        }
      } catch (error) {
        console.error('获取导入路径失败', error);
      }
      importDialogVisible.value = true;
    };

    // 处理导入
    const handleImport = async () => {
      importLoading.value = true;
      try {
        const filePaths = [];
        if (defaultPathExists.value) {
          filePaths.push(defaultPath.value);
        }
        if (importForm.value.customPath) {
          filePaths.push(importForm.value.customPath);
        }

        if (filePaths.length === 0) {
          ElMessage.warning('请至少指定一个有效的文件路径');
          return;
        }

        const response = await importThemes(filePaths);
        if (response.data && response.data.code === 200) {
          const result = response.data.data;
          ElMessage.success(result.message || '导入成功');
          importDialogVisible.value = false;
          // 刷新数据
          loadThemes();
          loadHotThemes();
        } else {
          ElMessage.error(response.data?.message || '导入失败');
        }
      } catch (error) {
        ElMessage.error('导入失败');
        console.error(error);
      } finally {
        importLoading.value = false;
      }
    };

    // 组件挂载时加载数据
    onMounted(() => {
      loadThemes();
      loadHotThemes();
      // 预加载无题材股票数量
      getNoThemeStocks().then(response => {
        if (response.data && response.data.code === 200) {
          noThemeCount.value = response.data.data.stockCount || 0;
        }
      }).catch(() => {});
    });

    return {
      searchKeyword,
      loading,
      stockLoading,
      allThemes,
      hotThemes,
      filteredThemes,
      selectedTheme,
      themeStocks,
      noThemeCount,
      importDialogVisible,
      importLoading,
      defaultPath,
      defaultPathExists,
      importForm,
      getTagStyle,
      getMarketType,
      handleSearch,
      resetSearch,
      selectTheme,
      selectNoTheme,
      showImportDialog,
      handleImport
    };
  }
};
</script>

