<template>
  <!-- 股东研究面板组件 - 展示公司股东相关信息 -->
  <div class="shareholders-panel">
    <!-- 股东统计概览 -->
    <el-row :gutter="20" class="shareholder-stats">
      <el-col :span="8">
        <el-card class="stat-card" shadow="hover">
          <div class="stat-icon" style="background: #409eff;">
            <el-icon><User /></el-icon>
          </div>
          <div class="stat-content">
            <div class="stat-label">股东总数</div>
            <div class="stat-value">{{ formatNumber(data.totalShareholders) }}</div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="8">
        <el-card class="stat-card" shadow="hover">
          <div class="stat-icon" style="background: #67c23a;">
            <el-icon><OfficeBuilding /></el-icon>
          </div>
          <div class="stat-content">
            <div class="stat-label">机构股东</div>
            <div class="stat-value">{{ formatNumber(data.institutionalShareholders) }}</div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="8">
        <el-card class="stat-card" shadow="hover">
          <div class="stat-icon" style="background: #e6a23c;">
            <el-icon><TrendCharts /></el-icon>
          </div>
          <div class="stat-content">
            <div class="stat-label">人均持股</div>
            <div class="stat-value">{{ calculateAvgShares() }}</div>
          </div>
        </el-card>
      </el-col>
    </el-row>

    <!-- 十大流通股东 -->
    <el-card class="top-shareholders" shadow="hover">
      <template #header>
        <div class="card-header">
          <div class="header-title">
            <el-icon><Trophy /></el-icon>
            <span>十大流通股东</span>
          </div>
          <el-tag v-if="data.top10Shareholders && data.top10Shareholders.length > 0" type="info">
            共 {{ data.top10Shareholders.length }} 位
          </el-tag>
        </div>
      </template>

      <el-table
        v-if="data.top10Shareholders && data.top10Shareholders.length > 0"
        :data="data.top10Shareholders"
        style="width: 100%"
        stripe
        border
      >
        <el-table-column type="index" label="排名" width="80" align="center">
          <template #default="{ $index }">
            <el-tag
              :type="$index < 3 ? 'danger' : 'info'"
              effect="dark"
              size="small"
            >
              {{ $index + 1 }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="name" label="股东名称" min-width="200" show-overflow-tooltip />
        <el-table-column prop="type" label="类型" width="100" align="center">
          <template #default="{ row }">
            <el-tag :type="getShareholderTypeType(row.type)" size="small">
              {{ row.type || '未知' }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="sharesFormatted" label="持股数量" width="150" align="right" />
        <el-table-column prop="ratioFormatted" label="持股比例" width="120" align="right">
          <template #default="{ row }">
            <el-progress
              :percentage="parseFloat(row.ratio) || 0"
              :color="getProgressColor(row.ratio)"
              :show-text="false"
              :stroke-width="8"
              style="width: 80px; display: inline-block; margin-right: 8px;"
            />
            {{ row.ratioFormatted }}
          </template>
        </el-table-column>
        <el-table-column prop="change" label="变动情况" width="120" align="center">
          <template #default="{ row }">
            <el-tag
              v-if="row.change"
              :type="getChangeType(row.change)"
              size="small"
            >
              {{ row.change }}
            </el-tag>
            <span v-else>-</span>
          </template>
        </el-table-column>
      </el-table>

      <el-empty v-else description="暂无十大流通股东数据" />
    </el-card>

    <!-- 股东变化趋势 -->
    <el-card class="shareholder-trend" shadow="hover">
      <template #header>
        <div class="card-header">
          <el-icon><DataLine /></el-icon>
          <span>股东集中度分析</span>
        </div>
      </template>

      <el-row :gutter="20">
        <el-col :span="12">
          <div ref="concentrationChart" class="chart-container"></div>
        </el-col>
        <el-col :span="12">
          <div class="concentration-analysis">
            <h4>分析说明</h4>
            <el-descriptions :column="1" border>
              <el-descriptions-item label="筹码集中度">
                {{ calculateConcentration() }}
              </el-descriptions-item>
              <el-descriptions-item label="机构持仓比例">
                {{ calculateInstitutionalRatio() }}
              </el-descriptions-item>
              <el-descriptions-item label="股东人数趋势">
                {{ analyzeShareholderTrend() }}
              </el-descriptions-item>
            </el-descriptions>

            <div class="analysis-tips">
              <el-alert
                title="投资提示"
                type="info"
                :closable="false"
                show-icon
              >
                <template #default>
                  <p>• 股东人数减少通常意味着筹码集中，有利于股价上涨</p>
                  <p>• 机构增持表明专业机构看好公司发展前景</p>
                  <p>• 需结合其他财务指标综合判断</p>
                </template>
              </el-alert>
            </div>
          </div>
        </el-col>
      </el-row>
    </el-card>
  </div>
</template>

<script>
import { ref, onMounted, onUnmounted } from 'vue'
import { User, OfficeBuilding, TrendCharts, Trophy, DataLine } from '@element-plus/icons-vue'
import * as echarts from 'echarts'

export default {
  name: 'ShareholdersPanel',

  components: {
    User,
    OfficeBuilding,
    TrendCharts,
    Trophy,
    DataLine
  },

  props: {
    data: {
      type: Object,
      required: true
    }
  },

  setup(props) {
    const concentrationChart = ref(null)
    let chartInstance = null

    /**
     * 格式化数字
     */
    const formatNumber = (num) => {
      if (num === null || num === undefined) return '-'
      if (num >= 10000) {
        return (num / 10000).toFixed(2) + '万'
      }
      return num.toString()
    }

    /**
     * 计算人均持股
     */
    const calculateAvgShares = () => {
      const total = props.data.totalShares
      const shareholders = props.data.totalShareholders
      if (!total || !shareholders || shareholders === 0) return '-'
      const avg = total / shareholders
      if (avg >= 10000) {
        return (avg / 10000).toFixed(2) + '万股'
      }
      return Math.round(avg) + '股'
    }

    /**
     * 获取股东类型样式
     */
    const getShareholderTypeType = (type) => {
      const typeMap = {
        '个人': '',
        '机构': 'success',
        '基金': 'warning',
        '社保': 'danger',
        'QFII': 'info'
      }
      return typeMap[type] || ''
    }

    /**
     * 获取进度条颜色
     */
    const getProgressColor = (ratio) => {
      const val = parseFloat(ratio) || 0
      if (val > 10) return '#f56c6c'
      if (val > 5) return '#e6a23c'
      return '#409eff'
    }

    /**
     * 获取变动类型
     */
    const getChangeType = (change) => {
      if (change.includes('增加')) return 'success'
      if (change.includes('减少')) return 'danger'
      if (change.includes('新进')) return 'warning'
      return 'info'
    }

    /**
     * 计算筹码集中度
     */
    const calculateConcentration = () => {
      const shareholders = props.data.top10Shareholders
      if (!shareholders || shareholders.length === 0) return '暂无数据'

      const top5Ratio = shareholders
        .slice(0, 5)
        .reduce((sum, s) => sum + (parseFloat(s.ratio) || 0), 0)

      if (top5Ratio > 50) return '高度集中 (' + top5Ratio.toFixed(2) + '%)'
      if (top5Ratio > 30) return '中度集中 (' + top5Ratio.toFixed(2) + '%)'
      return '相对分散 (' + top5Ratio.toFixed(2) + '%)'
    }

    /**
     * 计算机构持仓比例
     */
    const calculateInstitutionalRatio = () => {
      const shareholders = props.data.top10Shareholders
      if (!shareholders || shareholders.length === 0) return '暂无数据'

      const institutionalRatio = shareholders
        .filter(s => s.type && (s.type.includes('机构') || s.type.includes('基金') || s.type.includes('社保')))
        .reduce((sum, s) => sum + (parseFloat(s.ratio) || 0), 0)

      return institutionalRatio.toFixed(2) + '%'
    }

    /**
     * 分析股东趋势
     */
    const analyzeShareholderTrend = () => {
      // 这里可以根据历史数据判断，目前简化处理
      return '数据不足，无法判断'
    }

    /**
     * 初始化集中度图表
     */
    const initConcentrationChart = () => {
      if (!concentrationChart.value) return

      chartInstance = echarts.init(concentrationChart.value)

      const shareholders = props.data.top10Shareholders || []
      const data = shareholders.map((s) => ({
        name: s.name.length > 10 ? s.name.substring(0, 10) + '...' : s.name,
        value: parseFloat(s.ratio) || 0
      }))

      const option = {
        title: {
          text: '前十大股东持股比例',
          left: 'center'
        },
        tooltip: {
          trigger: 'axis',
          axisPointer: { type: 'shadow' }
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '3%',
          containLabel: true
        },
        xAxis: {
          type: 'value',
          axisLabel: { formatter: '{value}%' }
        },
        yAxis: {
          type: 'category',
          data: data.map(d => d.name).reverse(),
          axisLabel: { width: 120, overflow: 'truncate' }
        },
        series: [
          {
            name: '持股比例',
            type: 'bar',
            data: data.map(d => d.value).reverse(),
            itemStyle: {
              color: new echarts.graphic.LinearGradient(0, 0, 1, 0, [
                { offset: 0, color: '#83bff6' },
                { offset: 0.5, color: '#188df0' },
                { offset: 1, color: '#188df0' }
              ])
            },
            label: {
              show: true,
              position: 'right',
              formatter: '{c}%'
            }
          }
        ]
      }

      chartInstance.setOption(option)
    }

    /**
     * 处理窗口大小变化
     */
    const handleResize = () => {
      if (chartInstance) {
        chartInstance.resize()
      }
    }

    onMounted(() => {
      initConcentrationChart()
      window.addEventListener('resize', handleResize)
    })

    onUnmounted(() => {
      window.removeEventListener('resize', handleResize)
      if (chartInstance) {
        chartInstance.dispose()
      }
    })

    return {
      concentrationChart,
      formatNumber,
      calculateAvgShares,
      getShareholderTypeType,
      getProgressColor,
      getChangeType,
      calculateConcentration,
      calculateInstitutionalRatio,
      analyzeShareholderTrend
    }
  }
}
</script>

